INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('10659', 'NXGN-5013', 'Foundations in Youth Ministry', 'This course prepares students for contextual ministry with young people and their families. Students will examine biblical and theological foundations for youth ministry, and how identity, belonging, and discipleship are shaped across diverse contexts. Students will explore application of youth ministry models in different contexts, how to foster a culture of leadership development, and reflect on how ministry environments can encourage the spiritual growth and well-being of young people.', 'NXGN', 3, 0, 5, '[]');
