INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('10662', 'NXGN-6043', 'Reach & Retaining Young Adults', 'This course will examine the changing young adult (18-30) culture. Through examining demographic and developmental issues, students will explore ministry implications for local churches. Various models will be introduced as students are taught how to develop effective and contextualized young adult ministries. Cross-listed as EVAN 6043.', 'NXGN', 3, 0, 6, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('10663', 'NXGN-6063', 'Children''s Ministry', 'This course considers the importance of children''s ministry in the local church, examining different approaches and philosophies. It also explores the important role of theology as it relates to children''s ministry, including how it shapes both its purpose and practice. The course will encourage students to think purposefully and contextually about children''s ministry while examining key environments for faith formation, ways to support children with diverse needs and backgrounds, as well as examining curriculum.', 'NXGN', 3, 0, 6, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('10664', 'NXGN-6083', 'Camping Ministry', 'This course examines camping ministry by considering a variety of camping ministry models and the theological rationale undergirding each model. A focus on understanding children and youth campers will include a review of typical stages of development and faith formation. Students are introduced to camp leadership topics including: staffing, programming, the business side of camp and the skills needed for camp leadership. The course explores the role camp plays in evangelism, discipleship, and leadership development of children and youth, as well as the potential benefit to the child, church and community. Cross-listed as LEDR 6083.', 'NXGN', 3, 0, 6, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('10665', 'NXGN-7013', 'Counselling Adolescents & Fam', 'Addictions, eating disorders, self-injury, sexual choices, media saturation, sexual abuse, family breakdown, anxiety, depression, and suicide - these are the dark realities that mark the lives of many young people today. This class is designed to address a number of these contemporary behavioural, emotional, and relational issues faced by new millennium adolescents. It is meant to prepare the student for increased ministry effectiveness through a deeper awareness of underlying issues affecting adolescents and their families today. Students will develop a greater level of freedom in addressing and discussing these issues with both adolescents themselves and adults who intersect with the adolescent world. Cross-listed as PACC 7013. Recommended prior study: PACC 5013', 'NXGN', 3, 0, 7, '[{"codes":["PACC-5013"],"textExtension":"- Recommended prior to taking this course, but is not required."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('10666', 'NXGN-7213', 'Spec Top: Next Gen Ministry', 'Specialized courses in Next Generation Ministry offered from time to time.', 'NXGN', 3, 0, 7, '[]');
