INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('11337', 'PSYC-2123', 'Personality', 'Section Restrictions - 01 and 03 for PSYC majors , 02 and 04 for non-PSYC majors.
