INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('11969', 'THEA-PF00', 'Practice: Performance', 'This non-credit course is designed to train students in various capacities through their participation in productions directed by Theatre faculty. Students will receive training in minor or major roles. Registration is scheduled after the beginning of each term. The course can be repeated for the equivalent of six non-credit hours.', 'THEA', 0, 0, 0, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('11973', 'THEA-1483', 'Introduction to Theatre', 'This course provides students with a practical introduction to the basic principles of acting and performance. Open to non-majors.', 'THEA', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('11976', 'THEA-PD00', 'Practice: Production', 'This non-credit course is designed to train students in various capacities through their participation in productions directed by Theatre faculty. Students will receive training in skills such as stage management, publicity, lighting, sound, wardrobe, props, or set construction. Registration is scheduled after the beginning of each term. The course can be repeated for the equivalent of six non-credit hours.', 'THEA', 0, 0, 0, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('11980', 'THEA-2213', 'Acting & Performance 1', 'Development of the basic principles of performance and acting. Prerequisite(s): THEA 1483 and Theatre major or permission of the Theatre faculty.', 'THEA', 3, 0, 2, '[{"codes":["THEA-1483","and","theatre","major","or","permission","of","the","Department"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('11981', 'THEA-2223', 'Acting & Performance 2', 'Continuing development of the basic principles of performance and acting. Prerequisite(s): THEA 2213.', 'THEA', 3, 0, 2, '[{"codes":["THEA-2213"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('11986', 'THEA-2753', 'Performance Voice and Speech 1', 'Introductory exploration of voice and speech for the performer. Prerequisite(s): No prerequisites for non-majors; THEA 1483 and ENGL 1483/ ENGL 1493 (ENGL 1413/ENGL 1423 or ENGL 1406) with a minimum grade of C- for majors.', 'THEA', 3, 0, 2, '[{"codes":["THEA-1483","and","ENGL-1406","or","THEA-1483","and","ENGL-1413","and","ENGL-1423","or","THEA-1483","and","ENGL-1483","and","ENGL-1493","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('11987', 'THEA-2763', 'Performance Voice and Speech 2', 'Continued exploration of voice and speech for the performer. Prerequisite(s): No prerequisites for non-majors; THEA 1483 and ENGL 1483/ ENGL 1493 (ENGL 1413/ENGL 1423 or ENGL 1406) with a minimum grade of C- for majors.', 'THEA', 3, 0, 2, '[{"codes":["THEA-1483","and","ENGL-1406","or","THEA-1483","and","ENGL-1413","and","ENGL-1423","or","THEA-1483","and","ENGL-1493","and","ENGL-1493","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('11988', 'THEA-2803', 'Topics in Film', 'An introduction to the language and critical vocabulary of narrative and non-narrative film. Mandatory weekly screenings outside of class time. Prerequisite(s): THEA 1483 and ENGL 1483/ ENGL 1493 (ENGL 1413/ENGL 1423 or ENGL 1406) with a minimum grade of C- for majors.', 'THEA', 3, 0, 2, '[{"codes":["THEA-1483","and","ENGL-1406","or","THEA-1483","and","ENGL-1413","and","ENGL-1423","or","THEA-1483","and","ENGL-1483","and","ENGL-1493","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('11989', 'THEA-2813', 'Advanced Topics in Film', 'Advanced study of the formal and stylistic systems of narrative and non-narrative film. Mandatory weekly screenings outside of class time. Prerequisite(s): THEA 2803 or permission of the instructor.', 'THEA', 3, 0, 2, '[{"codes":["THEA-2803","or","permission","of","the","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('11991', 'THEA-2823', 'Introduction to Production 1', 'An introduction to production in the theatre. Basic production elements and procedures will be examined including theatre forms and stage management and two of the following - sets, scenic painting, properties, lighting, sound and costumes. This course includes classroom and practical, physical work in the theatre to develop basic skills. Clothing appropriate for work and safety is necessary. Open to non-majors. Course must be taken in both Fall and Winter terms to receive credit.', 'THEA', 1.5, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('11992', 'THEA-2833', 'Introduction to Production 2', 'An introduction to production in the theatre. Complementary to THEA 2823. Basic production elements and procedures will be examined from four of the following - sets, scenic painting, properties, lighting, sound and costumes. This course includes classroom and practical, physical work in the theatre to develop basic skills. Clothing appropriate for work and safety is necessary. Open to non-majors.', 'THEA', 3, 0, 2, '[{"codes":["THEA-2823"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('11993', 'THEA-2853', 'Theatre Movement 1', 'The goal of this course is to learn movement skills but also life skills. We live in our bodies so why not get to know them better? Course work is geared to developing body awareness, self-confidence, better posture, strength & flexibility.  We will also introduce self-expression and creative use of physicality.', 'THEA', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('11995', 'THEA-2863', 'Theatre Movement 2', 'This course will build movement vocabulary and creative use of physicality. Through embodied anatomy we will become aware of movement patterns and habits. The goal is to achieve a greater range of physical and emotional expression. Application of movement skills to text or scenes is introduced.', 'THEA', 3, 0, 2, '[{"codes":["THEA-2853","or","permission","of","the","instructor."],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('11997', 'THEA-2883', 'Theatre Hist: Origins-Pre-Mod', 'An examination of performance practice in world cultures from the origins of performance to the end of the pre-modern era. Prerequisite(s): THEA 1483 and ENGL 1483/ ENGL 1493 (ENGL 1413/ENGL 1423 or ENGL 1406) with a minimum grade of C- for majors.', 'THEA', 3, 0, 2, '[{"codes":["THEA-1483","and","ENGL-1406","or","THEA-1483","and","ENGL-1413","and","ENGL-1423","or","THEA-1483","and","ENGL-1483","and","ENGL-1493","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('11998', 'THEA-2893', 'Theatre Hist: Pre-Mod. to Pres', 'An examination of performance practice in world cultures from the pre-modern to the present. Prerequisite(s): THEA 1483 and ENGL 1483/ ENGL 1493 (ENGL 1413/ENGL 1423 or ENGL 1406) with a minimum grade of C- for majors.', 'THEA', 3, 0, 2, '[{"codes":["THEA-1483","and","ENGL-1406","or","THEA-1483","and","ENGL-1413","and","ENGL-1423","or","THEA-1483","and","ENGL-1483","and","ENGL-1493","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12003', 'THEA-3133', 'Playwriting', 'This course introduces the student to the principles of playwriting through an analysis of plays in various genres and the use of texts on dramatic theory. Students will work through projects assigned by the instructor, and are expected to submit proposals to MiniFest. Class work and the completion of a short play determine the student''s mark in the course. Prerequisite(s): THEA 1483 and ENGL 1483/ ENGL 1493 (ENGL 1413/ENGL 1423 or ENGL 1406) with a minimum grade of C- for majors.', 'THEA', 3, 0, 3, '[{"codes":["THEA-1483","and","ENGL-1406","or","THEA-1483","and","ENGL-1413","and","ENGL-1423","or","THEA-1483","and","ENGL-1483","and","ENGL-1493","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12004', 'THEA-3243', 'Dramaturgy', 'The processes and functions of dramaturgy will be examined in both a practical and theoretical context. Students will learn how to apply critical discourse to text analysis, performance and theatre systems in a manner which reflects the practical needs and working etiquette of the theatre. Dramaturgs will be assigned to work in the Acadia Theatre Company''s productions. Prerequisite(s): THEA 1483 and ENGL 1483/ ENGL 1493 (ENGL 1413/ENGL 1423 or ENGL 1406) with a minimum grade of C- for majors.', 'THEA', 3, 0, 3, '[{"codes":["THEA-1483","and","ENGL-1406","or","THEA-1483","and","ENGL-1413","and","ENGL-1423","or","THEA-1483","and","ENGL-1483","and","ENGL-1493","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12005', 'THEA-3313', 'Acting & Performance 3', 'Intermediate development and training in performance and acting. Prerequisite(s): THEA 2223 or permission of the instructor.', 'THEA', 3, 0, 3, '[{"codes":["THEA-2223","or","permission","of","the","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12006', 'THEA-3323', 'Acting & Performance 4', 'Continued intermediate development and training in performance and acting. Prerequisite(s): THEA 3313 or permission of the instructor.', 'THEA', 3, 0, 3, '[{"codes":["THEA-3313","or","permission","of","the","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12009', 'THEA-3853', 'Theatre Movement 3', 'This course integrates and applies movement skills which can continue to be used in other classes and going forward in your life.  Students will develop a personal warm-up strategy. We will work with creative process and explore applications to specific performance or presentation needs of each student.', 'THEA', 3, 0, 3, '[{"codes":["THEA-2853","or","THEA-2863","or","permission","of","the","instructor."],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12010', 'THEA-3863', 'Dance in History and Culture', 'This is a studio course that introduces students to the evolution of social and concert dance in Europe and North America. We will also look at social dance in other cultures as time and opportunity permit. Although dance history will be covered, the primary focus of this course is experiential learning - in other words, dancing! No prerequisite.', 'THEA', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12012', 'THEA-3883', 'Mod Drama Theat: Ibsen to WW2', 'British, European, and North American dramatic literature and theatrical practice from the birth of modern drama to the middle of the 20th century. May be taken for English credit. Prerequisite(s): THEA 1483 and ENGL 1483/ ENGL 1493 (ENGL 1413/ENGL 1423 or ENGL 1406) with a minimum grade of C- for majors.', 'THEA', 3, 0, 3, '[{"codes":["THEA-1483","and","ENGL-1406","or","THEA-1483","and","ENGL-1413","and","ENGL-1423","or","THEA-1483","and","ENGL-1483","and","ENGL-1493","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12013', 'THEA-3893', 'Mod. Drama/Theatre: WW2-Pres', 'British, European, and North American dramatic literature and theatrical practice from mid-20th century to the present. May be taken for English credit. Prerequisite(s): THEA 1483 and ENGL 1483/ ENGL 1493 (ENGL 1413/ENGL 1423 or ENGL 1406) with a minimum grade of C- for majors.', 'THEA', 3, 0, 3, '[{"codes":["THEA-1483","and","ENGL-1406","or","THEA-1483","and","ENGL-1413","and","ENGL-1423","or","THEA-1483","and","ENGL-1483","and","ENGL-1493","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12014', 'THEA-3923', 'Canadian Drama and Film', 'Contemporary theory and practice: an exploration of dramatic and cinematic aesthetics using contemporary Canadian texts and films. Prerequisite(s): (ENGL 1483/ ENGL 1493) or (ENGL 1413/ENGL 1423) or (ENGL 1406) with a minimum grade of C-.', 'THEA', 3, 0, 3, '[{"codes":["ENGL-1406","or","ENGL-1413","and","ENGL-1423","or","ENGL-1483","and","ENGL-1493","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12015', 'THEA-3973', 'Women and Theatre', 'An historical survey of women working in and for the theatre as performers, playwrights, directors and designers. THEA 1483 and ENGL 1483/ ENGL 1493 (ENGL 1413/ENGL 1423 or ENGL 1406) with a minimum grade of C- for majors.', 'THEA', 3, 0, 3, '[{"codes":["THEA-1483","and","ENGL-1406","or","THEA-1483","and","ENGL-1413","and","ENGL-1423","or","THEA-1483","and","ENGL-1483","and","ENGL-1493","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12018', 'THEA-4013', 'Special Topics in Theatre 1', 'Independent study in acting and performance, directing, playwriting, dramaturgy, research, or movement. Prerequisite(s): THEA 1483 and ENGL 1406 (ENGL 1413/ENGL 1423) with a minimum grade of C-, and permission of the Theatre faculty.', 'THEA', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12019', 'THEA-4023', 'Special Topics in Theatre 2', 'Independent study in acting and performance, directing, playwriting, dramaturgy, research, or movement. Prerequisite(s): THEA 1483 and ENGL 1406 (ENGL 1413/ENGL 1423) with a minimum grade of C-, and permission of the Theatre faculty.', 'THEA', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12020', 'THEA-4313', 'Performed Violence 1', 'Unarmed and non-bladed techniques in the illusion of violence for performance, at an internationally recognized certification 350 level. Prerequisite(s): No prerequisite for non-majors; THEA 1483 and ENGL 1406 (ENGL 1413/ENGL 1423) with a minimum grade of C- for majors.', 'THEA', 3, 0, 4, '[{"codes":["THEA-1483","and","ENGL-1406","or","THEA-1483","and","ENGL-1413","and","ENGL-1423","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12021', 'THEA-4323', 'Performed Violence 2', 'Bladed techniques in the illusion of violence for performance, at an internationally recognized certification level. Prerequisite(s): No prerequisite for non-majors; THEA 1483 and ENGL 1406 (ENGL 1413/ENGL 1423) with a minimum grade of C- for majors.', 'THEA', 3, 0, 4, '[{"codes":["THEA-1483","and","ENGL-1406","or","THEA-1483","and","ENGL-1413","and","ENGL-1423","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12022', 'THEA-4413', 'Acting and Performance 5', 'Advanced techniques and development in training for performance and acting. Prerequisite(s): Theatre Major with THEA 3323 or permission of the instructor.', 'THEA', 3, 0, 4, '[{"codes":["THEA-3323","or","permission","of","the","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12023', 'THEA-4423', 'Acting and Performance 6', 'Continued advanced techniques and development in training for performance and acting. Prerequisite(s): Theatre Major with THEA 4413 or permission of the instructor.', 'THEA', 3, 0, 4, '[{"codes":["THEA-4413","or","permission","of","the","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12024', 'THEA-4833', 'Theatre Ideas 1', 'Ideas that have changed how societies think about and practice theatre, with a focus on their contemporary relevance. Topics include ideas in scenic design, playwriting, acting and audience reception, from the Greeks to the dawn of modern theatre. Prerequisite(s): THEA 1483 and ENGL 1406 (ENGL 1413/ENGL 1423), each with a minimum grade of C-.', 'THEA', 3, 0, 4, '[{"codes":["THEA-1483","and","ENGL-1406","or","THEA-1483","and","ENGL-1413","and","ENGL-1423","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12025', 'THEA-4843', 'Theatre Ideas 2', 'Ideas that have changed how societies think about and practice theatre, with a focus on their contemporary relevance. Topics include ideas in scenic design, playwriting, acting and audience reception, from Naturalism to current international theatre practice. Prerequisite(s): THEA 1483 and ENGL 1406 (ENGL 1483/ENGL 1493) or ENGL 1413/ENGL 1423 or ENGL), each with a minimum grade of C-.', 'THEA', 3, 0, 4, '[{"codes":["THEA-1483","and","ENGL-1406","or","THEA-1483","and","ENGL-1483/ENGL-1493","or","THEA-1483","and","ENGL-1413/ENGL-1423","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12026', 'THEO-3013', 'Intro to Christian Theology 1', 'An introduction to Christian doctrine and theological inquiry. This first course in theology will begin with a discussion of theological method followed by a survey of the Christian doctrines of God, revelation, creation, and humanity. These doctrines will be studied by focusing on their relevance to contemporary issues faced by church and society.', 'THEO', 3, 0, 3, '[{"codes":["BIBL-2053","and","THEO-3003"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12027', 'THEO-3023', 'Christian Theology 2', 'A survey of the Christian doctrines of the person and work of Christ, the person and work of the Holy Spirit, salvation, the Church, and Last Times. These doctrines will be studied by focusing on their relevance to contemporary issues faced by church and society.', 'THEO', 3, 0, 3, '[{"codes":["THEO-3013"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12028', 'THEO-3033', 'Christian Ethics', 'An introduction to basic issues in Christian ethics faced by individuals and society today. The course will help students to develop an ethical approach to difficult problems, moral dilemmas, and the development of a personal ethical framework that is Christian in context. Issues to be explored include race/ethnicity, sexuality, bioethics, the environment, peace and justice, and global concerns/human rights.', 'THEO', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12031', 'THEO-4213', 'Spec Topics: Pastoral Ministry', 'Specialized courses in Pastoral Ministry offered from time to time.', 'THEO', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12032', 'THEO-4223', 'Spec Topics: Pastoral Ministry', 'Specialized courses in Pastoral Ministry offered from time to time.', 'THEO', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12033', 'THEO-4233', 'Spec Topics: Pastoral Ministry', 'Specialized courses in Pastoral Ministry offered from time to time.', 'THEO', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12034', 'THEO-5013', 'Christian Theology I', 'An introduction to Christian doctrine and theological inquiry. Students will become familiar with theological methods and approaches to the use of biblical data, theological literature, and personal transformation in shaping their theological identities. This first course in Theology will focus upon prolegomena and the doctrines of God (including revelation), Christ, and Holy Spirit. An overall Trinitarian orientation will be developed through the image of an integrated web rather than traditional vertical categories or silos. Various theological sub-disciplines will be used, including biblical, historical, and systematic approaches and priority will be given to evangelical emphases.', 'THEO', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12035', 'THEO-5023', 'Christian Theology II', 'This course will focus on doctrinal areas of humanity, sin (including evil and theodicy), salvation, the church, and last things. Students will become familiar with various theologians of the contemporary era and the application of theological method to specific projects and questions. Methods observed and employed will give attention to biblical, historical, and systematic theological approaches with emphasis upon evangelical responses to theological issues.', 'THEO', 3, 0, 5, '[{"codes":["THEO-5013"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12036', 'THEO-5503', 'Theology I: Indigenous Perspec', 'This course is a theological reflection focused on the concept of community. It will examine the Christian doctrines of creation, fall, and redemption, identifying God''s community-creating purpose in the world. Other issues examined include evil and the fall in their spiritual and cosmic dimensions, ecology and the cultural mandate. The course will include understandings of the nature and origins of community as portrayed within Indigenous cosmologies and spiritual perspectives. This course is normally taught by an Indigenous instructor. This course is normally available only to students enrolled in the MA-INCD program.', 'THEO', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12038', 'THEO-6013', 'Christian Ethics', 'An introduction to the methods and processes of Christian moral concerns and appropriate responses. In the context of classical thinkers and schools, the range of Christian ethics will be presented, with special attention to categories of ethical inquiry such as race/ethnicity, sexuality, bioethics, the environment, peace and justice, and global concerns/human rights, especially from a Canadian perspective. In developing blended strategies for decision-making (deontological, teleological, character ethics, etc.), priority will be given to the use of key biblical texts and viewing the church as an ethical community. Recommended prior study: THEO 5013, 5023', 'THEO', 3, 0, 6, '[{"codes":["THEO-5013","and","THEO-5023"],"textExtension":"- Recommended prior to taking this course, but is not required."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12053', 'THEO-6503', 'Theo II:Theo & Ethnic of Land', 'The course will help students to develop an integrated understanding of God, humanity and culture focusing on current debates and their bearing on Christian mission and community. Practical issues such as the relationship between the sacred and the secular, the role of art, the place of work and leisure, and the significance of political engagement will receive particular attention in juxtaposition with Indigenous perspectives in each area. This course is normally taught by an Indigenous instructor.', 'THEO', 3, 0, 6, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12054', 'THEO-6513', 'Ethics Intercultural Context', 'An intercultural and contextual introduction to central issues in Christian ethics, with attention to the way in which moral reflection interacts with philosophy and culture. The course explores biblical-theological foundations for ethics, the role of scripture and Jesus'' example in ethical formulation, and deals with major contemporary topics including gender, sexuality, marriage, euthanasia, war, bioethics, wealth, and poverty. This course is normally taught by an Indigenous instructor.', 'THEO', 3, 0, 6, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12055', 'THEO-6523', 'Creation and Transformation', 'The centre of Christian theology is Jesus Christ who unites Creator and creation. Therefore, this course will focus on the scriptural and ecclesiastical traditions concerning the person and work of Christ in transforming creation. This will provide the basis for a discussion about the implication of Christology for the transformation of creation community. Thus, the course will seek to engage the ideas represented by the councils, creeds of past theologians, and then move to examine the theological praxis that resulted in a colonial and post-colonial context. This course is normally taught by an Indigenous instructor.', 'THEO', 3, 0, 6, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12057', 'THEO-7013', 'Theo in First Five Centuries', 'A seminar in the development of Christian theology in the first through the fifth centuries. Using major writers and primary texts in translation, themes such as church, ministry, the sacraments/ordinances, community, and authority will be examined. Major emphasis upon the doctrines of Christ and Trinity in debates and conciliar discussions. Students will explore the approaches suggested by the work of W.H.C. Frend, W. Meeks, J. Pelikan, A. McGrath, R. Williams, T. Oden, and G. R. Evans. Attention will be given to the emergence of orthodox and non-orthodox interpretations. Prerequisite: Completion of, or concurrent enrolment in, THEO 5013 and CHUR 5013, or permission of instructor.', 'THEO', 3, 0, 7, '[{"codes":["THEO-5013","and","CHUR-5013","or","permission","of","the","instructor"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12059', 'THEO-7023', 'Theology of the Reformers', 'Seminar in the several theological traditions that emerged in the reforming movements of the 15th and 16th centuries: Lollardry, Hussite, Lutheran, Reformed (Zwingli and Calvin), Radical/Anabaptists, Anglican, and Catholic (Erasmus and St. Therese). Leading theologians will be examined in context, and the importance of emerging confessions will be underscored. Major thinkers to be used for essay orientation and analysis include: R. Bainton, S. Ozment; G.H. Williams; H. Oberman; C. Lindberg; and H. Hillerbrand. Prerequisite: Completion of, or concurrent enrolment in, THEO 5013 or 5023, and CHUR 5013, or permission of instructor.', 'THEO', 3, 0, 7, '[{"codes":["THEO-5013","or","THEO-5023","and","CHUR-5013","or","permission","of","the","instructor"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12061', 'THEO-7033', 'Contemporary Theology', 'Seminar focused on Post-Enlightenment theological trends comprising the discussion at present. Categories include 19th century Liberalism, rise of Evangelicalism and Fundamentalism, Neo-Orthodoxy, Neo-Evangelicalism, Radical Theology, Post-Foundationalism, Process Theology, Paleo-Orthodoxy, Radical Orthodoxy, Pentecostal voices, and the critiques of New Atheism and Non-Theism. Prerequisite: Completion of, or concurrent enrolment in, THEO 5013 or 5023, and CHUR 5013, or permission of instructor.', 'THEO', 3, 0, 7, '[{"codes":["THEO-5013","or","THEO-5023","and","CHUR-5013","or","permission","of","the","instructor"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12062', 'THEO-7043', 'Christology:Person&Work Jesus', 'A foundational seminar in the development of theological thought about the person and work of Jesus Christ. Biblical themes from Hebrew prophecies and the narratives of the New Testament include (Christology from below): birth and infancy; Jesus'' teaching as a rabbi; work in healing; crucifixion and resurrection; post-resurrection; ascension; and parousia. These themes will be integrated with doctrinal categories (including Christology from above) like: the pre-existent Christ with the Father; Christ in Creation; the two natures of Christ; Christ and the Spirit; the Saviour as atonement for sin; Christ as Judge, Christ in the church and sacraments/ordinances; the Lordship of Christ; the finality of Christ; and the Eternal Christ. Major recent Christological theologians for this course include K. Barth; R. Aldwinckle; W. Pannenberg; E. Schillebeeckx; P. Knitter; N.T. Wright; R. E. Brown; D. Migliore; and C. E. Gunton. Prerequisite: Completion of, or concurrent enrolment in, THEO 5013 or 5023, and BIBL 5023, 5033, or permission of instructor.', 'THEO', 3, 0, 7, '[{"codes":["THEO-5013","or","THEO-5023","and","BIBL-5023","and","BIBL-5033","or","permission","of","the","instructor"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12063', 'THEO-7053', 'Holy Spirit', 'Seminar in the doctrine of the Holy Spirit that first plumbs the theological history of discussion of the person and work of the Holy Spirit. Key biblical texts will be addressed. This will include early church, medieval, Radical Reformation, and contemporary Pentecostal and Charismatic contributions. Attention will be given to the fruit and gifts of the Holy Spirit, the Spirit in the nurture of believers (sanctification), spirituality in the Church, the Spirit''s work in human culture, and overall in creation and consummation. , Contemporary literature that will orient student work include: L.S. Chafer; G. Fee; J. Dunn; D. Bloesch; D. Dayton; H. Cox; W. Pannenberg; C. H. Pinnock; G. Atter; J. Wimber; and W. & J. Menzies. Prerequisite: Completion of, or concurrent enrolment in, THEO 5013, and BIBL 5023, 5033, or permission of instructor.', 'THEO', 3, 0, 7, '[{"codes":["THEO-5013,","BIBL-5023","and","BIBL-5033","or","permission","of","the","instructor"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12065', 'THEO-7063', 'Eschatology', 'Seminar in various approaches to the doctrine of last things. Using eschatological issues as basic human questions, students will work with categories of Christian eschatological discourse: death, resurrection, judgment, Jesus Christ, consummation, and eternal life. In addition to gathering biblical data (including the apocalyptic and messianic traditions), attention will be given to evaluating various schools of interpretation, including: chiliasm, the Augustinian model, Joachimism, covenantal theology, dispensationalism, Barthianism, realized eschatology, kingdom thought, theology of hope, logical positivism, eco-eschatology, the Orthodox and Catholic traditions, Process thinking, and nihilism. The historic creeds will provide a frame of reference for building an authentically Christian eschatology. Prerequisite: Completion of, or concurrent enrolment in, THEO 5023, BIBL 5023 and 5033, or permission of instructor.', 'THEO', 3, 0, 7, '[{"codes":["THEO-5023","and","BIBL-5023","and","BIBL-5033","or","permission","of","the","instructor"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12067', 'THEO-7083', 'Being Human', 'In this course, students will engage critically with what it means to be human, in biblical, theological, and contemporary contexts, leading them to develop a Christian anthropology appropriate to life and ministry today. Raising the questions, "Who am I?" "What am I?" and "Why am I here?" will lead to philosophical and theological explorations of personhood and identity, as students consider the nature and destiny of human beings. The course will address concepts such as naturalism, mind-body dualism, and post-modern identity, creation, imago dei, sin, relationality, and the significance of Christology for human self-understanding. Insights will be applied to contemporary issues including disability, human rights, artificial intelligence, and post-humanism.', 'THEO', 3, 0, 7, '[{"codes":["THEO-5013"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["THEO-5023"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12071', 'THEO-7113', 'Christian Theo Plural Context', 'This course focuses on the nature of pluralism in Western culture, in its philosophical, religious, and cultural forms. Through an examination of the nature of truth-claims, the concept of worldview, and shared cultural assumptions, students consider some of the potential and challenges of expressing Christian faith in contemporary Western and global context. They consider how to interact with and respond theologically to other religious traditions. Students explore the contours of relating faith and culture, including the impact of culture on theology, and potential for religious expression in the public square. Prerequisites: THEO 5013, 5023, or permission of instructor.', 'THEO', 3, 0, 7, '[{"codes":["THEO-5013","and","THEO-5023","or","permission","of","the","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12073', 'THEO-7133', 'Apologetic Engagement Contemp', 'This course will orient students to the field of Christian apologetics in contemporary context and equip them to engage faith and culture for ministry. We will examine the rationale for apologetics and its place in contemporary society, identify and explore cultural shifts that need to be addressed by the church, explore the nature of worldview and the philosophical viability of faith, and consider some major issues in apologetics today. Special topics include the existence of God, the problem of pain, the authority of the Bible, the supremacy of Christ, creation-evolution and other religions, while considering how Christians express their faith in contemporary context. Cross-listed as EVAN 7133.', 'THEO', 3, 0, 7, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('12074', 'THEO-7143', 'Theology of Political Reconcil', 'In this course students will develop a theology of political reconciliation through the lens of collective ethical responsibility. They will explore the place of social sin, forgiveness, and repentance in political reconciliation, and consider the tension between individual and collective responsibility. Students will apply their learning to contemporary contexts as they consider the political role of the church and what it means for Christian leaders to be ambassadors of reconciliation.', 'THEO', 3, 0, 7, '[]');
