INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13403', 'HIST-407T', 'Honours Thesis 1', 'The thesis is the most important component of the honours program. It provides the student with the opportunity to contribute to historical knowledge through original research. Prerequisite(s): Students must have permission of Thesis Supervisor and Department to do a History Thesis.', 'HIST', 3, 0, 4, '[]');
