INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13413', 'NUTR-407T', 'Honours Thesis 1', 'The Honours Thesis provides an opportunity for a student, under the guidance of a supervisor, to select a research topic, conduct a literature review of the topic, write a research proposal, carry out the research, and present it in a professional manner both orally and as a written thesis.', 'NUTR', 3, 0, 4, '[{"codes":["NUTR-3013"],"textExtension":"- Must be completed prior to taking this course."}]');
