INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13419', 'KINE-181C', 'Sledge Hockey', 'Introductory Activity Courses. The focus is on acquiring basic skills in the sport or physical activity, learning the theoretical basis of performance, learning teaching progressions, and acquiring an appreciation of the sport or physical activity.  Prerequisite(s): BKIN/BKIH students only, at least second-year standing.', 'KINE', 1.5, 0, 1, '[{"codes":["2nd-year","standing","(25h","or","more","completed)"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13420', 'POLS-470T', 'Honours Thesis 1', '', 'POLS', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13421', 'POLS-408T', 'Honours Thesis 2', '', 'POLS', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13422', 'PSYC-407T', 'Honours Thesis 1', 'This course requires the student to propose and carry out a study and submit a thesis written according to American Psychological Association format and regulations provided by the university honours committee. The thesis is supervised by a Psychology faculty member. The thesis grade is determined by the thesis supervisor and an additional Departmental faculty member. The thesis must be presented orally in a symposium organized by the Department.', 'PSYC', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13423', 'PSYC-408T', 'Honours Thesis 2', 'This course requires the student to propose and carry out a study and submit a thesis written according to American Psychological Association format and regulations provided by the university honours committee. The thesis is supervised by a Psychology faculty member. The thesis grade is determined by the thesis supervisor and an additional Departmental faculty member. The thesis must be presented orally in a symposium organized by the Department.', 'PSYC', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13424', 'SOCI-407T', 'Honours Thesis 1', '', 'SOCI', 3, 0, 4, '[]');
