INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13446', 'MUSI-4903', 'Applied Study', 'Course can be repeated for credit.', 'MUSI', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13447', 'BIOT-3443', 'Science of Fermentation', 'Earth could not support life without the activities of microorganisms. This course will examine the essential roles that microbes play in the biosphere, the unusual and surprising ways that they have adapted to harsh niches, and how humans are increasingly exploiting their biochemical abilities in food production, water purification, medicines, soil improvement and energy recovery. (3h lab). Prerequisite(s): BIOL 2053 with a minimum grade of C-; BIOL 2013 with a minimum grade of C- or permission of the instructor.', 'BIOT', 3, 0, 3, '[{"codes":["BIOL-2053","and","BIOL-2013","with","minimum","grade","C-","required","or","permission","or","instructor"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["BIOL-3570L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13448', 'BIOT-3453', 'Sensory Analysis', 'Principles involved in the evaluation of the appearance, taste, smell and texture of foods, with an emphasis on their role in food product development. Evaluation approaches, including consumer and analytical tests are covered in theory and in practice. The laboratory component includes a research project on sensory attributes of foods. (3h lab). Prerequisites: MATH 1223 or MATH 2243, NUTR 1343.', 'BIOT', 3, 0, 3, '[{"codes":["NUTR-1343,","and","either","MATH-1223","or","MATH-2243"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["NUTR-4220L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13449', 'BIOT-3463', 'Analytical Tech. in Biopharma', 'Modern molecular and atomic spectrometry, gas and liquid chromatography. (3h lab). Prerequisite(s): CHEM 2813 or CHEM 2853, with a minimum grade of C-.', 'BIOT', 3, 0, 3, '[{"codes":["CHEM-2813","or","CHEM","2853","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["CHEM-3820L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13450', 'BIOT-3473', 'Bioethics and Prof. Pract.', 'This course provides an introduction to ethical issues in health care and medical research, and it also surveys some of the relevant laws and social policies. Topics include abortion, assisted death, allocation of scarce resources, cloning, decisional capacity and informed consent, genetic enhancement, human and animal experimentation, and stem cell research. Prerequisite(s): One year of university study.', 'BIOT', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13451', 'BIOT-3483', 'Appl Microbiol & Molec Biotech', 'Provides an overview of the fundamental principles of genetics with a focus on modern theories and techniques including gene editing, regulation of gene expression and the use of genetic information in forensics. The laboratory will train students in the skills used in DNA fingerprinting and analyses. (3h lab).', 'BIOT', 3, 0, 3, '[{"codes":["BIOL-2013","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["BIOL-3610L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13452', 'MATH-1003', 'Precalculus', 'The study of functions and their properties. This includes an in-depth look at polynomials, rational, exponential, logarithmic, and trigonometric functions, and their applications. This course may not be used to satisfy major or minor Mathematics requirements.  Prerequisite: Permission of the instructor.', 'MATH', 3, 0, 1, '[{"codes":["MATH-1000L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13454', 'ENGL-1493', 'Writing & Reading Critically 2', 'This course is the second of two consecutive, connected courses that add up to one full-year course. It introduces students to fiction, drama, and poetry from a range of periods. Students will develop analytical skills and learn strategies for writing clearly and persuasively. ENGL 1483-1493 is acceptable for English Majors and functions as the foundational and introductory pre-requisite for most upper-level English classes. Students interested in English should take either ENGL 1483-1493 or ENGL 1413 plus ENGL 1423. Corequisite(s): Credit can be obtained only if students register in ENGL 1483 Part 1 during the same academic calendar year. Antirequisite(s): ENGL 1406 or ENGL 1413 and ENGL 1423.', 'ENGL', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13456', 'BIOT-2013', 'Research Methods Biotechnology', 'This course focuses on methods used in biotechnology research specifically synthesizing content knowledge for real-world application of skills in data management, research ethics, scientific communication, professionalism and biotechnology industry application. Includes a 3hr lab. Prerequisite(s): Enrollment in a Biotechnology degree Option, BIOL 1113, BIOL 1123, CHEM 1013, CHEM 1023.', 'BIOT', 3, 0, 2, '[{"codes":["","","","","BIOL-1113,","BIOL-1123,","CHEM-1013,","and","CHEM-1023;"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["BIOT-2010L;"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13459', 'ENGL-2083', 'Strategies for Reading Literat', 'This course is the first of two consecutive, connected courses that add up to one full-year course. It will bring English Majors together in (ideally) their second year to give them a common experience in exploring and discussing various critical strategies for reading literature. Amongst the theoretical approaches that may be introduced are feminism, historiography, psychoanalysis, and postcolonialism. The course is required of all English majors. Prerequisite(s): ENGL 1483-1493 or ENGL 1413 plus ENGL 1423 with a minimum grade of C-. Corequisite(s): Credit can be obtained only if students register in and complete ENGL 2093 Part 2 during the same academic calendar year. Antirequisite(s): ENGL 2006.', 'ENGL', 3, 0, 2, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13460', 'ENGL-2093', 'Strategies for Reading Literat', 'This course is the second of two consecutive, connected courses that add up to one full-year course. It will bring English Majors together in (ideally) their second year to give them a common experience in exploring and discussing various critical strategies for reading literature. Amongst the theoretical approaches that may be introduced are feminism, historiography, psychoanalysis, and postcolonialism. The course is required of all English majors. Prerequisite(s): ENGL 1483-1493 or ENGL 1413 plus ENGL 1423 with a minimum grade of C-. Corequisite(s): Credit can be obtained only if students register in and complete ENGL 2083 Part 1 during the same academic calendar year. Antirequisite(s): ENGL 2006.', 'ENGL', 3, 0, 2, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423","with","a","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13461', 'ENGL-2223', 'Shakespeare', 'This course is the first of two consecutive courses that add up to one full-year course. It will involve the intensive study of selected plays by Shakespeare. Its main goal is to help students develop both a critical and a theatrical eye. Careful attention will be paid to the complexity of Shakespeare''s language, as well as to the plays'' roles as cultural artefacts both today and in the past. Prerequisite(s): ENGL 1483-1493 or ENGL 1413 plus ENGL 1423) with a minimum grade of C-. Corequisite(s): Credit can be obtained only if students register in ENGL 2233 Part 2 during the same academic calendar year. Antirequisite(s): Credit can be obtained for either ENGL 2223- 2233 (combined), or for one or both ENGL 2183 and ENGL 2193.', 'ENGL', 3, 0, 2, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13462', 'ENGL-2233', 'Shakespeare', 'This course is the second of two consecutive courses that add up to one full course. It will involve the intensive study of selected plays by Shakespeare. Its main goal is to help students develop both a critical and a theatrical eye. Careful attention will be paid to the complexity of Shakespeare''s language, as well as to the plays'' roles as cultural artefacts both today and in the past. Prerequisite(s): ENGL 1483-1493 or ENGL 1413 plus ENGL 1423 with a minimum grade of C-. Corequisite(s): Credit can be obtained only if students register in ENGL 2223 Part 1 during the same academic calendar year. Antirequisite(s): Credit can be obtained for either ENGL 2223- 2233 (combined), or for one or both ENGL 2183 and ENGL 2193.', 'ENGL', 3, 0, 2, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13463', 'ENGL-2323', 'The Romantics', 'This course is the first of two consecutive courses that add up to one full course. It focuses on the diverse literature of the British Romantic period (1785-1830), a period of social, political and artistic change and contradiction. Artists and writers combine nostalgia, self-aware immediacy and hopeful idealism into works that favour imagination, emotion and vision. Featured authors include William Blake, William Wordsworth, Mary Wollstonecraft, Lord Byron, John Keats, Mary Shelley and Jane Austen. Prerequisite(s): ENGL 1483- 1493 or ENGL 1413 plus ENGL 1423 with a minimum grade of C-. Corequisite(s): Credit can only be obtained if students register in and complete ENGL 2333 during the same academic calendar year. Antirequisite(s): Credit can only be obtained for either ENGL 2323 -2333 (combined), or for one or both of ENGL 2353 and ENGL 2363.', 'ENGL', 3, 0, 2, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13464', 'ENGL-2333', 'The Romantics', 'This course is the second of two consecutive courses that add up to one full course. It focuses on the diverse literature of the British Romantic period (1785-1830), a period of social, political and artistic change and contradiction. Artists and writers combine nostalgia, self-aware immediacy and hopeful idealism into works that favour imagination, emotion and vision. Featured authors include William Blake, William Wordsworth, Mary Wollstonecraft, Lord Byron, John Keats, Mary Shelley and Jane Austen. Prerequisite(s): ENGL 1483- 1493 or ENGL 1413 plus ENGL 1423 with a minimum grade of C-. Corequisite(s): Credit can only be obtained if students register in ENGL 2323 during the same academic calendar year. Antirequisite(s): Credit can only be obtained for either ENGL 2323-2333 (combined), or for one or both of ENGL 2353 and ENGL 2363', 'ENGL', 3, 0, 2, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13465', 'ENGL-1483', 'Writing & Reading Critically 1', 'This course is the first of two consecutive, connected courses that add up to one full-year course. It introduces students to fiction, drama, and poetry from a range of periods. Students will develop analytical skills and learn strategies for writing clearly and persuasively. ENGL 1483-1493 is acceptable for English Majors and functions as the foundational and introductory pre-requisite for most upper-level English classes. Students interested in English should take either ENGL 1483-1493 or ENGL 1413 plus ENGL 1423. Corequisite(s): Credit can be obtained only if students register in ENGL 1493 Part 2 during the same academic calendar year. Antirequisite(s): ENGL 1406 or ENGL 1413 and ENGL 1423.', 'ENGL', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13466', 'ENGL-2473', 'Victorian Studies', 'This course is the first of two consecutive combined courses that add up to one full course. Students read British fiction, poetry, and drama from 1837-1901 within cultural, historical, and political contexts. The aim of this course is to introduce students to canonical and non- canonical works, as well as to convey an understanding of the nineteenth-century issues with which writers were generally preoccupied. Prerequisite(s): ENGL 1483-1493 or ENGL 1413 plus ENGL 1423 with a minimum grade of C-. Corequisite(s): Credit can only be obtained if students register in ENGL 2483 during the same academic calendar year. Antirequisite(s): Credit can be obtained for either ENGL 2473-2483, or for one or both of ENGL 2413 and ENGL 2423.', 'ENGL', 3, 0, 2, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13467', 'ENGL-2483', 'Victorian Studies', 'This course is the second of two consecutive combined courses that add up to one full course. Students read British fiction, poetry, and drama from 1837-1901 within cultural, historical, and political contexts. The aim of this course is to introduce students to canonical and non- canonical works, as well as to convey an understanding of the nineteenth-century issues with which writers were generally preoccupied. Prerequisite(s): ENGL 1483-1493 or ENGL 1413 plus ENGL 1423 with a minimum grade of C-. Corequisite(s): Credit can only be obtained if students register in ENGL 2473 during the same academic calendar year. Antirequisite(s): Credit can be obtained for either ENGL 2473-2483, or for one or both of ENGL 2413 and ENGL 2423', 'ENGL', 3, 0, 2, '[{"codes":["ENGL-1483","and","ENGL-1493","or","ENGL-1413","and","ENGL-1423;","Minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13468', 'BIOT-3413', 'Viticulture and Industry Knowl', 'This course provides students with the opportunity to develop a range of skills and knowledge in the dynamic environment of beverage production, including vineyard management techniques and harvesting, production, sensory evaluation and marketing practices. (3hr lab)', 'BIOT', 3, 0, 3, '[{"codes":["BIOL-1113","BIOL-1123","CHEM-1013","CHEM-1023","and","BIOT-2013"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13469', 'BIOT-3423', 'Biopharma and Industry Knowled', 'This course provides students with the opportunity to develop a range of skills and knowledge in common biopharma processes and how they apply them to solve different problems.', 'BIOT', 3, 0, 3, '[{"codes":["BIOL-1113","BIOL-1123","CHEM-1013","CHEM-1023","BIOT-2013"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13470', 'BIOT-3433', 'Wine & Beverage Marketing', 'Students will learn to design, deliver, and promote wine and beverage products, services, and experiences that will satisfy customers. They will learn research and measurement tools to help them make informed choices about the best promotional tools (e.g., digital) to use in a regulated market. Students will have practical experiences at local wineries, cideries, craft breweries, and distilleries. Prerequisite(s): Third-year standing and 19 years of age or older.', 'BIOT', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13471', 'BIOT-2010L', 'BIOT 2013 Laboratory', '', 'BIOT', 0, 1, 2, '[{"codes":["BIOT-2013"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13472', 'MUSI-271A', 'Topics in Collaborative Music', 'Topics in Collaborative Music includes intensive work on various repertoire with a small group and a faculty coach. This course may include weekly coaching, academic lectures, assignments, and performance opportunities. Course may be repeated for credit.', 'MUSI', 1.5, 0, 2, '[{"codes":["MUSI-271B"],"textExtension":"- Must be taken at the same time as this course."}]');
