INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13479', 'PSYC-6073', 'Clinical Practicum and Psychop', 'Students will conduct psychological assessments and treatment in one or more placements under the supervision of registered psychologists. The classroom component provides students with practicum-related support, career preparation, and a foundational knowledge of DSM diagnostic criteria of disorders and anti-oppressive training using a client-centered approach. Enrolment is limited to Acadia M.Sc. Clinical Psychology students and by permission of the Department. Credit can only be obtained upon successful completion of both PSYC 6073 and PSYC 6083.', 'PSYC', 3, 0, 6, '[{"codes":["PSYC-5013","PSYC-5033","PSYC-5053","and","PSYC-5063"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13480', 'PSYC-6083', 'Clinical Practicum and Psychop', 'Students will conduct psychological assessments and treatment in one or more placements under the supervision of registered psychologists. The classroom component provides students with practicum-related support, career preparation, and a foundational knowledge of DSM diagnostic criteria of disorders and anti-oppressive training using a client-centered approach. Enrolment is limited to Acadia M.Sc. Clinical Psychology students and by permission of the Department. Credit can only be obtained upon successful completion of both PSYC 6073 and PSYC 6083.', 'PSYC', 3, 0, 6, '[{"codes":["PSYC-5013","PSYC-5023","PSYC-5033","PSYC-5053","and","PSYC-5063"],"textExtension":"- Must be completed prior to taking this course."}]');
