INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13482', 'MUSI-431A', 'Intro: HS Instrumental Music', 'Students will be introduced to the philosophies and practical skills that support successful instrumental music instruction in high schools. Topics will include repertoire selection, administration of resources, scheduling, and  lesson/unit design congruent with the Nova Scotia Instrumental Music Curriculum. Prerequisite(s): Permission of the Instructor. Corequisite(s): MUSI 3310.', 'MUSI', 1.5, 0, 4, '[{"codes":["MUSI-3310"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13483', 'MUSI-431B', 'Intro: HS Instrumental Music', 'Students will be introduced to the philosophies and practical skills that support successful instrumental music instruction in high schools. Topics will include repertoire selection, administration of resources, scheduling, and lesson/unit design congruent with the Nova Scotia Instrumental Music Curriculum. Prerequisite(s): Permission of the Instructor. Corequisite(s): MUSI 3310.', 'MUSI', 1.5, 0, 4, '[{"codes":["MUSI-3310","in","same","term"],"textExtension":"- Must be taken at the same time as this course."}]');
