INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13595', 'HIST-3033', 'History of the Holocaust', 'History 3033 will examine the origins, course and consequences of the Holocaust, one of the worst genocides in history. Topics will include the rise of antisemitism, Nazi racial policies, the transition from persecution to mass murder, the organization of the camps, responses to the Holocaust and the postwar search for justice.', 'HIST', 3, 0, 3, '[{"codes":["30h","of","university","courses"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13596', 'KINE-5043', 'Special Topics', '', 'KINE', 3, 0, 5, '[]');
