INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13610', 'ENVS-9223', '2000 Level Envs Elective', '', 'ENVS', 3, 0, 9, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13624', 'KINE-599Y', 'Graduate Thesis', 'This course requires the student to propose and carry out a research study under the supervision of a KINE faculty member. Students construct, submit, and defend a written thesis document in accordance with the KINE format and Graduate Studies regulations.', 'KINE', 15, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13627', 'LEDR-2113', 'Theo & Prac of Racial Justice', '', 'LEDR', 3, 0, 2, '[{"codes":["Take","9","credit","hours","from;","BIBL-2013","or","BIBL-3013","or","BIBL-3023","or","THEO-3013","or","THEO-3023"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13628', 'LEDR-5113', 'Theo & Prac of Racial Justice', '', 'LEDR', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13629', 'BIOL-2853', 'Physiology and Anatomy 1', 'An integrated approach to understanding human anatomy and physiology. Major topics include levels of organization, muscle-skeletal systems, neuroanatomy and physiology, and the integument. Labs involve use of specimens and models. This course is recommended for nursing students. (3h lab). Antirequisites: Credit can be obtained for only one of BIOL 2813, 2853 or KINE 2413. Major credit cannot be obtained for both BIOL 3173/ BIOL 3183 and BIOL 2853, although BIOL 2853 can be used as a science elective.', 'BIOL', 3, 0, 2, '[{"codes":["BIOL-2850L;"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13630', 'BIOL-2850L', 'Physiology and Anatomy 1 Lab', '', 'BIOL', 0, 1, 2, '[{"codes":["BIOL-2853"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13631', 'BIOL-2863', 'Physiology and Anatomy 2', 'An integrated approach to understanding human anatomy and physiology. Major topics include the endocrine, cardiovascular, respiratory, urinary, digestive, and reproductive systems. Labs involve use of specimens and models. This course is recommended for nursing students. (3h lab). Antirequisites: Credit can be obtained for only one of BIOL 2823, 2863 or KINE 2423. Major credit cannot be obtained for both BIOL 3173/ BIOL 3183 and BIOL 2863, although BIOL 2863 can be used as a science elective.', 'BIOL', 3, 0, 2, '[{"codes":["BIOL-2853","with","a","minimum","grade","of","C-"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["BIOL-2860L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13632', 'BIOL-2860L', 'Physiology and Anatomy 2 Lab', '', 'BIOL', 0, 1, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13644', 'THEA-PD03', 'Practice: Production', 'Students will produce, rehearse, and perform a production under the direction of Theatre faculty. Some students will be cast and receive instruction in acting, some will receive instruction in direction, dramaturgy, stage management, publicity, set construction, and/or lighting, sound, wardrobe, and prop design; and some will participate onstage and offstage. May be repeated for a total of 18 credit hours. Work often occurs evenings, weekends, and study breaks. Students should avoid taking night classes that would conflict.', 'THEA', 3, 0, 0, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13646', 'DMIN-8636', 'Portfolio-Project', 'Under the direction of a portfolio-project supervisor, appointed by the Director in consultation with the candidate, the doctoral candidate will design, implement, and report on a major research project.', 'DMIN', 6, 0, 8, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13647', 'DMIN-8646', 'Portfolio-Project', 'Under the direction of a portfolio-project supervisor, appointed by the Director in consultation with the candidate, the doctoral candidate will design, implement, and report on a major research project.', 'DMIN', 6, 0, 8, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13650', 'CREL-1213', 'World Religions Part 1', 'The history, beliefs, practices and contemporary relevance of the Hindu, Buddhist, Confucian, Taoist, Zoroastrian, Judaic, Muslim and Christian faiths. After outlining methods of understanding different ways of being religious the course examines the components of larger streams of tradition and compares and contrasts their respective beliefs and practices. Corequisite(s): Credit can be obtained only if students register in CREL 1223 Part 2 during the same academic calendar year. Antirequisite(s): Credit can be obtained for only one of CREL 1213/CREL 1223 or CREL 1206.', 'CREL', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13651', 'CREL-1223', 'World Religions Part 2', 'The history, beliefs, practices and contemporary relevance of the Hindu, Buddhist, Confucian, Taoist, Zoroastrian, Judaic, Muslim and Christian faiths. After outlining methods of understanding different ways of being religious the course examines the components of larger streams of tradition and compares and contrasts their respective beliefs and practices. Corequisite(s): Credit can be obtained only if students register in CREL 1213 Part 1 during the same academic calendar year. Antirequisite(s): Credit can be obtained for only one CREL 1213/CREL 1223 or CREL 1206.', 'CREL', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13664', 'PACC-7000', 'Mental Hlth Care in the Church', 'This micro-credential course explores the intersection of mental health and faith-based communities. Students will understand common symptoms, typical course of treatment, and possible complications of the major categories of mental illness. Additionally, students will create a model for a nurturing church environment as a supportive hub for mental health.', 'PACC', 0, 0, 7, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13665', 'PAST-7000', 'Perspectives on Preaching', 'This micro-credential course explores specific and current perspectives on the nature of preaching. Students will be introduced to current perspectives on preaching and the ways in which they can include these insights into their own practice to enhance their preaching.', 'PAST', 0, 0, 7, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13667', 'POLS-5013', 'Authoritarian Regimes', 'This course examines the internal politics of authoritarian regimes. Major topics include military coups, regime survival strategies, corruption and patronage, ideology and propaganda, and revolutionary movements. Case studies will be drawn from around the globe. This course will also consider whether contemporary democracies are vulnerable to an authoritarian transition of their own.', 'POLS', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13668', 'COMP-5950', 'Project', 'MSc project for students enrolled in the project option.', 'COMP', 0, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13669', 'WGST-3203', 'Black Women in Politics', 'This course explores the political expressions of Black women in Canada and the United States from slavery to the present. Through books, primary sources, and films, students will examine how Black women in Canada and the United States have articulated themselves as political actors even though, for most of this period, they have been defined outside of the body politic.', 'WGST', 3, 0, 3, '[{"codes":["WGST-1413","and","second-year","standing"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13670', 'POLS-3153', 'Canadian Foreign Policy', 'This course explores Canada''s involvement in global politics, taking a critical analysis that interrogates the trends and activities that have defined Canada''s international role and the various forces and actors that shaped Canada''s global engagement. Canada''s national focus on multilateralism, peacekeeping and human security will be examined. Other themes include Canada''s role in foreign wars, global governance, and international development.', 'POLS', 3, 0, 3, '[{"codes":["POLS-2683",""],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13672', 'POLS-3053', 'Borders and Migration', 'This course looks at the causes, consequences and experiences of borders, and their impact on the people who cross them. The course prepares students to understand the impact of frontiers and borders locally, globally, aesthetically, intellectually, technologically, and their effects on nation states, cultures, Indigenous Peoples, languages, gender, the class system, and growing digital divides.', 'POLS', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13674', 'POLS-3133', 'Leaders and Cabinets in Canada', 'This course examines executive-level governance in the Canadian federal system. It explains the work of prime ministers, premiers, ministers and cabinets, and touches on the role of opposition party leaders in a system of responsible government as well as glass ceilings. Key political actors and public policy decisions in Canadian history are profiled, including notable leaders and ministers across Canada.', 'POLS', 3, 0, 3, '[{"codes":["A","minimum","grade","of","C-","in","POLS-2003,","POLS-2023,","or","POLS-2223,","or","permission","of","the","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13677', 'POLS-3243', 'Political Psychology', 'This course explores the intersection of politics and psychology, providing students with tools to analyze political phenomena through the lens of individual and collective psychological processes. We will delve into topics like the psychology of democracy, capitalism, and fascism, social solidarity and exclusion, media influence and propaganda, politics of identity, memory, and collective trauma, colonialism, nationalism, and more.', 'POLS', 3, 0, 3, '[{"codes":["30h","or","more","completed"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13678', 'POLS-3233', 'Political Mgmt Canada', 'This course profiles the work of partisan advisors and political staff to leaders, situating Canadian practice in comparative context. Topics may include political management theory, strategic communications, campaign management, public opinion research, political marketing, permanent campaigning, advocacy, ethical codes of conduct. Emphasis is placed on concise writing.', 'POLS', 3, 0, 3, '[{"codes":["POLS-2223","with","minimum","grade","B","or","","permission","of","the","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13679', 'POLS-4023', 'Getting Elected in Canada', 'In this course, students will research election literature to prepare a campaign plan as part of an academic exercise to get a candidate elected to a Canadian legislature. Topics may include the history of Canadian elections, electoral systems, election rules, voter behaviour, candidate nominations, campaign jobs, leaders'' debates, constituency campaigns, diverse representation and digital campaign trends. Antirequisite: POLS 3903 Canadian Political Parties.', 'POLS', 3, 0, 4, '[{"codes":["A","minimum","grade","of","B","in","POLS","2003,","POLS","2023,","POLS","2223,","POLS","3133,","or","POLS","3203,","or","permission","of","the","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13680', 'POLS-4013', 'Authoritarian Regimes', 'This course examines the internal politics of authoritarian regimes. Major topics include military coups, regime survival strategies, corruption and patronage, ideology and propaganda, and revolutionary movements. Case studies will be drawn from around the globe. This course will also consider whether contemporary democracies are vulnerable to an authoritarian transition of their own.', 'POLS', 3, 0, 4, '[{"codes":["POLS-2893"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13681', 'POLS-5023', 'Getting Elected in Canada', 'In this course, students will apply academic literature about elections to design a campaign plan that will get a candidate elected to a Canadian legislature. Topics may include the history of Canadian elections, electoral systems, election rules, voter behaviour, candidate nominations, campaign jobs, leaders'' debates, constituency campaigns, diverse representation and digital campaign trends. Antirequisite: POLS 3903 Canadian Political Parties.', 'POLS', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13682', 'SOCI-5263', 'Health, Environment, Poverty', 'This course explores the interrelationship between our health, the environment, and social inequalities including poverty. A central question to explore will be "what can/does sociology offer in the face of the climate crisis"? Assigned readings explore international and local cases, allowing students to build connections. Antirequisite: SOCI 4263.', 'SOCI', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13684', 'SOCI-4473', 'Boundaries, Borders, Belonging', 'The course examines how social, political, and symbolic boundaries shape belonging and exclusion in an increasingly globalized yet divided and polarized world. The course takes a critical lens to interrogate the borders as the regimes of control, surveillance, citizenship, mobility, labour and everyday life.', 'SOCI', 3, 0, 4, '[{"codes":["3h","1000-level","SOCI","and","third-year","standing,","or","permission","of","the","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13685', 'SOCI-4233', 'Sem in Gender & Development', 'This course focuses on theoretical and empirical explanations of how global development processes affect gender inequality and social relations. Students will gain an understanding of how the theories, actors, and ongoing challenges of development interact with and work to shape socially constructed gender relations in a global perspective. Special attention is paid to how globalization influences gender in development processes.', 'SOCI', 3, 0, 4, '[{"codes":["3h","1000-level","SOCI","and","third-year","standing,","or","permission","of","the","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13686', 'SOCI-2473', 'Sociology of Migration', 'The course introduces students to the social, political, and cultural dynamics of human mobility through a sociological lens, examining how migration intersects with larger social processes of globalization, colonialism, imperialism, capitalism, and racialization. It provides key themes, concepts, and theories of migration from various perspectives, including labour migration, forced migration, return migration, and environmental migration. Antirequisite(s): Credit can be obtained for only one of SOCI 2473 or SOCI 3473.', 'SOCI', 3, 0, 2, '[{"codes":["3h","of","1000-level","SOCI","or","permission","of","the","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13687', 'CREL-3013', 'Hate Groups And/As Religion', 'Intersectional examination of practices and self-understandings of North American hate groups or religious groups whose dominant teaching promotes hatred of persons or groups due to ethnicity, religion, gender, sexual orientation, or other identity. Special consideration of gender in the formation of such groups. Topics: social scientific study of NRMs; historical roots/teachings of hate groups; issues of popularity and interpretation.', 'CREL', 3, 0, 3, '[{"codes":["2nd","year","standing","(25h","or","more","completed)"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13690', 'ECON-3543', 'Health Economics', 'An applied study of health economics through a microeconomic lens, focusing particularly on Canadian issues and policies, including the determinants of healthcare, the economics of insurance, the behaviour of healthcare providers and consumers, asymmetric information, and healthcare markets.', 'ECON', 3, 0, 3, '[{"codes":["ECON-1013"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13691', 'FRAN-3503', 'Le Français Québécois, Acadien', 'Le but du cours est d''offrir aux élèves une description des grandes lignes des aspects divergents (par rapport à la norme) du français québécois et acadien. Bien qu''on fera lire des extraits d''auteurs exemplifiant ces usages, le but premier sera de permettre aux élèves eux-mêmes de lire et comprendre du français québécois et acadien.', 'FRAN', 3, 0, 3, '[{"codes":["FRAN-2023"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13693', 'NURS-1203', 'Transitioning to a Prof. Rn', 'This is the first nursing course in the Licensed Practical Nurse (LPN) to Bachelor of Science in Nursing (BScN) pathway and will build on the knowledge and skills acquired in the student''s LPN program. The focus of the course is to support student''s transition from LPN to a baccalaureate prepared (BScN). The course introduces students to a concept-based curriculum and foundational concepts of professional RN practice including role and responsibilities, professional RN identity, ethics, and legal issues. Topics such as: scope of practice, standards of nursing practice, code of ethics, entry-level competencies, Nova Scotia College of Nursing (NSCN) and the Canadian Nurses Association (CNA) will be included. Students are introduced to concepts of collaboration, communication, relational practice, informatics, and leadership.', 'NURS', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13694', 'NURS-1213', 'The Roles of the R.N.', 'This is the second course in the Licensed Practical Nurse (LPN) to Bachelor of Science in Nursing (BScN) pathway and will build on the knowledge and skills acquired in the student''s LPN program. It is delivered by St. Francis Xavier University.', 'NURS', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13695', 'NURS-2103', 'Prof Formation of Nursing 1', 'This course is an introductory nursing course designed to assist students in developing a professional identity as a Registered Nurse (RN). Students will identify and analyze concepts that define and underpin the professional identity of the RN. Students will be introduced to attributes of professionalism, which include leadership, clinical judgement, communication, ethics, and comportment. Concepts introduced in Professional Formation 1 will be further explored in Professional Formation 2 and 3.', 'NURS', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13696', 'NURS-2203', 'Foundations of Nursing 1', 'This course is designed to assist students in understanding professional nursing competencies and concepts in the care of diverse populations across the lifespan. Emphasis will be on the development of psychomotor skills and clinical reasoning related to the concepts of communication, grief, clinical judgment, perfusion and gas exchange, thermoregulation, infection, tissue Integrity, mobility, elimination, nutrition, acute and chronic pain in diverse populations across the lifespan. An additional three-hour nursing practice component per week for eight weeks is integrated into this course.', 'NURS', 3, 0, 2, '[{"codes":["NURS-2200L","-","Must","be","taken","at","the","same","time","as","this","course.",""],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13698', 'NURS-2213', 'Foundations of Nursing 2', 'This course will focus on the Integration of foundational nursing concepts, skills and practice such as patient safety, nutrition, elimination and tissue integrity. Emphasis will be on the development of psychomotor skills and clinical judgment related to populations in transition across the lifespan. An additional three - hour nursing practice component per week for eight weeks is integrated into this course.', 'NURS', 3, 0, 2, '[{"codes":["NURS-2103,","NURS-2203,","NURS-2403,","NURS-2413,","and","NURS-2903"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13699', 'NURS-2303', 'Health & Illness 1', 'This course explores the nursing of individuals and families in transition across the lifespan. Using evidenced-based research, students will explore the role of the nurse in facilitating the health of individuals and families through various life stages including childbirth. Through a process of critical inquiry, biopsychosocial responses related to associated health and illness events across the lifespan.', 'NURS', 3, 0, 2, '[{"codes":["NURS-2103,","NURS-2203,","NURS-2403,","NURS-2413,","and","NURS-2903"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13700', 'NURS-2403', 'Health Prom. & Assessment 1', 'This course focuses on health promotion and illness prevention of individuals across the lifespan. Using the population health promotion model as a framework, this course will allow students the opportunity to analyze health concepts with nursing application through selected exemplars. This course, in particular, will emphasize the assessment phase of the Clinical Judgement/Decision Making with theoretical and practical applications focusing on the comprehensive and systematic assessment of individuals. Students are introduced to health promotion principles and the utilization of these principles in planning and implementing health promotion plans for individuals. An additional three-hour nursing practice component per week for eight weeks is integrated into this course.', 'NURS', 3, 0, 2, '[{"codes":["NURS-2400L","-","Must","be","taken","at","the","same","time","as","this","course.",""],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13701', 'NURS-2413', 'Health Promo. & Assessment 2', 'This course explores the concepts of health and wellness and the nurse''s role in health promotion at the family, group and community level. Students will utilize the population health promotion model and clinical judgement/decision making as a framework for working with families, groups and communities.', 'NURS', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13702', 'NURS-2503', 'Pathop in Diverse Populations', 'This course focuses on the study of foundational concepts and physiologic processes related to human pathophysiology across the lifespan. Emphasis is on understanding pathophysiology as an alteration in normal physiological functioning. Topics include the pathogenesis of common diseases across the life span. Within each topic the rationale for nursing interventions are explored.', 'NURS', 3, 0, 2, '[{"codes":["NURS-2103,","NURS-2203,","NURS-2403,","NURS-2413,","and","NURS-2903"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13703', 'NURS-2513', 'Pharmo & Alternative Therapies', 'This course will explore concepts of pharmacotherapeutics, alternative and complementary therapies in diverse populations across the lifespan. Emphasis will be on understanding the basic principles of pharmacokinetics and pharmacodynamics and how these principles affect nursing interventions and treatment decisions in all populations across the lifespan. An additional three-hour nursing practice component per week for eight weeks is integrated into this course.', 'NURS', 3, 0, 2, '[{"codes":["NURS-2510L","-","Must","be","taken","at","the","same","time","as","this","course.",""],"textExtension":"- Must be taken at the same time as this course."},{"codes":["NURS-2103,","NURS-2203,","NURS-2403,","NURS-2413,","and","NURS-2903"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13704', 'NURS-2200L', 'Nurs 2203 Laboratory', '', 'NURS', 0, 1, 2, '[{"codes":["NURS-2203","-","Must","be","taken","at","the","same","time","as","this","course.",""],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13705', 'NURS-2210L', 'Nurs 2213 Laboratory', '', 'NURS', 0, 1, 2, '[{"codes":["NURS-2213","-","Must","be","taken","at","the","same","time","as","this","course.",""],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13706', 'NURS-2400L', 'Nurs 2403 Laboratory', '', 'NURS', 0, 1, 2, '[{"codes":["NURS-2403","-","Must","be","taken","at","the","same","time","as","this","course.",""],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13708', 'NURS-2510L', 'Nurs 2513 Laboratory', '', 'NURS', 0, 1, 2, '[{"codes":["NURS-2513","-","Must","be","taken","at","the","same","time","as","this","course.",""],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13709', 'NURS-2903', 'Nurs. Practice Integration 1', 'Nursing Practice Integration 1: Foundational Concepts in Nursing   This practicum focuses on the Integration of foundational concepts of nursing knowledge, skills and practices. Application of these foundational concepts will occur in a variety of nursing practice settings. This course will consist of 160 hours of nursing practice application.', 'NURS', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13711', 'NURS-2913', 'Nurs. Practice Integration 2', 'Nursing Practice Integration 2: Care of Persons and Families in Transition Across the Lifespan  This course builds upon Nursing Practice Integration 1. This course will integrate professional nursing concepts related to the nursing care of persons and families in transition across the lifespan. This course will broaden students'' understanding of professional nursing competencies and standards of nursing care in these populations and consists of 160 nursing practice hours.', 'NURS', 3, 0, 2, '[{"codes":["NURS-2103,","NURS-2203,","NURS-2403,","NURS-2413,","and","NURS-2903"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13712', 'NURS-3103', 'Professional Formation 2', 'This course builds on the foundational knowledge acquired in Professional Formation 1, which is designed to assist students in developing a professional identity as a registered nurse (RN). Students will be provided with the opportunity to identify, analyze, and integrate concepts that define and underpin professionalism.', 'NURS', 3, 0, 3, '[{"codes":["NURS-3303,","NURS-3313,","NURS-3503,","and","NURS-3906"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13713', 'NURS-3303', 'Health & Illness 2', 'This course explores the nursing of individuals and families experiencing acute health challenges across the lifespan. Using evidence-based research, students will explore the role of the professional nurse in caring for individuals and families encountering these health challenges. Through a process of critical inquiry and relational practice, biopsychosocial responses related to the acute phase of illness across the lifespan are analyzed.', 'NURS', 3, 0, 3, '[{"codes":["NURS-2303,","NURS-2213,","NURS-2503,","NURS-2513,","and","NURS-2913"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13714', 'NURS-3313', 'Health & Illness 3', 'This course will explore health and illness concepts, with an emphasis on the acute biopsychosocial conditions across the lifespan. Evidence informed research is the foundation for the application of nursing care within the context of person, families and communities. Concepts covered are related to the biopsychosocial responses to acute illness across the lifespan.', 'NURS', 3, 0, 3, '[{"codes":["NURS-2303,","NURS-2213,","NURS-2503,","NURS-2513,","and","NURS-2913"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13715', 'NURS-3323', 'Health & Illness 4', 'This course will explore health and illness concepts, with an emphasis on the chronic biopsychosocial conditions across the lifespan. Evidence-informed research is the foundation for the application of nursing care within the context of person, families and communities. Concepts covered are related to the biopsychosocial responses to chronic illness.', 'NURS', 3, 0, 3, '[{"codes":["NURS-3303,","NURS-3313,","NURS-3503,","and","NURS-3906"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13716', 'NURS-3503', 'Nursing Research Methods', 'This course will introduce students to the research process as it relates to nursing and other health disciplines. Concepts of research design, implementation, analysis and interpretation are studied in the context of the steps of the research process. The course requires students to become immersed in the language and culture of research and to understand the broader context in which nursing research is conducted. Emphasis is placed on the student''s potential role as a generator of researchable questions, as a collaborator in research related to nursing practice and as an intelligent consumer of research.', 'NURS', 3, 0, 3, '[{"codes":["NURS-2303,","NURS-2213,","NURS-2503,","NURS-2513,","and","NURS-2913"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13717', 'NURS-3906', 'Nurs. Practice Integration 3', 'This course will integrate students'' understanding and knowledge of nursing concepts related to the care of persons and families experiencing acute health challenges in a variety of settings across the life span. Acute health challenges may include delirium, fluid and electrolyte imbalances, Acute Coronary Syndrome, acute renal failure, anxiety, meningitis, septicemia, pancreatitis, psychosis and mood disorders. Students will apply knowledge and demonstrate practical skill application of concepts/exemplars related to these health challenges in a variety of nursing practice settings. This course will consist of 240 hours of direct nursing practice on and off campus.', 'NURS', 6, 0, 3, '[{"codes":["NURS-2303,","NURS-2213,","NURS-2503,","NURS-2513,","and","NURS-2913"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13718', 'NURS-3916', 'Nurs. Practice Integration 4', 'Nursing Practice Integration 4 will integrate professional nursing concepts related to a variety of settings inclusive of all ages across the lifespan. Students will care for persons and families in acute care, long term care and community care settings. The practice will broaden students'' understanding of professional nursing competencies and standards of nursing care required in a variety of populations and across a variety of settings. This course will consist of 240 nursing practice hours.', 'NURS', 6, 0, 3, '[{"codes":["NURS-3303,","NURS-3313,","NURS-3503,","and","NURS-3906"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13719', 'NURS-4103', 'Professional Formation 3', 'This course will focus on the development of a professional nursing identity as a continuous process and builds upon dynamic and fluid process by introducing and integrating previous and new educational and nursing practice concepts that lead to self-reflection and foster the formation of students'' identity as a professional Registered Nurse (RN).', 'NURS', 3, 0, 4, '[{"codes":["NURS-3103,","NURS-3323,","and","NURS-3916"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13720', 'NURS-4503', 'Nursing Theory & Practice Syn', 'This course is designed to foster integration and synthesis of prior learning in nursing theory and practice. Using a case study approach, students will explore complex and emerging health and illness issues in diverse populations throughout the lifespan. Students will trace a variety of prevailing health issues among their clients which may include an individual, a family, a community, or a specific population across the different stages of the health - illness continuum, including health promotion, prevention, health protection, health maintenance, restoration, and palliation.', 'NURS', 3, 0, 4, '[{"codes":["NURS-3103,","NURS-3323,","and","NURS-3916"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13721', 'NURS-4703', 'Special Topics in Nursing', 'In depth study of a selected topic in the field. Special topics or projects that are not covered in the regular curriculum.
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13722', 'NURS-4813', 'Dir. Study & Practice: Nursing', 'This course is a supervised study of current knowledge and practice in a selected topic in Nursing.', 'NURS', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13723', 'NURS-4906', 'Nurs. Practice Integration 5', 'Nursing Practice Integration 5 uses a population health approach to promote synthesis of prior learning presented in Terms 1-6. Students will demonstrate leadership in professional nursing practice by providing excellent nursing care and by demonstrating the ability to develop a health program plan to guide the nursing care of their clients which may include an individual, a family, a community, or a specific population experiencing prevailing health and illness challenges in the student''s particular practice area. Health program plans can be applied to health problems across any stage of the health-illness continuum, including health promotion, prevention, health protection, health maintenance, restoration, and palliation. Sample placement for students include various community health settings, acute care settings, rural or remote communities, hospice, government agencies, public health, professional bodies or long-term care. This course consists of 240 hours of supervised preceptored nursing practice.', 'NURS', 6, 0, 4, '[{"codes":["NURS-3103,","NURS-3323,","and","NURS-3916"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13724', 'NURS-4915', 'Nurs. Practice Integration 6', 'Nursing Practice Integration 6-Transition to Nursing Practice is the final course of the BScN program. This course is a preceptored nursing practice with supervision from Nursing Faculty or Nursing Practice Educator. This course will integrate nursing knowledge and entry-level competencies throughout the reality work life dimension and understanding of the scope and role of the Registered Nurse assisting the nursing students'' transition to the graduate nurses'' role. Relational nursing practice experiences will emphasize the role of the professional nurse and continue to build intra- and inter professional relationships within the professional health care team. Bridging theory to practice and self-directed learning will prepare students for National Council Licensure Examination (NCLEX-RN) and ongoing professional development. The senior level consolidation is 480 hours over a period of up to 13 weeks of preceptored nursing practice is in a setting of the students'' choice, and/or in consultation with the course professor.', 'NURS', 15, 0, 4, '[{"codes":["NURS-4103,","NURS-4503,","and","NURS-4906"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13725', 'KINE-3593', 'Physical Activity for All', 'Designed for future Physical Education teachers, this course develops pedagogical skills that will enable PE students of all cultures, orientations, and abilities the opportunities to be active within group settings. The course explores how to make physical education more inclusive so that future PE students can showcase their culture in class and through activities.', 'KINE', 3, 0, 3, '[{"codes":["3rd","year","standing","(55h","or","more","completed)"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13726', 'KINE-2483', 'Comprehensive School Health', 'Student learning and health are improved when schools and communities work together using an organized, united, and holistic approach which includes: social and physical environments; teaching and learning; policy; and partnerships and services working together. This course will focus on understanding these relationships to foster an ideal learning environment and healthy students. Prerequisite(s): BKIN/BKIH students only.', 'KINE', 3, 0, 2, '[{"codes":["2nd-year","standing","(25h","or","more","completed)"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13727', 'KINE-3123', 'School, Culture, Leadership', 'This course is designed for future Physical Education teachers and focuses on the roles that culture and leadership play in engaging students to become active.', 'KINE', 3, 0, 3, '[{"codes":["3rd","year","standing","(55h","or","more","completed)"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13728', 'KINE-185C', 'Multi-Activity Games', 'This course focuses on acquiring knowledge about the rules, tactics, and technical skills of low-organized games and activities. Students will learn how to apply the principles of kinesiology in practice. BKIN/BKIH Students Only', 'KINE', 1.5, 0, 1, '[{"codes":["2nd-year","standing","(25h","or","more","completed)"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13729', 'KINE-181E', 'Lacrosse', 'The focus is on acquiring the basic skills of the sport, learning the theoretical basis of performance, learning teaching progressions, and acquiring an appreciation of the sport.   BKIN/BKIH Students Only', 'KINE', 1.5, 0, 1, '[{"codes":["2nd-year","standing","(25h","or","more","completed)"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13732', 'CODE-3043', 'Renewable Energy & Community', 'Renewable energy (wind, solar, marine, geothermal) is explored in the context of its impacts on the economic, environmental, and societal dimensions in community. Emphasis on the role of renewal energy to address climate change, energy security, energy poverty, and economic self-determination is explored through scholarly literature, case studies, and field experiences. Prerequisite(s): Third-year standing in BCD, ESST, ENVS, or permission of the Department.', 'CODE', 3, 0, 3, '[{"codes":["3rd-year","standing","(55h","or","more","completed)"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13733', 'CODE-3033', 'Rural Community Development', 'This course examines how varying perspectives about rurality impact rural communities locally and globally. Students will gain an in-depth understanding of contemporary issues facing rural communities and historical processes that have shaped today''s rural world. They will also explore how equity, diversity, and inclusionary practices play out in rural communities and how rural communities respond to challenges and build resilience. Prerequisite(s): Third-year standing in BCD or ESST or permission of the Department.', 'CODE', 3, 0, 3, '[{"codes":["3rd-year","standing","(55h","or","more","completed)"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13734', 'BIOL-2453', 'Introduction to Microbiology', 'This course introduces the interactions of bacteria, archaea, protists, fungi, and viruses with the human environment, including the important roles of these microbes in production and spoilage of food and beverages, in benefitting human health, in causing human disease, and in shaping the human immune system. (3h lab). This course is recommended for Nutrition majors.  Antirequisite(s): Credit can be obtained for only one of or BIOL 2453, BIOL 2053, or BIOL 2253.', 'BIOL', 3, 0, 2, '[{"codes":["BIOL","1113,","or","BIOL","1813,","or","BIOL","1853,","or","BIOL","2853,","with","a","minimum","grade","of","C-;","CHEM","1013","is","highly","recommended"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["BIOL-2450L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13735', 'BIOL-2450L', 'Biol 2453 Laboratory', '', 'BIOL', 0, 1, 2, '[{"codes":["BIOL-2453"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13737', 'BIOL-4193', 'One Health', 'A focus on the interconnection of human, animal, and environmental health. We explore our roles as biologists in the One Health perspective through themes such as biodiversity loss, pandemics, pollution, and the rise of antibiotic resistance. Emphasis on understanding biological mechanisms coupled with multidisciplinary perspectives.', 'BIOL', 3, 0, 4, '[{"codes":["Completion","of","the","Biology","Core,","with","each","course","completed","with","a","minimum","grade","of","C-"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13738', 'BIOL-4683', 'Biology of Cancer', 'This course will explore the cellular and molecular basis of human cancer. Topics will include the various forms of cancer, genetics of cancer, and historical and modern treatment strategies. The goal is to remove the mystery behind cancer and understand the biological processes behind development, diagnoses and treatment of cancer.', 'BIOL', 3, 0, 4, '[{"codes":["BIOL-3613","with","a","minimum","grade","C-"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13740', 'BIOL-4033', 'Scientific Writing', 'An introduction to writing clearly for scientists and to communicating research to broad audiences. Through lectures, short exercises, written assignments, workshops, journaling, peer review and presentations, this course will teach writing for scientific, government, and community audiences, including communciating science through written media and a policy brief.', 'BIOL', 3, 0, 4, '[{"codes":["Completion","of","the","Biology","Core,","with","each","course","completed","with","a","minimum","grade","of","C-"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13742', 'CHEM-3910', 'Chemistry Seminar 1', 'A weekly seminar course covering an introduction to a broad range of research topics of current relevance to chemistry and related fields of study. Speakers include faculty from within and outside Acadia University.', 'CHEM', 0, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13743', 'CHEM-3920', 'Chemistry Seminar 2', 'A weekly seminar course covering further exposure to a broad range of research topics of current relevance to chemistry and related fields of study. Speakers include faculty from within and outside Acadia University.', 'CHEM', 0, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13746', 'BIOL-4663', 'Bioinformatics', 'An introduction to the analysis of biological data using computational tools. Using R programming, students will apply and interpret bioinformatic techniques including genetic mapping, microbiome analysis, and RNA-sequencing. This course will include examples of applications across biological fields such as human health, agriculture, and conservation. Biology Majors may use BIOL 4663 to either fulfill the Biology Core or as credit toward the BIOL 3000-4000 requirement, but not both. Antirequisite(s): Credit can be obtained for only one of BIOL 4663 or COMP 4663.', 'BIOL', 3, 0, 4, '[{"codes":["BIOL","2013","and","one","other","3h","2000-level","BIOL,","MATH","1253,","MATH","2243,","each","completed","with","a","minimum","grade","of","C-"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13747', 'COMP-4663', 'Bioinformatics', 'An introduction to the analysis of biological data using computational tools. Using R programming, students will apply and interpret  bioinformatic techniques including genetic mapping, microbiome analysis, and RNA-sequencing. This course will include examples of applications across biological fields such as human health, agriculture, and conservation. Some biology background is an asset. Antirequisite(s): Credit can be obtained for only one of COMP 4663 or BIOL 4663.', 'COMP', 3, 0, 4, '[{"codes":["COMP-2113,","MATH-1253"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13748', 'BUSI-3523', 'Sustainable Technologies', 'This course will examine the role of technology in the context of sustainability. Utilizing innovation, societal, political and historical perspectives the course examines how technological development has contributed both positively and negatively to the environmental crisis. Technological innovations across multiple sectors will be explored. Antirequisite(s): Credit can be obtained for only one of ESST 3523 or BUSI 3523.', 'BUSI', 3, 0, 3, '[{"codes":["(ESST-1023","and","ESST","2003),","or","BUSI","1703,","or","permission","of","the","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13749', 'POLS-3163', 'Law, Religion, Modern State', 'This course examines the relationship - sometimes productive, occasionally violent, never boring - between law and religion in the modern state. It explores the role of religion in historical processes of colonization, decolonization, and state-building and analyzes how governments in places like Israel, India, Nigeria, and the United States attempt to shape religion''s place in public life.', 'POLS', 3, 0, 3, '[{"codes":["30h","or","more","completed"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13752', 'HIST-2673', 'Witchcraft & Magic', '???This course examines social, cultural, and legal histories of witchcraft, magic, and the occult. Considering ancient, medieval, early modern, and modern settings the course explores how attitudes and actions around witchcraft and the supernatural intersect with histories of gender, race, class, colonialism, religion, science, and popular culture. Students examine a wide array of primary sources from diverse historical contexts.?', 'HIST', 3, 0, 2, '[{"codes":["Minimum","second-year","standing"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13754', 'HIST-2683', 'Forensic Archaeology', 'Forensic Archaeology: Clandestine Burials, Mass Graves, Crash Sites and Human Rights Introduction to the archaeological methods and theories used to assist in the investigation of forensics and the recovery of human remains. MIA cases from past conflicts will be examined to provide students with hands-on experience of determining when and how a case moves from desk-based work into the field. International humanitarian forensics and international crimes will also be discussed.', 'HIST', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13755', 'ENGL-2803', 'Intro to Indigenous Literature', 'This course will introduce students to the Indigenous literatures of Turtle Island with a focus on Canadian writers combined with a few seminal works from the United States. Topics may include gender and sexuality, impacts of colonization, the land and the environment, identity, culture and spirituality, family and kinship.', 'ENGL', 3, 0, 2, '[{"codes":["ENGL-1483/ENGL-1493","or","ENGL-1413/ENGL-1423","or","ENGL-1406","with","minimum","grade","C-"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13756', 'ENGL-3623', 'Literary Animals', 'This course will examine the roles that animals play in literature and introduce students to key concepts in the field of animal studies.', 'ENGL', 3, 0, 3, '[{"codes":["ENGL-1483/ENGL-1493","or","ENGL-1413/ENGL-1423","with","a","minimum","grade","of","C-"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13757', 'ENGL-3653', 'Postcolonial Cultures', 'This course will introduce students to the fields of postcolonial literature and scholarship through a focus on a range of literary texts, from novels and poetry to film and art alongside history, politics, and culture. Students will learn about colonization, decolonization, settler colonialism, race, nation, empire, and the diaspora.', 'ENGL', 3, 0, 3, '[{"codes":["ENGL-1483/ENGL-1493","or","ENGL-1413/ENGL-1423","or","ENGL-1406","with","a","minimum","grade","of","C-"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13759', 'SOCI-2023', 'Sociology of Law', 'This course examines law as a social phenomenon enmeshed in ''everyday life'', rather than conceiving of law as existing only in official institutions (courts or legislatures), in legal documents (acts, regulations, and orders) or practiced by ''legal actors'' (lawyers, judges and police officers). Through various theoretical approaches, students will analyze legal change and the risk of law in social organizations.', 'SOCI', 3, 0, 2, '[{"codes":["3h","of","1000-level","SOCI","and","second-year","standing,","or","permission","of","the","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13761', 'PACC-5043', 'Pastoral Care Skills', 'This course introduces basic counseling skills that contribute to formation of a collaborative, caring relationship.  Topics include active listening skills, understanding meaning, goal setting and conflict management from emotional, relational, and spiritual perspectives. Students will practice skills through a variety of learning activities. Through self-reflection, each person will continue to form their own identity as a caregiver.', 'PACC', 3, 0, 5, '[{"codes":["PACC-3013,","PACC-5013"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13777', 'DMIN-8143', 'Group Spiritual Formation', 'Participants will establish an interactive learning and spiritual accompaniment relationship with fellow Doctor of Ministry students and enriched with spiritual formation instruction. For the duration of the course, students meet in a series of scheduled online soul care sessions to learn and participate in spiritual formation principles and practices. These will be designed and facilitated in such a way as to allow participants to reflect with others on their own specific spiritual and leadership contexts.', 'DMIN', 3, 0, 8, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13802', 'LANG-1133', '1000 Level LANG Elective', '', 'LANG', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13807', 'COMP-5143', 'Software Foundations', 'This course covers key mathematical concepts for reliable software development, including logic, computer-assisted theorem proving, and the Coq proof assistant, all of which are essential tools for building robust software. Students will also explore functional programming, operational semantics, Hoare logic, and static type systems. This course emphasizes formal verification techniques to help students ensure the correctness of their software designs.', 'COMP', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13808', 'COMP-5423', 'Cryptography, Network Security', 'This course covers the core principles or cryptography and network security. Students will explore classical encryption techniques such as substitution, transposition, and product ciphers, and moder algorithms like RSA. For network security, the course examines secure communication protocols, firewalls, IDS, and defenses against network attacks. Students will be able to design secure cryptographic systems and protect computer networks.', 'COMP', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13809', 'COMP-5163', 'Internet of Things Programming', 'This course will investigate the Internet of Things (IoT) as a network of objects or "things" embedded with electronics, software and sensors connected on networks enabling them to collect or exchange information. Students will also learn to program and enable devices to collect or exchange information.', 'COMP', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13810', 'COMP-5463', 'Principles of Programming', 'This course will cover topics including the History of Programming languages, programming paradigms, language design, syntax, semantics and its specifications. This course is intended to provide the student with a firm grounding in a range of concepts and constructs in the theory and practice of programming languages.', 'COMP', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13811', 'COMP-5453', 'Knowledge Rep. and Reasoning', 'This course provides and overview on the core of Symbolic AI, covering key topics such as Propositional and First-Order Logic, Non-Monotonic Logics, and techniques for Reasoning under Uncertainty: Probabilistic and possibilistic logics. Students will explore advanced methods like Bayesian Networks and their applications in decision-making under uncertainty, as well as planning techniques. The course also covers Case-Based Reasoning for problem solving.', 'COMP', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13812', 'COMP-5443', 'Image Processing', 'This course introduces the fundamental concepts of digital image processing from a practical standpoint, while providing essential theoretical background. Key topics will include image acquisition, processing techniques, practical application, and basic image analysis algorithms. The course is designed to make digital image processing accessible to computer scientists and engineers with little prior experience in the subject.', 'COMP', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13813', 'COMP-5433', 'Evolutionary Computation', 'This course focuses on population-based intelligence models to simulate biological evolution for stochastic search. Necessary algorithm design considerations including representations, cost functions, and credit assignment mechanisms. The course will primarily focus on three main paradigms: Genetic Algorithms, Genetic Programming. Special attention will be given to co-evolution, multi-objective optimization and automatic program decomposition.', 'COMP', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13814', 'COMP-5183', 'ML With Real-World Data', 'This course will focus on working with limited/noisy data to build accurate models useable in real-world situations with data mimicking or from a real-world source. Deep and shallow learning approaches will be explored, with proper data analysis and preparation techniques. Time-series data analysis will be performed. Students will learn to merge these predictive models into a simulated business system.', 'COMP', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13815', 'COMP-5543', 'Data Mining', 'This course will introduce basic data mining techniques such as preprocessing (e.g., aggregation, sampling and dimensionality reduction), pattern mining, classification (e.g., decision trees, rules), prediction modelling (e.g., Bayesian networks, nearest neighbours), cluster analysis, and outlier detection before covering more advanced data mining techniques such as advanced clustering (e.g., graph-based and fuzzy clustering), infrequent patterns, machine learning and avoiding false discoveries.', 'COMP', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13816', 'COMP-5563', 'Computer Vision', 'This course introduces the core concepts of computer vision covering the essential methodologies and techniques. Students will study the theory behind essential tasks such as semantic segmentation, feature extraction, image classification, and object detection. By course completion, students will be equipped to apply fundamental computer vision principles and tools to solve practical problems in both scientific and commercial contexts.', 'COMP', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13817', 'COMP-5583', 'Multi-Agent Systems', 'This course provides an overview of state-of-the-art agent and multi-agent technologies and their applications, with special emphasis on the core issues involved in the research of agent-based systems. This course covers agent architectures, agents'' behaviours, coordination and inter-agent communication. Pervasive, ubiquitous and cloud computing and how agent systems can be applied in these environments will be covered.', 'COMP', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13818', 'COMP-5573', 'High Perf & Parallel Computing', 'This course will examine contemporary tools, methodologies, and strategies fundamental to modern parallel problem-solving. The focus will be on software resources, but will also examine associated hardware architectures employed to achieve parallelism in computationally intensive tasks, with students solving real-world problems on existing parallel machines. Students will read recent research publications and participate in a significant parallel project implementation.', 'COMP', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13819', 'COMP-5513', 'Intro to Intelligent Systems', 'This course constructs prototype intelligent systems using state-of-the-art Artificial Intelligence (AI) techniques and explores rule-based and statistical approaches to AI. Students will create computer programs that use Natural Language Processing (NLP) to respond to commands written in English and learn how to design Machine Learning (ML) systems that can solve difficult problems by learning from examples.', 'COMP', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13820', 'COMP-5173', 'Neural Networks', 'This course introduces the history and algorithms in neural networks, covering topics like perceptron, gradient descent learning algorithm, backpropagation, linear-separability, multi-layer perceptron, Hopefield network, self-organizing maps, restricted Boltzmann machine, self-supervised learning. Students will delve into advanced topics on deep neural network architectures like Convolutional Neural Network (CNN), Recurrent Neural Network (RNN), Long Sort-Term Memory (LSTM), Generative Adversarial Network (GAN).', 'COMP', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13821', 'COMP-5153', 'AI in Computer Security', 'This course explores how AI enhances security systems and protects them. Topics include machine learning algorithms, anomaly detection, and AI-driven automation in tasks like IDS, malware analysis. Students will gain practical insights for both offensive and defensive cybersecurity applications preparing them for the challenge of today''s security landscape. Protection strategies on AI model security also will be discussed.', 'COMP', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13822', 'EDUC-50P3', 'Couns Prac 1 & Grp Supervision', 'Students partcipate in a minimum 100 hours intital supervised counselling practicum that necessitates one day per week availability for a 16-week placement necessary to meet initial practicum requirements. During this practicum, students complete a minimum of 50 hours of direct service with clients, 10 hours of which must be group work. The practicum is accompanied by a 36-hour group supervision class to support practicum students'' professional growth and development during the practicum period.', 'EDUC', 3, 0, 5, '[{"codes":["EDUC-50F3,","EDUC-50D3,","EDUC-5033,","EDUC-5133,","and","EDUC-5623"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13823', 'KINE-5883', 'Applied Independent Study', 'A substantial evaluation or study chosen in consultation with a faculty advisor to reflect student interest. Such a study may be based on field, laboratory, or library study.', 'KINE', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13824', 'KINE-5140L', 'Advanced Assessment 1 Lab', '', 'KINE', 0, 1, 5, '[{"codes":["KINE-5143",""],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13825', 'BUSI-3343', 'Wine & Beverage Marketing', 'Students will learn to design, deliver, and promote wine and beverage products, services, and experiences that will satisfy customers. They will learn research and measurement tools to help them make informed choices about the best promotional tools (e.g., digital) to use in a regulated market. Students will have practical experiences at local wineries, cideries, craft breweries, and distilleries. Prerequisite(s): Third-year standing and 19 years of age or older.', 'BUSI', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13826', 'PSYC-4243', 'Writing for Psych Science', 'This course focuses on developing effective writing skills for communicating psychological science to various audiences, including the public. Through readings, writing exercises, and workshops, students will enhance their transferable communication abilities. Weekly assignments will undergo peer review, and guest lectures from science writers will enrich the learning experience. Prerequisite(s): PSYC 2013 and PSYC 2023.', 'PSYC', 3, 0, 4, '[{"codes":["PSYC-2013","and","PSYC-2023"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13827', 'PSYC-4233', 'Intergroup Relations', 'An in-depth exploration of intergroup relations from a social psychological perspective. Theory and research about the processes involved in stereotyping, prejudice, and discrimination. Students will learn about empirical research in the field of intergroup relations and will emerge from the course with an understanding of stereotyping, prejudice, and discrimination theory and research. Prerequisite(s): PSYC 2013 and PSYC 2103.', 'PSYC', 3, 0, 4, '[{"codes":["PSYC-2013","and","PSYC-2103;"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13829', 'LAWS-1013', 'Intro Law & Society for Majors', 'Introduces the relationships between law and Canadian society. Students examine different types of law and legal systems, including Indigenous law, the judicial system, the legal profession, and the institutional, social, and cultural contexts in which laws are made and enforced. Prerequisite(s): This course is restricted to Law and Society majors. Non-majors should register for LAWS 1003. Antirequisite(s): Credit can only be obtained for one of LAWS 1003 or LAWS 1013.', 'LAWS', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13830', 'EDUC-50N3', 'Couns Prac 2 & Grp Supervision', 'Students participate in a minimum 400-hour supervised counselling internship that is completed on a full-time or part-time bases. During internship, students complete a minimum 200 hours of direct client service, 40 of which must be group work. The practicum is accompanied by a 36-hour group supervision class to support practicum interns'' professional growth and development during the practicum period.', 'EDUC', 3, 0, 5, '[{"codes":["EDUC-50F3,","EDUC-50D3,","EDUC-5033,","EDUC-5133,","EDUC-5623,","and","","EDUC-50P3"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13831', 'ECON-3363', 'Law and Economics', 'This course examines three avenues of law - property, contracts, and crime & punishment - to characterise how economic principles have guided significant developments in law and how economic analysis can be used to assess, critique, and improve current law and public policy decision making. Prerequisite(s): ECON 1013.', 'ECON', 3, 0, 3, '[{"codes":["ECON-1013;"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13832', 'MATH-1603', 'Fundamentals of Academic Math', 'This course is designed to assist students with the transition from high school mathematics to university mathematics. Topics include the study of algebraic expressions including polynomial, exponential, rational, and radical expressions; linear inequalities; problem solving; and an introduction to logic sets. This course may not be used to satisfy Mathematics requirements for any degree program. Prerequisite(s): Permission of the instructor. Antirequisite(s): Students who have received credit for any other MATH 1000 level course may not subsequently receive credit for this course.', 'MATH', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13833', 'PACC-6063', 'Theories of Counselling', 'This course surveys the major theories of psychological functioning and psychotherapy and will review the benefits and limitations of each.  Students will learn about evidence based and best practice approaches for many problem areas and to incorporate current research findings into caring plans. Discussions will include an understanding of human behaviour through biological, emotional, cognitive, spiritual, social and cultural perspectives.', 'PACC', 3, 0, 6, '[{"codes":["PACC-5013"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13834', 'PACC-7073', 'Counselling Practicum Seminar', 'This seminar is a professional development course to accompany PACC 7079 Supervised Clinical Practicum. Students will reflect with their peers on their experiences in the clinical practicum with consideration of assessment / conceptualization, care / treatment approaches, client goal setting, professional ethics, as well as their own response to the emotional process of counselling. Building a pattern of peer mentorship, ongoing learning, and self-care is a key goal of this course. Must be taken concurrently with PACC 7079 Supervised Clinical Practicum.', 'PACC', 3, 0, 7, '[{"codes":["PACC-7123"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13835', 'PACC-7123', 'Advanced Counselling Skills', 'In this course, students receive training in counseling skills from Acceptance and Commitment Therapy (ACT).? ACT is an evidence-based and action-oriented treatment approach that encourages people to face ongoing negative emotions and to move forward in their lives in accordance with their personal values and beliefs.? Students will learn and practice skills in assessment, goal setting, the core processes of therapy, and measurement of progress.? Discussion will also focus on how problems can perpetuate at the cognitive, affective, behavioural, relational, and spiritual levels.', 'PACC', 3, 0, 7, '[{"codes":["PACC-5013","and","PACC-5043"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13836', 'PACC-7079', 'Supervised Clinical Practicum', 'Students complete a clinical practicum in a supervised counselling setting. Students must apply and be accepted to a counselling setting that fits with their intended area of practice and the setting must be approved by ADC. Students will complete a minimum of 400 hours of supervised experience and instruction that includes a minimum of 120 hours of direct services (individual, family, or group) covering all stages of counselling with a variety of problem areas. Must be taken concurrently with PACC 7073 Counselling Practicum Seminar.', 'PACC', 9, 0, 7, '[{"codes":["PACC-7123"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13838', 'KINE-3060L', 'AT Practicum Lab 1', '', 'KINE', 0, 1, 3, '[{"codes":["KINE-3063"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13839', 'KINE-3070L', 'AT Practicum 2 Lab', '', 'KINE', 0, 1, 3, '[{"codes":["KINE-3073"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13840', 'KINE-4110L', 'AT Practicum 3 Lab', '', 'KINE', 0, 1, 4, '[{"codes":["KINE-4113"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13841', 'KINE-4120L', 'AT Practicum 4 Lab', '', 'KINE', 0, 1, 4, '[{"codes":["KINE-4123"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13842', 'BIOL-2003', 'Introduction to Cell Biology', 'This course covers the structure and function of the cell. The structure of prokaryotic and eukaryotic cells is explored with an emphasis on the functions of various organelles in the cell. Topics include organization of the cell, cellular metabolism, cell cycle, and cell communication. This course is meant for non-Biology majors and cannot be used for Biology major credit. Prerequisite(s): High school Biology or Chemistry, and completion of 27 credit hours. Antirequisite(s): Credit can be obtained for only one of BIOL 2003 or BIOL 2013.', 'BIOL', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13843', 'BIOL-4003', 'Plants, Habitats, Climate Chng', 'An in-depth look at major habitats found in tropical, temperate, boreal and Arctic regions and the plans that grow there. We explore the habitat''s abiotic and biotic features, and plant strategies that make them successful in these habitats. We discuss how plants can adapt to climate change and environmental change, and the impacts of change on plant communities. Prerequisite(s): BIOL 1113/1123, and either BIOL 2033 or BIOL 2043 with minimum grades of C-, or permission of the instructor.', 'BIOL', 3, 0, 4, '[{"codes":["BIOL-1113/BIOL-1123","and","either","BIOL-2033","or","BIOL-2043","with","minimum","grades","of","C-,","or","permission","of","the","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13844', 'BIOL-4103', 'Animal Ecophys Climate Change', 'This course focus on past, present, and projected changes in ecosystems brought about naturally and anthropogenically and their impact on animal inhabitants. The early material focuses on physiochemical changes in environmental conditions, shifting toward an understanding of how such changes influence the physiology and behaviour of different taxa. Laboratory exercises focus on how invertebrate models respond to changing climates. (3h lab).', 'BIOL', 3, 0, 4, '[{"codes":["BIOL-2013","and","BIOL-2073","each","with","a","minimum","grade","of","C-"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["BIOL-4100L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13848', 'BIOL-4100L', 'Animal Ecophys Climate Lab', '', 'BIOL', 0, 1, 4, '[{"codes":["BIOL-4103"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13849', 'BUSI-3093', 'Sustainable Acct & Report', 'The accounting profession is expanding to include areas of sustainability including environmental, social and governance (ESG) factors. In this course, students will gain insight to the rapidly evolving sustainability standards, including the IFRS Disclosure Standards, and the application of other non-financial reporting sustainability frameworks.', 'BUSI', 3, 0, 3, '[{"codes":["BUSI-2033"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13850', 'ENVS-5900', 'ENVS Graduate Seminar 1', 'Review of current research topics and problems in Environmental Science. Instruction on presenting seminars, writing papers and preparing abstracts may be included. Weekly seminars will be held throughout the year. It may be co-taught with GEOL 5900 and GEOM 5900.', 'ENVS', 0, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13851', 'ENVS-5903', 'ENVS Graduate Seminar 2', 'Review of current research topics and problems in Environmental Science. Instruction on presenting seminars, writing papers and preparing abstracts may be included. Weekly seminars will be held throughout the year. It may be co-taught with GEOL 5903 and GEOM 5903.', 'ENVS', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13852', 'ESST-3533', 'Pol Ecology of the Maritimes', 'This course explores the connection between environmental processes, economies, and social power relations through a local focus  on the Maritime region. Students will read political and ecological theory, explore historical and contemporary examples from the  Maritime context, and apply theoretical lessons through experimental assignments.', 'ESST', 3, 0, 3, '[{"codes":["ESST-2013"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13853', 'ESST-3603', 'Sustainable Food Systems', 'This course uses an experiential approach to understanding sustainable food systems theory and practice. Using readings, critical  discussions, project work, and engagement with community organizations, students will explore concepts and applications of food-citizenship,  -sovereignty, -security, -policy, and sustainability. Students will learn foundational food skills, broadening their capacity as growers and eaters through hands-on activities and field trips. Antirequisite(s): CODE 3603.', 'ESST', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13854', 'CLAS-1813', 'Intro Greek & Roman Lit.', 'An introduction to the literature of the ancient Greeks and Romans (in translation), including a range of ancient genres (including epic poetry, drama, and the novel) and themes. This course will familiarize students with some of the unique elements of the study of ancient literature and basic concepts in narrative theory.', 'CLAS', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13855', 'CLAS-2453', 'History Alive! Greece & Rome', 'In this course, students will bring ancient history to life by playing two full "Reacting to the Past" games: "The Threshold of Democracy:  Athens in 403 BCE" and "The Crisis of Catiline: Rome, 63 BCE". Students are assigned character roles with specific goals: they must communicate effectively, collaborate, and compete to advance their objectives to try to "win" the game.', 'CLAS', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13856', 'HIST-2453', 'History Alive! Greece & Rome', 'In this course, students will bring ancient history to life by playing two full "Reacting to the Past" games: "The Threshold of Democracy:  Athens in 403 BCE" and "The Crisis of Catiline: Rome, 63 BCE". Students are assigned character roles with specific goals: they must communicate effectively, collaborate, and compete to advance their objectives to try to "win" the game.', 'HIST', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13858', 'SOCI-2373', 'Emotions and Society', 'This course introduces sociological approaches to the study of emotions. Topics include emotional labour, feeling rules, collective emotions, public and political emotions, changes in the norms and patterns of emotion over time, and emotions in relation to activism, gender, class, racialization, nationalism, social media, violence and conflict.', 'SOCI', 3, 0, 2, '[{"codes":["3h","of","1000-level","SOCI","and","second-year","standing,","or","permission","of","the","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13860', 'SOCI-5433', 'Class Gender Indigeneity Race', 'This course examines exemplary analyses of the intersection of class, gender, Indigeneity, and racialization in a variety of social settings. Antirequisite(s): SOCI 4413.', 'SOCI', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13861', 'SOCI-5233', 'Global Health', 'This course examines the local and transnational relations governing health and health care in global south settings. We investigate the relative role of international groups, nations, and local health care providers in shaping how health care is received (and not received). Topics include: political violence and care in conflict settings; poverty, structural violence, and neoliberalism; and diverging ideas about bodies and healing. Prerequisite(s): Restricted to graduate students in the Faculty of Arts. Antirequisite(s): SOCI 4223.', 'SOCI', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13862', 'POLS-3253', 'Political Ethics', 'This course explores key questions about the relationship between politics and ethics. It examines both historical and contemporary theoretical debates on the role of ethics in politics and the politics of ethics, and applies them to such practical issues as leadership and governance, institutions and expressions of power, norms and exclusions, and conflicts and resistance. Prerequisite(s): Minimum second year standing, or enrolment in the Certificate in Democratic Leadership program.', 'POLS', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13863', 'POLS-2023', 'Intro to Democratic Leadership', 'This course examines ways that leaders exercise leadership in democratic contexts. Topics to be discussed include ethical leadership, public responsibilities, and challenges that political leaders face in a complex, globalized world.', 'POLS', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13864', 'POLS-3263', 'Ir & Global South', 'This course introduces students to diverse Global South perspectives in the field of International Relations (IR). Focusing on issues such as colonialism, decolonization, sovereignty, security, and nationalism, it highlights both the omission and contributions of the Global South to the field. In doing so, it enables students to critically engage with central issues in the field of IR.', 'POLS', 3, 0, 3, '[{"codes":["POLS-2683"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13865', 'PHYS-4523', 'Physics Research Special Topic', 'Completion of a physics research project with faculty supervisor(s), including a written report presented to the department. Prerequisite(s): Permission of the department. Antirequisite(s): PHYS 407T and PHYS 408T.', 'PHYS', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13866', 'PHYS-3563', 'Cosmology', 'Modern cosmology entered a new era with the launch of the James Webb Space Telescope. This course investigates the hot Big Bang cosmological model in which our universe evolved from a dense, hot soup of elementary particles to being filled today with radiation, stars, galaxies, black holes, and dark matter. Einstein''s General Theory of Relativity is introduced.', 'PHYS', 3, 0, 3, '[{"codes":["PHYS-2113","or","PHYS-2123,","and","PHYS-2413","or","PHYS-2423"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13867', 'PHYS-3553', 'Stellar Astrophysics', 'Beginning with binary stars as tools for determining stellar properties, we then discuss spectral classification. The physics underlying stellar models is developed and hydrogen-burning stars like the Sun are discussed. Students will have the opportunity to complete observing projects in the Acadia Observatory.', 'PHYS', 3, 0, 3, '[{"codes":["PHYS-2113","or","PHYS-2123,","and","PHYS-2413","or","PHYS-2423"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["PHYS-3343","and","PHYS-3433"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13868', 'ESST-4000L', 'ESST Capstone Lab', 'This lab provides an experiential capstone experience for ESST students in their final year of study. It will provide experiential opportunities to strengthen connections to community and landscape, facilitate a retrospective reflection supporting students in articulating key learning and takeaways from the program, celebrate the students'' collective journey, and support graduating students in the transition out of the program and into future endeavours. This is an immersive, experiential lab that takes place over 2 days in the winter semester. Exact dates will be confirmed early in the winter semester with input from graduating students.', 'ESST', 0, 1, 4, '[{"codes":["ESST-4003"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13870', 'CLAS-3013', 'Pompeii and Herculaneum', 'An examination of the archaeological sites of Pompeii and Herculaneum. Topics include destruction, discovery, and conservation; the use of literary and epigraphic evidence with material culture to reconstruct social, political and religious life; the economic role of the countryside; and the reception, collection and ownership of archaeological remains.', 'CLAS', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13871', 'ESST-2023', 'Land-Based Learning', 'This course uses an experiential approach to providing practices, skills, tools, and applied frameworks for land-based learning, cultivating resilience, and building capacity for joy, connection, and rest while working for transformative change. It aims to better resource students doing sustainability work, acknowledging that challenging emotions and queries can arise in learning about the current state of the environment and society.', 'ESST', 3, 0, 2, '[{"codes":["ESST-1003"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13872', 'HIST-4023', 'Honours Seminar', 'This course will help prepare students for writing an Honours Thesis. Students will explore the process of writing a thesis, from initial idea, through creating proposals, and doing research and writing on this scale. Other topics may include grant applications, conferences, publishing, graduate programs, and careers in the field. Evaluation is on a Pass/Fail basis. Prerequisite: Permission of the Department', 'HIST', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13873', 'BIBL-2033', 'Christian Scriptures 1', 'This course is a thorough reading of the entire Bible from Genesis to Revelation. Students will explore the central themes, narratives, and key figures of each biblical book, focusing on the primary content and context. By the end, students will comprehend the structure and unity of the biblical canon and how each book contributes to the overarching biblical narrative. Through weekly reading assignments and discussions, participants will develop a deeper familiarity with these foundational texts. The course is content-driven, emphasizing comprehension and retention of key content.', 'BIBL', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13874', 'BIBL-2043', 'Christian Scriptures 2', 'This course is a continuation of BIBL 2033, providing a thorough reading of the entire Bible from Genesis to Revelation. Students will explore the central themes, narratives, and key figures of each biblical book, focusing on the primary content and context. By the end, students will comprehend the structure and unity of the biblical canon and how each book contributes to the overarching biblical narrative. Through weekly reading assignments and discussions, participants will develop a deeper familiarity with these foundational texts. The course is content-driven, emphasizing comprehension and retention of key content.', 'BIBL', 3, 0, 2, '[{"codes":["BIBL-2033"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13875', 'BIBL-2053', 'Intro to the Christian Bible', 'This course introduces students to the Christian Bible, its structure, and its significance for faith and culture. Students will learn basic facts about the Bible, including its overall story and key figures. They will explore the different types of writing found in Scripture, such as history, poetry, and letters, and how these genres shape meaning. The course also examines the basic histories and geographies in which the Bible was written and addressed. Designed for beginners, this course provides a foundation for understanding the Bible''s message and its impact on the world.', 'BIBL', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13876', 'CHUR-2043', 'Intro to Christian History 2', 'This course explores the history of Christianity from the 16th century to the present, examining key movements, theological shifts, and global expansion. Students will study the impact of the Reformation and Catholic Reformation, the rise of evangelicalism, and Christianity''s engagement with modernity. Special attention is given to the role of Christianity in Canada, including its influence on colonization and the history of Indian residential schools. Through historical analysis and discussion, students will gain insight into the development of Christian traditions and their ongoing impact in contemporary society.', 'CHUR', 3, 0, 2, '[{"codes":["CHUR-2033"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13877', 'CHUR-3033', 'World Christianity', 'From its early days, Christianity has developed across many different cultural contexts. This course explores the dynamic landscape of world Christianity. Students will learn about history, demographics, distinctives, theology, and trends related to Christianity in various regions of the world. Special attention will be given to Christianity in the Global South.', 'CHUR', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13878', 'IDTH-2012', 'Integration and Formation 1', 'This course introduces students to foundational academic skills and the importance of community in theological education. Students will learn strategies for academic success, including time management, reading and writing critically, practicing academic integrity, and conducting quality research. A strong emphasis is placed on building a supportive cohort community and beginning the process of personal and intercultural self-awareness through assessments. Through group activities, practical exercises, and reflective learning, students will grow in confidence as learners and community members, equipped for the journey of theological study. IDTH 2012 and IDTH 2022 are normally taken in a student''s first year.', 'IDTH', 2, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13879', 'IDTH-2022', 'Integration and Formation 2', 'Building on the foundation of IDTH 2013, this course deepens students'' engagement with community, self-awareness, and faith formation. Students will revisit and reflect on their intercultural and personality assessments to explore how these insights shape their approach to learning, relationships, and Christian discipleship. Emphasis is placed on fostering a reflective posture toward one''s spiritual growth and communal life within the cohort. Through guided discussions, personal reflection, and continued community-building, students will be encouraged to integrate their academic journey with their formation as disciples and members of a learning community. IDTH 2012 and IDTH 2022 are normally taken in a student''s first year.', 'IDTH', 2, 0, 2, '[{"codes":["IDTH-2012"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13880', 'NXGN-3053', 'Cont Topics in Youth Ministry', 'This course explores contemporary issues in youth culture, drawing on insights from current research and applying them to Next Generation ministry. Students will examine these topics through biblical, theological, and pastoral lenses, reflecting on their significance and developing thoughtful, contextually relevant responses for the young people they serve.', 'NXGN', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13881', 'PAST-2002', 'Serving Experience 1', 'This pass/fail course is a guided service experience designed to integrate theological learning with hands-on service. Students will complete a minimum of 60 hours in a setting of their choosing (can be paid or volunteer). Students will engage reflectively on their experiences while developing skills relevant to the area of service. This course can take place any time in the year, in a ministry context that is outside their normal experiences. Students are responsible for identifying and securing their own serving position.', 'PAST', 2, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13882', 'PAST-2013', 'Serving Experience 2', 'This pass/fail course is a guided service experience designed to integrate theological learning with hands-on service. Students will complete a minimum of 90 hours in a setting of their choosing (can be paid or volunteer). Students will engage reflectively on their experiences while developing skills relevant to the area of service. This course is suited for the spring or summer months, allowing for immersive engagement in a ministry context that is outside their normal experiences, and different from PAST 2002 Service Experience 1. Students are responsible for identifying and securing their own serving position.', 'PAST', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13883', 'PAST-4033', 'Mentored Ministry 3', 'This course guides students in the formation of pastoral identity and in the development of ministry skills. This will be accomplished in class through the integration of theory and theology under the direction of the professor, and within a healthy local church under the mentorship of a pastor. Minimum of 100 in-ministry hours required. May be completed in the summer or during the fall and winter semesters. Open only to Bachelor of Theology (Ordination Track) students.', 'PAST', 3, 0, 4, '[{"codes":["PAST-4023","and","a","minimum","of","60","credit","hours"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13884', 'PAST-4043', 'Mentored Ministry 4', 'This course guides students in the formation of pastoral identity and in the development of ministry skills. This will be accomplished in class through the integration of theory and theology under the direction of the professor, and within a healthy local church or other approved ministry setting, under the mentorship of a pastor or ministry leader. Minimum of 100 in-ministry hours required. May be completed in the summer or during the fall and winter semesters. Open only to Bachelor of Theology (Ordination Track) students.', 'PAST', 3, 0, 4, '[{"codes":["PAST-4033","and","a","minimum","of","60","credit","hours"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13885', 'THEO-3003', 'Foundational Christian Beliefs', 'This introductory course explores foundational questions in Christian theology, introducing classical and Christian arguments for the existence of God. Students will become familiar with essential Christian doctrines, gaining insight into central beliefs that shape Christianity. The course emphasizes understanding key theological themes and terminology, preparing students for further study in theology. This course provides a foundational understanding that helps students engage meaningfully with theological concepts, equipping them for informed dialogue within diverse religious contexts.', 'THEO', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13886', 'CHUR-5033', 'World Christianity', 'From its early days, Christianity has developed across many different cultural contexts. This course explores the dynamic landscape of world Christianity. Students will learn about history, demographics, distinctives, theology, and trends related to Christianity in various regions of the world. Special attention will be given to Christianity in the Global South.', 'CHUR', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13887', 'CHUR-6053', 'Hist of Christianity in NA', 'This course provides an examination of the history of Christianity in Canada and the United States. It highlights how Christian faith has shaped-and been shaped by-European settlement, interactions with Indigenous, Black, and other racialized communities, and pivotal events such as awakenings, wars, missions, the help and harm of outreach efforts, and social reform movements. The course also explores the emergence of fundamentalism, evangelicalism, and Pentecostalism, as well as recent issues involving church and state. Throughout, students will compare and contrast the influences, similarities, and differences between Christian history in the United States and Canada.', 'CHUR', 3, 0, 6, '[{"codes":["CHUR-5013"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13888', 'NXGN-6053', 'Cont Topics in Youth Ministry', 'This course explores contemporary issues in youth culture, drawing on insights from current research and applying them to Next Generation ministry. Students will examine these topics through biblical, theological, and pastoral lenses, reflecting on their significance and developing thoughtful, contextually relevant responses for the young people they serve.', 'NXGN', 3, 0, 6, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13889', 'LAWS-3023', 'Language & the Law', 'This course surveys the legal basis for language rights at the international, Canadian and provincial levels. Students will study international declarations and treaties; Official and Indigenous language legislation and case law; and provincial and territorial language regimes. They will consider issues such as territoriality/personality principles, collective/private rights, and linguistic human rights. Antirequisite(s): Credit can be obtained for only one of LAWS 3023 or LANG 3023.', 'LAWS', 3, 0, 3, '[{"codes":["LAWS-1003","or","LAWS-1013","and","completion","of","60h"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13890', 'LANG-3023', 'Language & the Law', 'This course surveys the legal basis for language rights at the international, Canadian and provincial levels. Students will study international declarations and treaties; Official and Indigenous language legislation and case law; and provincial and territorial language regimes. They will consider issues such as territoriality/personality principles, collective/private rights, and linguistic human rights. Antirequisite(s): Credit can be obtained for only of one LANG 3023 or LAWS 3023.', 'LANG', 3, 0, 3, '[{"codes":["LAWS-1003","or","LAWS-1013","and","completion","of","60h"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13891', 'CLAS-4023', 'Honours Seminar', 'This course will help prepare students for writing and Honours Thesis. Students will explore the process of writing a thesis, from initial idea, through creating proposals, and doing research and writing on this scale. Other topics may include grant applications, conferences, publishing, graduate programs, and careers in the field. Evaluation is on a Pass/Fail basis. Prerequisite(s): Permission of the Department.', 'CLAS', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13893', 'MATH-1320L', 'MATH 1323 Lab', '', 'MATH', 0, 1, 1, '[{"codes":["MATH-1323"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13894', 'BUSI-9009', 'Busi Administration Elective', '', 'BUSI', 9, 0, 9, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13911', 'ECON-2723', 'Agricultural & Resource Econ', 'This course serves as an introduction to the economic concepts related to agricultural and natural resource production and market outcomes. The primary focus will be on the markets for agricultural products, forests and fisheries, including understanding the factors affecting the demand and supply for these resources and the causes and evaluation of policy responses related to market failure.', 'ECON', 3, 0, 2, '[{"codes":["ECON-1013"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13912', 'ECON-3773', 'Doing Economics', 'The course bridges theory and practice by having students design, execute, and present economic analyses addressing real-world issues across business, policy, and research contexts.', 'ECON', 3, 0, 3, '[{"codes":["ECON-1013,","ECON-1023,","ECON-2613"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13913', 'ENGL-4413', 'Major Research Project', '', 'ENGL', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13914', 'FRAN-3043', 'France: Gaul to Renaissance', 'Through lectures and case studies, students will explore French history from Julius Ceasar''s invasion to the assassination of Henry IV. Themes may include state building, religion, feudalism, war, daily life, trade and education. Course offered in English. Students wishing to have this course count towards a major degree in French will be required to write the assignments in French. Antirequisite(s): Credit can only be obtained for one of FRAN 3043 or HIST 3043.', 'FRAN', 3, 0, 3, '[{"codes":["FRAN-2113","and","FRAN-2123","OR","12h","of","HIST"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13915', 'HIST-3043', 'France: Gaul to Renaissance', 'Through lectures and case studies, students will explore French history from Julius Ceasar''s invasion to the assassination of Henry IV. Themes may include state building, religion, feudalism, war, daily life, trade and education. Course offered in English. Students wishing to have this course count towards a major degree in French will be required to write the assignments in French. Antirequisite(s): Credit can only be obtained for one of FRAN 3043 or HIST 3043.', 'HIST', 3, 0, 3, '[{"codes":["FRAN-2113","and","FRAN-2123;","or","12h","from","HIST"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13916', 'HIST-2943', 'Germany: From War to War', 'Reflections of German political and social history from WWI to WWII. This course explores Germany''s complex social and political history in an interdisciplinary way through literary and historical narratives. It focuses on writers whose work commented on and responded to major historical events from the beginning of World War I to the Third Reich. This course is taught in English. Antirequisite(s): Credit can be obtained for only one of HIST 2943 or GERM 2913.', 'HIST', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13917', 'LAWS-3703', 'Crime and Punishment', 'A cross-cultural and social historical examination of the social response to crime. Topics may include patterns of crime, the history of policing and forms of punishment, the evolution of the penitentiary, and comparative justice models. Antirequisite(s): Credit can be obtained for only one of SOCI 3703 or LAWS 3703.', 'LAWS', 3, 0, 3, '[{"codes":["3h","of","SOCI","or","3h","of","LAWS,","and","second","year","standing"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13918', 'LAWS-2723', 'Canadian Criminal Justice', 'The criminal justice system and the structure of legal regulation and enforcement in Canada. Topics may include policing, court processes, modes of punishment, youth justice, wrongful convictions, and minority groups in the justice system. Antirequisite(s): Credit can be obtained for only one of LAWS 2723 or SOCI 2723.', 'LAWS', 3, 0, 2, '[{"codes":["3h","1000-level","LAWS","or","3h","1000-level","SOCI,","and","second-year","standing"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13919', 'SOCI-3483', 'Race, Migration, Imperialism', 'This course explores how Western imperialism has shaped the contemporary landscape of migration in relation to "race", class, and gender. It examines how colonialism, slavery, and imperial expansion play a role in global systems of mobility, and how these legacies continue to structure today''s gendered and racialized borders, citizenship regimes and migrant hierarchies.', 'SOCI', 3, 0, 3, '[{"codes":["3h","1000-level","SOCI","and","second-year","standing,","or","permission","of","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13920', 'SOCI-3283', 'Reproductive Justice', 'An introduction to reproductive justice, focusing on Canada in international context. Situating reproductive justice as a social movement for bodily autonomy rooted in Black feminist politics, the course examines how health care systems, the law, and culture shape reproductive and sexual lives and how communities respond. Topics include social movements related to menstruation, abortion, maternity care, parenting, and sexual health. This course is open to Nursing students in their second year or above without the usual prerequisites.', 'SOCI', 3, 0, 3, '[{"codes":["3h","of","1000-level","SOCI","and","second-year","standing,","or","permission","of","the","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13922', 'WGST-3713', 'Gender & Race: Workplace Pols', '??This course will examine how social differences such as gender, class, sexuality, race, and ability shape identities and processes within workplace environments. Students will consider social differences not as individual traits but as social processes that are reproduced in the contemporary workplace. Students will investigate this regime of reproduction and propose how normalizing discourses and social hierarchies can be challenged.?', 'WGST', 3, 0, 3, '[{"codes":["WGST-1413","and","second-year","standing"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13923', 'BIOT-4003', 'Research Project Biotech', 'A biotechnology-related research project conducted under the supervision of one (or more) faculty members. The student will take an active role in planning and implementation, and submit a written report upon completion of the project. Seventy-two hours (72h) of research activity, normally involving laboratory or field work, are required. Subject to availability of a suitable research supervisor.', 'BIOT', 3, 0, 4, '[{"codes":["18h","of","lab-based","BIOL","and/or","CHEM","courses"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13924', 'MATH-2113', 'Intro Topics Math & Stats 1', 'Introductory level study of a particular topic in mathematics or statistics. Prerequisite(s): Permission of the Department.', 'MATH', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13925', 'MATH-2123', 'Intro Topics Math & Stats 2', 'Introductory level study of a particular topic in mathematics or statistics. Prerequisite(s): Permission of the Department.', 'MATH', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13926', 'PHYS-2533', 'Special Topics in Physics 1', 'Study of a particular topic in physics in an area not covered in the normal curriculum.', 'PHYS', 3, 0, 2, '[{"codes":["PHYS-1023","or","PHYS-1063,","and","permission","of","the","Department"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13927', 'PHYS-3533', 'Special Topics in Physics 2', 'Study of a particular topic in physics in an area not covered in the normal curriculum.', 'PHYS', 3, 0, 3, '[{"codes":["6h","PHYS","at","2000-level,","and","permission","of","Department"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13928', 'SCIE-1013', 'Topics in Science 1', 'Study of a particular topic in Science.', 'SCIE', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13929', 'SCIE-1023', 'Topics in Science 2', 'Study of a particular topic in Science.', 'SCIE', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13930', 'SCIE-2013', 'Topics in Science 3', 'Study of a particular topic in Science.', 'SCIE', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13931', 'SCIE-2023', 'Topics in Science 4', 'Study of a particular topic in Science.', 'SCIE', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13932', 'KINE-3243', 'Intro Teaching Secondary PE', 'An introduction to foundational issues and concepts for students who want to become teachers of Physical Education at the secondary level (Grades 6-12). The importance of reflecting on one''s prior experience of physical education and of other physical activity contexts will highlight how these experiences profoundly shape one''s thoughts and knowledge about students, teachers, teaching, and curriculum.', 'KINE', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13933', 'KINE-3793', 'Exploring Growth through PA', 'We live in a society that privileges comfort and promotes risk reduction; however, challenging oneself can lead to growth and learning is often a result of failure.  This course explores this tension through the lens of "extreme" physical pursuits, unpacking some of the key psychological and physiological elements underpinning performance in activities including mountain climbing, ultra marathons, and free diving.', 'KINE', 3, 0, 3, '[{"codes":["2nd","year","standing",""],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13934', 'MUSI-1833', 'Theory and Keyboard 2', 'This course continues the rudiments and literacy of western and popular music through keyboard, oral, and aural skills, and introduces functional harmony and voice leading.', 'MUSI', 3, 0, 1, '[{"codes":["MUSI-1813","with","a","minimum","grade","of","C"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13935', 'MUSI-3701', 'Performing Ensemble', 'Performing Ensemble for music majors. Non-music majors may join with permission of the instructor. Students must successfully complete both the fall and winter term of the ensemble. Auditioned ensemble. Prerequisite(s): Permission of the instructor.', 'MUSI', 1, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13936', 'CLAS-3143', 'Topics in Classical Reception', 'An advanced seminar in the reception of ancient Greek and Roman in popular culture. Topics may include an individual media (i.e. comics, video games), specific theories in classical reception and/or media studies (i.e. queer theory, "the gaze"), or the receptions of an individual historical event, narrative, or motif (i.e. Medusa, katabasis, the end of the Roman republic).', 'CLAS', 3, 0, 3, '[{"codes":["CLAS-2583","and","second-year","standing,","or","permission","of","the","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13937', 'CLAS-3153', 'Topics in Greek & Roman Lit', 'A seminar course studying the literature of the ancient Greeks and Romans (read in translation). Topics may include and individual genre (i.e. the epic, tragedy, the novel) or author (i.e. Ovid, Euripides), which will be examined through the narrative and literary theory.', 'CLAS', 3, 0, 3, '[{"codes":["CLAS-1813","and","second-year","standing,","or","permission","of","the","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13938', 'CLAS-3163', 'Pre-Modern Written Sources', 'An introduction to studying written primary sources from the pre-modern world including graffiti, court cases, law codes, letters, wills, literature, and death monuments. This course will familiarize students with basic ancient and medieval written script (palaeography) and focus on the methodology of studying ancient and medieval writing. No prior knowledge of Latin is needed to succeed in this course.', 'CLAS', 3, 0, 3, '[{"codes":["12h","HIST,","CLAS,","or","LATI,","or","permission","of","the","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13940', 'HIST-3863', 'History of Crime & Deviance', 'This course explores the historical cultural constructions of deviance from 500-1500, considering how past societies determined "good" and "bad" behaviour; how they determined what was immoral, sinful, deviant, or criminal. By examining the intersection of crime and deviance from religious, political, legal, and socio-economic factors, students will question the changing definitions of criminal behaviour throughout the Middle Ages and beyond.', 'HIST', 3, 0, 3, '[{"codes":["12h","HIST","courses,","or","permission","of","the","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13941', 'HIST-3963', 'Medieval Violence', 'This course scrutinizes the role of violence in medieval society, 500-1500. Students will study theories of "violence" and consider why medieval societies condemned and legitimized certain forms of violence. This will include looking at religious violence, warfare, executions, rebellions, sport, monstrosity and the construction of the "other", as well as traumascapes and violence in the archives.', 'HIST', 3, 0, 3, '[{"codes":["12h","HIST","courses,","or","permission","of","the","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13943', 'HIST-2923', 'Germany: Division, Unification', 'Reflections of German political and social history from the end of WW II to Reunification through its literature. Readings examine Germany and Germans in the post World War II era, their retrospective interpretation of the war and the Holocaust, and their view of the place of a divided, then reunited Germany in the world. This course is taught in English. Antirequisite(s): Credit can be obtained for only one of HIST 2923 or GERM 2923.', 'HIST', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13944', 'HIST-2833', 'Ancient Greece Culture/Society', 'An introduction to the central aspects of the experience of living in ancient Greece. Topics include legal institutions, gender and sexuality, domestic life, warfare, economic activities, religion and ritual, slavery, commerce, health, athletic competition, philosophy, and the reception of ancient Greece in our modern world. Emphasis will be placed on Athens and Sparta, from the Archaic through the Hellenistic periods.? Antirequisite(s): Credit can be obtained for only one of HIST 2833 or CLAS 2833.', 'HIST', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13946', 'CHEM-4533', 'Medicinal Chem & Drug Design', 'This course explores the history and evolution of drug discovery and regulation, alongside modern drug design principles. Topics include target selection, hit identification, lead optimization, preclinical studies, and clinical trials. Emphasis is placed on diverse design strategies such as ethnopharmacology, in silico modeling, combinatorial chemistry, high-throughput screening, and structure activity relationship studies to develop effective therapeutics.', 'CHEM', 3, 0, 4, '[{"codes":["CHEM-3513","and","CHEM-3723,","or","permission","of","the","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13947', 'CHEM-4503', 'Adv Structure Determination', 'Further investigation of molecular structure determination by modern methods, building on the techniques presented in CHEM 3523. Emphasis is placed on both 1D and 2D nuclear magnetic resonance (NMR) spectroscopy, supplemented by mass spectrometry and IR spectroscopy for structure elucidation. Analysis of compounds with heavy elements will be introduced.', 'CHEM', 3, 0, 4, '[{"codes":["CHEM-3523"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13948', 'BUSI-4343', 'Leadership', '??This course examines core and contemporary leadership theories, behavioural competencies, and leader-follower dynamics. Through case studies, applied exercises, and reflective activities, students develop practical leadership competencies relevant to a variety of organizational settings. Emphasis is placed on developing practical leadership skills applicable in business, non-profits, social enterprises, and public organizations. ?', 'BUSI', 3, 0, 4, '[{"codes":["Third-year","standing","or","higher"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13949', 'BUSI-3713', 'Occupational Health & Safety', '??This course introduces key principles, practices, and legal foundations of workplace health and safety. Students learn to identify, assess, and control hazards; interpret Canadian OHS legislation; and understand employer-employee responsibilities. Through case studies and applied exercises, the course develops skills in incident reporting, investigations, emergency planning, and fostering proactive safety cultures across diverse organizational settings.?', 'BUSI', 3, 0, 3, '[{"codes":["Third-year","standing","or","higher,","or","permission","of","the","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13950', 'BUSI-2913', 'Training and Development', 'This course introduces the principles and practices of employee training and organizational learning. Students examine training needs analysis, instructional design, delivery methods, and evaluation of learning effectiveness. Emphasis is placed on developing evidence-based training programs that support performance improvement, employee growth, and organizational capability across diverse workplace settings.', 'BUSI', 3, 0, 2, '[{"codes":["BUSI-1703,","COMM-1213,","each","with","a","minumum","grade","of","C-"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13951', 'BUSI-3793', 'Innovation', 'An introduction to insights from innovation studies. This course examines taken-for-granted ideas about innovation and where it comes from. Students learn about process and systems models of innovation, conditions of complexity and uncertainty, innovation management techniques, research and development organizations, the pro-innovation bias, problems of techno-solutionism, and the value of social, convivial, and responsible innovation. Includes a hands-on "innovation lab".', 'BUSI', 3, 0, 3, '[{"codes":["Third-year","standing","or","higher,","or","permission","of","the","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13952', 'CODE-3053', 'Sus. Econ Dev and Enterprise', 'This course examines how communities build just, resilient local economies through sustainable development and social enterprise. Students explore co-operatives, social enterprises, and community-owned ventures, using case studies and applied work to assess economic strategies and design initiatives that advance equity, inclusion, sustainability, and community well-being.', 'CODE', 3, 0, 3, '[{"codes":["CODE-1033","and","CODE-2033,","or","permission","of","the","Department"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13953', 'CODE-4073', 'Research & Honours Seminar', 'This seminar supports students undertaking?honours?research in deepening the craft of inquiry within community development. Building on prior coursework in research methods, students refine meaningful research questions, strengthen their research designs, and develop approaches for collecting, analyzing, and interpreting data in ethically grounded and community-responsive ways. Restricted to CODE Honours or graduate students, or permission of the Department.', 'CODE', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13954', 'ART-3053', 'Nature-Based Fashion', 'This course will focus on drawing, designing and painting nature-based art, emphasizing the exploration of native plants at the Harriet Irving Botanical Gardens, as well as Nova Scotia wildlife and accompanying habitat. Form, structure, texture, and shading will be key technical elements developed in the course. There will be an opportunity for students to produce wearable art from their designs.', 'ART', 3, 0, 3, '[{"codes":["ART-2013","and","ART-2023,","or","permission","of","the","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13955', 'IDTH-5001', 'Seminary Orientation', 'Seminary Orientation prepares students for seminary study and their ADC program. Through lectures, demonstrations, practice exercises, readings, testing, and an all-day retreat (for Fall admissions), students will be introduced to various expectations, skills, and resources necessary for advancing successfully through their degrees, and they will also begin their preliminary personal testing. A component of this course is a Bible overview seminar as well as introduction and teaching around responsible AI usage in one''s education.', 'IDTH', 1, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13956', 'BIBL-5022', 'Old Testament Foundations', 'The Old Testament contains most of the Christian Bible. This course introduces students to the major sections and literary genres of the Old Testament and considers how genre shapes meaning. The course also surveys key aspects of the Old Testament''s ancient Near Eastern historical and cultural contexts, highlighting why this background is foundational for responsible interpretation. Throughout, students will develop an awareness of the Old Testament''s ongoing relevance for Christian theology and practice. This course assumes knowledge of the contents of the Old Testament and provides a basis for further biblical and theological study.', 'BIBL', 2, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13957', 'BIBL-5032', 'New Testament Foundations', 'The New Testament Foundations course introduces students to the content, central concepts, and basic methods associated with the academic study of the New Testament. Students will survey the New Testament''s ancient historical, cultural, and religious contexts, with attention to how this background is foundational for responsible interpretation. The course also examines the major literary genres found in the New Testament and considers how genre shapes meaning and theological claims. Throughout, students will be equipped to describe and discuss key themes, purposes, and distinctive voices within the New Testament, providing a foundation for further study in biblical studies, theology, and ministry.', 'BIBL', 2, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13958', 'BIBL-6042', 'Hermeneutics Lab', 'This is a practice-based course in learning methods for interpreting Scripture for Christian ministry. Students work through scaffolded interpretive exercises across selected primary biblical genres, using relevant secondary literature and common analytical tools in biblical studies. The course also introduces a range of hermeneutical approaches and supports students in applying them to the interpretive process. Prerequisites: BIBL 5022 and 5032.', 'BIBL', 2, 0, 6, '[{"codes":["BIBL-5022","and","BIBL-5032"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13959', 'PAST-5011', 'Ministry Integration 1', 'This course introduces students to the nature and responsibilities of pastoral ministry and discernment of personal calling in dialogue with ecclesial affirmation and the Spirit''s leading. It also introduces them to the formative ministry portfolio.', 'PAST', 1, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13960', 'PAST-5021', 'Ministry Integration 2', 'This course deepens vocational formation through biblical and theological reflection and ministerial ethics. It prepares students for supervised placements and equips them to evidence emerging ministerial capabilities through reflective practice and a structured portfolio. Prerequisite: PAST 5011.', 'PAST', 1, 0, 5, '[{"codes":["PAST-5011"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13961', 'LEDR-5123', 'Ministry Across Difference', 'Ministry Across Difference equips students to serve faithfully amidst the richness of cultural, generational, and socio-economic diversity in church and community settings. Students will analyze how power dynamics and various assumptions can shape ministry practice that fosters and celebrates the diversity of the community. The course emphasizes intercultural and intergenerational competence, cultural humility, and respect for diverse ways of knowing and being. Attention is given to adapting one''s ministry style to match team needs, cultural contexts, and emerging ministry scenarios. Prerequisite: LEDR 5113.', 'LEDR', 3, 0, 5, '[{"codes":["LEDR-5113"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13962', 'PAST-6013', 'Organizational Leadershipadmin', 'This course prepares students for the practical administrative responsibilities of congregational leadership. The course introduces core practices for stewarding church assets. Students learn how congregations govern themselves by examining the purpose and use of governing documents in relation to legal, ethical, and denominational responsibilities. Through case studies, students develop collaborative habits for working on ministry teams, including communication, role clarity, and duty-of-care expectations that support safe-church practice including in the digital sphere. Students also gain competence in reading and preparing basic budgets and financial reports for responsible decision-making and planning.', 'PAST', 3, 0, 6, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13963', 'PAST-701A', 'Mentored Ministry 1', 'Mentored Ministry provides supervised ministry experience in an approved setting, totaling at least 100 hours of practice. Students participate in the day-to-day work of ministry, develop their ministerial capabilities, and receive guidance and feedback through placement supervision and feedback. Structured reflection in a ministry portfolio is a core component, helping students integrate theological learning with ministry practice and growth in vocation, self-awareness, and professional habits for sustainable leadership. Prerequisite PAST 5021.', 'PAST', 2.5, 0, 7, '[{"codes":["PAST-5021"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13964', 'PAST-702A', 'Mentored Ministry 2', 'Mentored Ministry provides supervised ministry experience in an approved setting, totaling at least 100 hours of practice. Students participate in the day-to-day work of ministry, develop their ministerial capabilities, and receive guidance and feedback through placement supervision and feedback. Structured reflection in a ministry portfolio is a core component, helping students integrate theological learning with ministry practice and growth in vocation, self-awareness, and professional habits for sustainable leadership. Prerequisite or corequisite: PAST 701a', 'PAST', 2.5, 0, 7, '[{"codes":["PAST-701a"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13965', 'PAST-703A', 'Mentored Ministry 3', 'Mentored Ministry provides supervised ministry experience in an approved setting, totaling at least 100 hours of practice. Students participate in the day-to-day work of ministry, develop their ministerial capabilities, and receive guidance and feedback through placement supervision and feedback. Structured reflection in a ministry portfolio is a core component, helping students integrate theological learning with ministry practice and growth in vocation, self-awareness, and professional habits for sustainable leadership. Prerequisite or corequisite: PAST 702a', 'PAST', 2.5, 0, 7, '[{"codes":["PAST-702a"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13966', 'PAST-704A', 'Mentored Ministry 4', 'Mentored Ministry provides supervised ministry experience in an approved setting, totaling at least 100 hours of practice. Students participate in the day-to-day work of ministry, develop their ministerial capabilities, and receive guidance and feedback through placement supervision and feedback. Structured reflection in a ministry portfolio is a core component, helping students integrate theological learning with ministry practice and growth in vocation, self-awareness, and professional habits for sustainable leadership. Prerequisite or corequisite: PAST 703a', 'PAST', 2.5, 0, 7, '[{"codes":["PAST-703a"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13967', 'LEDR-6013', 'Theo-Futures for Ministry Inno', 'Theo-Futures for Ministry Innovation primes Christian leaders with the theological orientation, interpretive discipline, relational attentiveness, and adaptive capacities required to lead faithfully amid cultural, technological, and ecclesial change. The course forms leaders in futures-oriented theological imagination, disciplined sensemaking, empathetic engagement with diverse perspectives on the future, and readiness for faithful innovation in ministry.', 'LEDR', 3, 0, 6, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13968', 'PAST-3011', 'Ministry Integration 1', 'This course introduces students to the nature and responsibilities of pastoral ministry and discernment of personal calling in dialogue with ecclesial affirmation and the Spirit''s leading. It also introduces them to the formative ministry portfolio.', 'PAST', 1, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13969', 'PAST-3021', 'Ministry Integration 2', 'This course deepens vocational formation through biblical and theological reflection and ministerial ethics. It prepares students for supervised placements and equips them to evidence emerging ministerial capabilities through reflective practice and a structured portfolio. Prerequisite: PAST 3011.', 'PAST', 1, 0, 3, '[{"codes":["PAST-3011"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13970', 'PAST-401A', 'Mentored Ministry 1', 'Mentored Ministry provides supervised ministry experience in an approved setting, totaling at least 100 hours of practice. Students participate in the day-to-day work of ministry, develop their ministerial capabilities, and receive guidance and feedback through placement supervision and feedback. Structured reflection in a ministry portfolio is a core component, helping students integrate theological learning with ministry practice and growth in vocation, self-awareness, and professional habits for sustainable leadership. Prerequisite PAST 3021.', 'PAST', 2.5, 0, 4, '[{"codes":["PAST-3021"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13971', 'PAST-402A', 'Mentored Ministry 2', 'Mentored Ministry provides supervised ministry experience in an approved setting, totaling at least 100 hours of practice. Students participate in the day-to-day work of ministry, develop their ministerial capabilities, and receive guidance and feedback through placement supervision and feedback. Structured reflection in a ministry portfolio is a core component, helping students integrate theological learning with ministry practice and growth in vocation, self-awareness, and professional habits for sustainable leadership. Prerequisite or corequisite: PAST 401a', 'PAST', 2.5, 0, 4, '[{"codes":["PAST-401a"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13972', 'PAST-403A', 'Mentored Ministry 3', 'Mentored Ministry provides supervised ministry experience in an approved setting, totaling at least 100 hours of practice. Students participate in the day-to-day work of ministry, develop their ministerial capabilities, and receive guidance and feedback through placement supervision and feedback. Structured reflection in a ministry portfolio is a core component, helping students integrate theological learning with ministry practice and growth in vocation, self-awareness, and professional habits for sustainable leadership. Prerequisite or corequisite: PAST 402a', 'PAST', 2.5, 0, 4, '[{"codes":["PAST-402a"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13973', 'PAST-404A', 'Mentored Ministry 4', 'Mentored Ministry provides supervised ministry experience in an approved setting, totaling at least 100 hours of practice. Students participate in the day-to-day work of ministry, develop their ministerial capabilities, and receive guidance and feedback through placement supervision and feedback. Structured reflection in a ministry portfolio is a core component, helping students integrate theological learning with ministry practice and growth in vocation, self-awareness, and professional habits for sustainable leadership. Prerequisite or corequisite: PAST 403a', 'PAST', 2.5, 0, 4, '[{"codes":["PAST-403a"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13974', 'LEDR-501A', 'Leadership Labs 1', 'Digital Literacies is a hands-on lab for discerning and using digital spaces in ministry. Students evaluate platforms and hybrid practices for communication, worship support, pastoral care, and formation, attending to opportunities and risks. The course cultivates theological judgment and ethics for emerging technologies (including AI) through discussion, guided exercises, feedback, and revision. A component of this course is Formation in Groups gatherings through the semester. This course is considered a full year course, and credit can only be obtained if students take both sections in the same academic year. Prerequisite: PAST 5021.', 'LEDR', 0.5, 0, 5, '[{"codes":["PAST-5021"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13975', 'LEDR-501B', 'Leadership Labs 1', 'Digital Literacies is a hands-on lab for discerning and using digital spaces in ministry. Students evaluate platforms and hybrid practices for communication, worship support, pastoral care, and formation, attending to opportunities and risks. The course cultivates theological judgment and ethics for emerging technologies (including AI) through discussion, guided exercises, feedback, and revision. A component of this course is Formation in Groups gatherings through the semester. This course is considered a full year course, and credit can only be obtained if students take both sections in the same academic year. Prerequisite: PAST 5021.', 'LEDR', 0.5, 0, 5, '[{"codes":["PAST-5021"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13976', 'LEDR-502A', 'Leadership Labs 2', 'Adaptive Leadership is a practice-focused lab for leading through changing times. Students learn to name adaptive challenges, test small responses, and adjust leadership approaches through feedback-informed cycles. Attention is given to courageous, hope-shaped leadership and to cultivating innovation as an ongoing discipline so students can guide communities through real transitions. A component of this course is Formation in Groups gatherings through the semester. This course is considered a full year course, and credit can only be obtained if students take both sections in the same academic year. Prerequisite: PAST 5021.', 'LEDR', 0.5, 0, 5, '[{"codes":["PAST-5021"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13977', 'LEDR-502B', 'Leadership Labs 2', 'Adaptive Leadership is a practice-focused lab for leading through changing times. Students learn to name adaptive challenges, test small responses, and adjust leadership approaches through feedback-informed cycles. Attention is given to courageous, hope-shaped leadership and to cultivating innovation as an ongoing discipline so students can guide communities through real transitions. A component of this course is Formation in Groups gatherings through the semester. This course is considered a full year course, and credit can only be obtained if students take both sections in the same academic year. Prerequisite: PAST 5021.', 'LEDR', 0.5, 0, 5, '[{"codes":["PAST-5021"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('13978', 'HIST-2843', 'Ancient Rome: Culture/Society', 'An introduction to the central aspects of the experience of living in ancient Rome with an emphasis on the first century BCE to the second century CE. Topics include class and status, slavery, gender and sexuality, religion, health, public entertainment, and the reception of ancient Rome in our modern world. Antirequisite(s): Credit can be obtained for only one of HIST 2843 or CLAS 2843.', 'HIST', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6613', 'APSC-1070L', 'APSC 1073 Laboratory', '', 'APSC', 0, 1, 1, '[{"codes":["APSC-1073"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6614', 'APSC-1073', 'Introduction to Engineering', 'This course provides students with basic engineering skills and knowledge that will be used through their professional life. The primary topic is technical communications (report writing, referencing sources, unit analyses, data acquisition & interpretation, effective presentations). The history and disciplines of engineering, code of ethics, and engineers'' responsibility for safety in the workplace and environmental awareness are also covered. (1h tutorial).', 'APSC', 3, 0, 1, '[{"codes":["APSC-1070L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6615', 'APSC-1110L', 'APSC 1113 Laboratory', '', 'APSC', 0, 1, 1, '[{"codes":["APSC-1113"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6616', 'APSC-1113', 'Statics', 'This is a first course in engineering mechanics, focusing on the analysis of various simple static structures. Topics include force and position vectors, dot and cross products, directed force vectors, equivalent force and moment systems, particle and rigid body equilibrium, two and three force elements, trusses, frames, machines, friction, centroids and moments of inertia. Students complete a major design project for part of their grade. (3h lab). Prerequisite(s) or Corequisite(s): MATH 1013, PHYS 1013.', 'APSC', 3, 0, 1, '[{"codes":["MATH-1013","and","PHYS-1013",""],"textExtension":"- Must be taken either prior to or at the same time as this course."},{"codes":["APSC-1110L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6622', 'APSC-1220L', 'APSC 1223 Tutorial', '', 'APSC', 0, 1, 1, '[{"codes":["APSC-1223"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6623', 'APSC-1223', 'Design 1 (CAD)', 'An introduction to the engineering design process focusing on the role of graphics in design. Students are instructed in the use of modern CAD software for the production of mechanical drawings and learn standards for same. Free hand sketching, 3-D visualization techniques and report writing are also covered. Students complete a major design project and submit a set of drawings with a written report to obtain a significant portion of their grade. (3h lab).', 'APSC', 3, 0, 1, '[{"codes":["APSC-1220L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6624', 'APSC-1410L', 'APSC 1413 Tutorial', '', 'APSC', 0, 1, 1, '[{"codes":["APSC-1413"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6625', 'APSC-1413', 'Comp Programming for APSC 1', 'This course covers the fundamental programming principles of flow control, modularity and structured programming. The student will implement significant programs in the "C" programming language to solve a variety of engineering problems. (3h lab).  Prerequisite(s) or Corequisite(s): MATH 1013.', 'APSC', 3, 0, 1, '[{"codes":["MATH-1013"],"textExtension":"- Must be taken either prior to or at the same time as this course."},{"codes":["APSC-1410L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6632', 'APSC-2110L', 'APSC 2113 Laboratory', '', 'APSC', 0, 1, 2, '[{"codes":["APSC-2113"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6633', 'APSC-2113', 'Thermo-Fluids I', 'This course introduces the sciences of Thermodynamics and Fluid Mechanics in an integrated manner. It covers the basic properties of fluids and gasses, the ideal gas equation of state, simple compressible substances, fluid statics, work and heat interactions, the first and second laws of thermodynamics, enthalphy, entropy and specific heat, steady and unsteady flow, Carnot, Rankine and refrigeration cycles. (3h lab). Prerequisite(s): APSC 1113, MATH 1023.', 'APSC', 3, 0, 2, '[{"codes":["APSC-1113","MATH-1023"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["APSC-2110L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6634', 'APSC-2120L', 'APSC 2123 Laboratory', '', 'APSC', 0, 1, 2, '[{"codes":["APSC-2123"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6635', 'APSC-2123', 'Thermo-Fluids 2', 'Fluid flow definitions and material properties. Fluid statics, forces on submerged surfaces, buoyancy and stability. Continuity, Euler, energy and momentum equations with engineering applications. Dimensional analysis, similitude, theory of physical models. Reynolds number, laminar vs turbulent flows, friction factor and simple piping systems. Lift and drag of submerged objects. (3h lab). Prerequisite(s): APSC 2113.', 'APSC', 3, 0, 2, '[{"codes":["APSC-2113"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["APSC-2120L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6636', 'APSC-2130L', 'ASPC 2133 Laboratory', '', 'APSC', 0, 1, 2, '[{"codes":["APSC-2133","-","Must","be","taken","at","the","same","time","as","this","course"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6637', 'APSC-2133', 'Strength of Materials', 'Elastic deformation and failure analysis for common engineering elements. Material properties, stress strain testing and diagrams. Axial, torsion, transverse and bending loads. Stress transformations and principal stresses. Statically indeterminate problems. Design of struts, pins, shafts, pressure vessels, beams and columns. (3h lab). Prerequisite(s): APSC 1113, MATH 1023. Antirequisite(s): Credit can be obtained for only one of APSC 2133 or APSC 1133.', 'APSC', 3, 0, 2, '[{"codes":["APSC-1113","MATH-1023"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["APSC-2130L","-","Must","be","taken","at","the","same","time","as","this","course"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6638', 'APSC-2210L', 'APSC 2213 Laboratory', '', 'APSC', 0, 1, 2, '[{"codes":["APSC-2213"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6639', 'APSC-2213', 'Electric Circuits 1', 'Introductory circuit analysis. Kirchoff''s laws, node and mesh analysis, terminal behaviour and circuit equivalence including Thévenin and Norton circuits. Controlled sources and energy storage elements, steady state and transient response of first order networks. Steady state AC power, phasor diagrams, power and power factor are introduced. (3h lab). Prerequisite(s): MATH 1023.', 'APSC', 3, 0, 2, '[{"codes":["MATH-1023"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["APSC-2210L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6640', 'APSC-2220L', 'APSC 2223 Laboratory', '', 'APSC', 0, 1, 2, '[{"codes":["APSC-2223"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6641', 'APSC-2223', 'Digital Systems', 'Digital logic, digital systems, machine level representation of data, principles of assembly level machine organization, principles of CPU design. Cross-coded as Comp 2203. (1.5h lab).', 'APSC', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6642', 'APSC-2323', 'Surveying', 'Chain, level, transit, EDM; Differential, contour, profile, vertical curves, grade stakes, slope stakes; triangulations, traversing, horizontal curves, coordinates; areas and volumes. Two weeks of field work required. Prerequisite(s): Permission of School of Engineering.', 'APSC', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6643', 'APSC-2410L', 'APSC 2413 Tutorial', '', 'APSC', 0, 1, 2, '[{"codes":["APSC-2413"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6644', 'APSC-2413', 'Engineering Economics', 'Topics of theoretical and applied economics of interest and use to engineers and professionals in related fields. Topics include market equilibria, interest rate determination, present and future values, investment criteria, budgeting and replacement analysis, depreciation, taxation, inflation, sensitivity and risk analysis, and multi-staged and multi-attribute decision making. (3h lab). Prerequisite(s): MATH 1023.', 'APSC', 3, 0, 2, '[{"codes":["MATH-1023"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["APSC-2410L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6646', 'APSC-2520L', 'APSC 2523 Laboratory', '', 'APSC', 0, 1, 2, '[{"codes":["APSC-2523"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6647', 'APSC-2523', 'Electric Circuits 2', 'Advanced circuit analysis dealing primarily with AC systems. The concepts of sinusoidal excitation, phasors and complex impedance are fully developed. Mutual inductance and magnetically coupled coils are used to describe transformer behaviour and performance. Power calculations for single and balanced three phase systems are covered, introducing the concepts of real and reactive power. Unbalanced networks, grounding and harmonics are also examined. (3h lab). Prerequisite(s): APSC 2213.', 'APSC', 3, 0, 2, '[{"codes":["APSC-2213"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["APSC-2520L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6648', 'APSC-2610L', 'APSC 2613 Laboratory', '', 'APSC', 0, 1, 2, '[{"codes":["APSC-2613"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6649', 'APSC-2613', 'Comp Programming for APSC 2', 'Computer programming in the C++ language. Topics discussed include object oriented versus procedural programming, objects, stacks, queues, linked lists, trees, various sorting and searching algorithms. Students may apply the theory to develop programs for hardware control, graphics or the numerical solution of various engineering problems. (3h lab). Prerequisite(s): APSC 1413.', 'APSC', 3, 0, 2, '[{"codes":["APSC-1413"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["APSC-2610L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6651', 'APSC-2680L', 'APSC 2683 Tutorial', '', 'APSC', 0, 1, 2, '[{"codes":["APSC-2683"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6652', 'APSC-2683', 'Design 2', 'This course provides a project-based exercise in the engineering design process. Students work in teams and as individuals on defined projects which utilize knowledge gained from their previous engineering courses. The projects encompass conceptual design, detailed analysis, engineering drawings, physical model fabrication, experimentation, testing and report writing. (3h lab). Prerequisite(s): APSC 1223', 'APSC', 3, 0, 2, '[{"codes":["APSC-1223"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["APSC-2680L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6653', 'APSC-2710L', 'APSC 2713 Laboratory', '', 'APSC', 0, 1, 2, '[{"codes":["APSC-2713"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6654', 'APSC-2713', 'Dynamics', 'The kinematics and kinetics of particles and rigid bodies. Rectangular, tangential/normal and cylindrical coordinates in translating reference frames. Application of Newton''s laws, energy method, and impulse and momentum method. Simple mechanisms with emphasis on linkages. (3h lab). Prerequisite(s): APSC 1113, MATH 1023.', 'APSC', 3, 0, 2, '[{"codes":["APSC-1113","MATH-1023"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["APSC-2710L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6658', 'APSC-2810L', 'APSC 2813 Laboratory', '', 'APSC', 0, 1, 2, '[{"codes":["APSC-2813"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6659', 'APSC-2813', 'Engineering and the Biosphere', 'The course explores the effect of engineered systems and structures on the biosphere. Topics include cell structure and function, microbiology and toxicology, nutrient cycles, communities and ecology as these relate to engineering projects. The application of technology and design to minimize the impact of human activities on living systems is also considered. Laboratory sessions will consist of field-trips to local sites. NOTE: APSC 2813 is not considered an equivalent to any course offered through the Biology department. (3h lab). Prerequisite(s): CHEM 1023 or permission of the instructor.', 'APSC', 3, 0, 2, '[{"codes":["CHEM-1023"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["APSC-2810L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6661', 'APSC-2920L', 'APSC 2923 Laboratory', '', 'APSC', 0, 1, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6662', 'APSC-2923', 'Intro to Industrial Eng', 'This course introduces operations research models. The focus is on formulating, building and solving optimization models, primarily using Microsoft Excel. Topics to be covered include linear programming, assignment models, transportation and network models, project management, decision analysis and risk, queueing models, nonlinear optimization and case studies from other engineering disciplines. Prerequisite(s): MATH 1023; APSC 1413 or COMP 1113.', 'APSC', 3, 0, 2, '[{"codes":["#","MATH-1023","#","APSC-1413","or","COMP-1113"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6663', 'APSC-3210L', 'APSC 3213 Laboratory', '', 'APSC', 0, 1, 3, '[{"codes":["APSC-3213"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6664', 'APSC-3213', 'Industrial Chemistry', 'An introduction to selected chemical industries, with particular emphasis on the Canadian scene. Examination of basic chemical industries and the relationship between chemistry of the process, engineering design, and equipment requirement is performed. (1h lab). Prerequisite(s): MATH 1023 and CHEM 1023.', 'APSC', 3, 0, 3, '[{"codes":["MATH-1023","CHEM-1023"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["APSC-3210L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6665', 'APSC-3310L', 'APSC 3313 Laboratory', '', 'APSC', 0, 1, 3, '[{"codes":["APSC-3313"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6666', 'APSC-3313', 'Fundamentals of Process Eng', 'This course seeks to develop the student''s ability to perform mass and energy balances on reactive and non-reactive processes. Topics include the fundamental properties of multiphase systems, phase equilibrium, vapour pressure, phase rule, Roault''s and Henry''s laws and colligative properties. Emphasis is placed on developing problem solving skills. (3h lab). Prerequisite(s): CHEM 1023 or CHEM 1123, MATH 1023.', 'APSC', 3, 0, 3, '[{"codes":["#","MATH-1023","#","CHEM-1023","or","CHEM-1123"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["APSC-3310L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6667', 'APSC-3410L', 'APSC 3413 Laboratory', '', 'APSC', 0, 1, 3, '[{"codes":["APSC-3413"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6668', 'APSC-3413', 'Intro Environmental Eng', 'Overview of environmental engineering terms and definitions. Air and water quality, impact of domestic, agricultural and industrial operations on the environment. Review of pertinent legislation, measurement techniques and common control methods. Construction practices and their effects on the environment. (3h lab). Prerequisite(s): CHEM 1023, MATH 1023.', 'APSC', 3, 0, 3, '[{"codes":["MATH-1023","CHEM-1023"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["APSC-3410L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6671', 'APSC-3683', 'Special Topics Project', 'Guided study/project work in a particular area of applied science, carried out under the direction of a faculty member in the School of Engineering. Such work may involve the design, development, implementation and documentation of a significant engineering device or research to better understand an engineering problem. A written report must be submitted and/or a public presentation made upon completion of the work to receive a grade. Prerequisite(s): Third-year standing and permission of the School of Engineering.', 'APSC', 3, 0, 3, '[{"codes":["3rd-year","standing","(55h","or","more","completed)"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6672', 'ARAM-7013', 'Biblical Aramaic', 'This course will introduce students to the grammar, syntax, and vocabulary of the Aramaic of the Old Testament. Building off the basics of Hebrew grammar, students will learn the basic grammar and vocabulary of Biblical Aramaic. As part of this course, students will translate portions of the Aramaic sections of Daniel and Ezra. Prerequisite: HEBR 5023', 'ARAM', 3, 0, 7, '[{"codes":["HEBR-5023"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6673', 'ARAM-7913', 'Directed Study in Aramaic 1', 'Advanced independent study of Aramaic texts or grammar under the supervision of a professor.', 'ARAM', 3, 0, 7, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6674', 'ARAM-7923', 'Directed Study in Aramaic 2', 'Advanced independent study of Aramaic texts or grammar under the supervision of a professor.', 'ARAM', 3, 0, 7, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6675', 'ARAM-7933', 'Directed Study in Aramaic 3', 'Advanced independent study of Aramaic texts or grammar under the supervision of a professor.', 'ARAM', 3, 0, 7, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6676', 'ARAM-7943', 'Directed Study in Aramaic 4', 'Advanced independent study of Aramaic texts or grammar under the supervision of a professor.', 'ARAM', 3, 0, 7, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6677', 'ARAM-7953', 'Directed Study in Aramaic 5', 'Advanced independent study of Aramaic texts or grammar under the supervision of a professor.', 'ARAM', 3, 0, 7, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6678', 'ARAM-7963', 'Directed Study in Aramaic 6', 'Advanced independent study of Aramaic texts or grammar under the supervision of a professor.', 'ARAM', 3, 0, 7, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6681', 'ART-1813', 'Hist of Art: Prehistory-1400', 'Art from prehistoric times to Giotto is considered in relation to its cultural and historical context. Cross-coded as HIST 1813. Antirequisite(s): Credit can be obtained for only one of ART 1813 or HIST 1813.', 'ART', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6682', 'ART-1823', 'Hist of Art: 1400 to Present', 'Art from the time of Giotto to the present is considered in relation to its cultural and historical context. Antirequisite(s): Credit can be obtained for only one of ART 1823 or HIST 1823.', 'ART', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6685', 'ART-2013', 'Drawing 1', 'Studio art course for beginners and those with more advanced technical skills. Students maintain a sketchbook and learn techniques like contour, value studies, textural inquiry and perspective. Realism and abstraction are explored. Limited to 14 students.', 'ART', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6687', 'ART-2023', 'Drawing 2', 'This course develops concepts and skills introduced in ART 2013, although ART 2013 is not a prerequisite. Students will learn more complex and imaginative drawing techniques working in realism and abstraction. Emphasis is on collaboration and creativity in a positive studio art environment. Limited to 16   participants', 'ART', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6688', 'ART-2033', 'Digital Imaging 1', 'An introduction to the computer as an art-making tool. Students will learn to create, develop, manipulate and enhance digital images with several applications using their laptop computer as a mobile studio.', 'ART', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6689', 'ART-2043', 'Digital Imaging 2', 'The ethics, aesthetics, and theory of digital image making will be addressed. Through assignments and experimentation, the student will create, acquire, manipulate and output of digital images with several applications using the laptop computer as a mobile studio. Prerequisite(s): ART 2033.', 'ART', 3, 0, 2, '[{"codes":["ART-2033"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6690', 'ART-2053', 'Art and the Environment 1', 'This course addresses environmental issues through art, with a focus on the landscape model. It provides students with both "hands on" and academic assistance to allow them to undertake visual studies of local urban and rural landscapes, with the possibility of wilderness study. This course utilizes representational drawing and painting, working with drawing materials with an introduction to watercolour.', 'ART', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6691', 'ART-2063', 'Art and the Environment 2', 'This course addresses environmental issues through art, with a focus on the landscape model. It allows students to undertake visual studies of local landscapes. Students will develop their own imagery employing both realism and abstraction of their work. This course explores the production of images using acrylic on both paper and canvas surfaces.', 'ART', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6692', 'ART-2073', 'Contemporary Art', 'An examination of western art from 1945 to the present. Topics include the development of abstract expressionism, minimalism and post-minimalism, conceptualism, and pluralism in both two-dimensional and three-dimensional media.', 'ART', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6693', 'ART-2083', 'Canadian Art 1', 'The history of the visual arts in Canada from the sixteenth century to the early twentieth century with special emphasis on painting and sculpture.', 'ART', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6694', 'ART-2093', 'Canadian Art 2', 'The history of the visual arts in Canada from the early twentieth century to the present with special emphasis on painting and sculpture.', 'ART', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6701', 'ART-2313', 'American Art', 'Major developments in American art from the colonial period to the present. Major emphasis will be placed on specific artistic groups, major artists, pivotal artistic events, and themes specific to American culture.', 'ART', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6703', 'ART-2413', 'Art of the Nineteenth Century', 'Major developments in European art from the time of the French Revolution to the end of the century. Emphasis is placed on movements such as neo-classicism, romanticism, impressionism, and post-impressionism.', 'ART', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6704', 'ART-2423', 'Art of the 20th C. 1900-1945', 'Major developments in western art from 1900-1945. Major movements such as expressionism, cubism, Surrealism, and Dadaism will be emphasized.', 'ART', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6706', 'ART-2623', 'Art 17th & 18th C.', 'Selected work from these centuries is studied in relationship to its cultural, political, and economic context. Emphasis will be placed on such major figures as Rembrandt, Velazquez, Caravaggio, Watteau, and others.', 'ART', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6707', 'ART-2813', 'Art of the Indian Subcontinent', 'A general survey of the architecture, sculpture, and painting with particular emphasis on the development of the Hindu temple and of the Buddha image.', 'ART', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6712', 'ART-3013', 'Painting: Wtrcolour, Pen, Ink', 'A studio art course in which students will learn pen and ink, as well as complex watercolour techniques, and work to create realistic, multi-technical paintings on paper. Emphasis is on collaboration and creativity in a positive studio art environment. Limited to 14 students.', 'ART', 3, 0, 3, '[{"codes":["ART-2013","or","ART-2023","or","permission","of","instructor",""],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6714', 'ART-3023', 'Painting 2: Acrylic', 'Students will learn acrylic painting techniques, including colour mixing, scales, and brush work, and will   produce a professional-style large-format painting on gallery canvas suitable for exhibition. Realism and abstraction are explored. Emphasis is on collaboration and creativity in a positive studio art environment. Limited to 14 students.', 'ART', 3, 0, 3, '[{"codes":["ART","2013","or","ART","2023","or","permission","of","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6715', 'ART-3033', 'Art and Identity 1', 'In this course, art will be employed as both a tool and potentially a catalyst in our search for the meaning of identity. This will be accomplished through a visual exploration of memory on a personal and cultural level. Prerequisite(s): ART 2013 or permission of the instructor.', 'ART', 3, 0, 3, '[{"codes":["ART-2013"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6716', 'ART-3043', 'Art and Identity 2', 'In this course, art will be employed as both a tool and potentially a catalyst in our search for the meaning of identity. This will be accomplished through a visual exploration of memory on a personal and cultural level. Prerequisite(s): ART 2013 or permission of the instructor.', 'ART', 3, 0, 3, '[{"codes":["ART-2013"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6724', 'ART-3313', 'Special Topics in Hist of Art', 'This course examines selected topics in the history of western and non-western art not included in the established curriculum. May be repeated for credit with change of topic.', 'ART', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6725', 'ART-3323', 'Art Critcl Theo & Methds', 'A study of various scholarly approaches to the history of art, as well as theories which inform these approaches. Prerequisite(s): 6h ART and permission of the Department.', 'ART', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6728', 'ART-3513', 'Woman and Art', 'An examination of women in art, as subjects and as artists, from the middle ages to the present. Emphasis is placed on their contribution to the history of western art as producers of major paintings, sculptures, and craft objects.', 'ART', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6730', 'ART-3613', 'Art Ind. Study Studio 1', 'Individual study of problems in studio art, for highly motivated students, developed with and directed by a supervising professor. Prerequisite(s): Permission of the Department.', 'ART', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6731', 'ART-3623', 'Art Ind. Study Studio 2', 'Individual study of problems in studio art, for highly motivated students, developed with and directed by a supervising professor. Prerequisite(s): Permission of the Department.', 'ART', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6732', 'ART-3713', 'Art Directed Readings 1', 'This course consists of supervised readings and research projects in a specific area of the history of art to be chosen in consultation with a faculty member to culminate in the preparation of a major research paper using technical and critical literature in the history of art. Prerequisite(s): 12h ART (history) and permission of the instructor.', 'ART', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6733', 'ART-3723', 'Art Directed Readings 2', 'This course consists of supervised readings and research projects in a specific area of the history of art to be chosen in consultation with a faculty member to culminate in the preparation of a major research paper using technical and critical literature in the history of art. Prerequisite(s): 12h ART (history) and permission of the instructor.', 'ART', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6741', 'BIBL-3063', 'Interpreting the Bible', 'This course on how to interpret the Christian Scriptures examines and integrates practical and theoretical perspectives on the Biblical writings. Students will learn how to read, interpret, and apply the Bible. Among the various subjects discussed are: Bible translations, text and context, literary genres, and the influence of our own cultural context on interpretation.', 'BIBL', 3, 0, 3, '[{"codes":["BIBL-2053"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6742', 'BIBL-2023', 'Survey of the Bible', 'This course lays the foundation for advanced study of the Bible by helping students acquire knowledge of the basic contents and narrative of the Bible.', 'BIBL', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6743', 'BIBL-3013', 'Intro to the Old Testament 1', 'An examination of Genesis through Nehemiah. This course will survey these texts within the historical, political, and religious contexts of the Ancient Near East, and will introduce the student to the academic, literary, and theological study of this section of the Bible.', 'BIBL', 3, 0, 3, '[{"codes":["BIBL-2053"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6744', 'BIBL-3023', 'Intro to the Old Testament 2', 'An examination of Esther through Malachi. This course will survey these texts within the historical, political, and religious contexts of the Ancient Near East, and will introduce the student to the academic, literary, and theological study of this section of the Bible. Prerequisite(s): BIBL-2053; BIBL-3013 recommended.', 'BIBL', 3, 0, 3, '[{"codes":["BIBL-2053"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6745', 'BIBL-3033', 'Intro to the New Testament 1', 'An examination of the New Testament gospels. This course will survey these texts within their 1st century historical, political, and religious contexts, and will introduce the student to the academic, literary, and theological study of this section of the Bible.', 'BIBL', 3, 0, 3, '[{"codes":["BIBL-2053"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6746', 'BIBL-3043', 'Intro to the New Testament 2', 'An examination of Acts to Revelation. This course will survey these texts within their Greco-Roman contexts, and will introduce the student to the academic, literary, and theological study of these sections of the Bible. Prerequisite(s): BIBL 2053; BIBL 3033 recommended.', 'BIBL', 3, 0, 3, '[{"codes":["BIBL-3033"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6747', 'BIBL-3053', 'Israel Study Tour', 'A study tour in Israel and the Palestinian Territories (and surrounding areas as possible) designed to introduce the geography of the land and to shed light on events of the Old and New Testaments and the intertestamental period. Some consideration will also be given to the role that Christians and the Church have played in the land in ancient and modern times.', 'BIBL', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6748', 'BIBL-3143', 'Death,Burial&Resurrec Jesus', 'The death, burial and resurrection of Jesus is central to historic Christian belief. This course will consider how the historicity of these events can be established confidently, despite criticisms and objections. Through a close reading of the evidence in the four Gospels and other portions of the New Testament, and examination of other historical and archeological evidence, the historicity of these events will be explored.', 'BIBL', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6750', 'BIBL-5013', 'Survey of the Bible', 'This course lays the foundation for advanced study of the Bible by helping students acquire knowledge of the basic contents and narrative of the Bible. This course is required of students who have not passed the Bible Knowledge Entrance Test. Normally, this course is taken prior to, or concurrent with, BIBL 5023 or BIBL 5033.', 'BIBL', 3, 0, 5, '[{"codes":["BIBL-5023","or","BIBL-5033"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6751', 'BIBL-5023', 'Interpreting the Old Testament', 'The Old Testament contains most of the Christian Bible. This course will introduce the student to the different sections and genres of literature in the Old Testament, to interpretative methods appropriate to them, and to theological principles. The course will also survey aspects of the historical and cultural context of the Old Testament. This course assumes knowledge of the contents of the Old Testament, and is the foundation for advanced studies.', 'BIBL', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6752', 'BIBL-5033', 'Interpreting the New Testament', 'This course will introduce the student to the different sections and genres of literature in the New Testament, to interpretative methods appropriate to them, and to theological principles. The course will also survey the world of Jesus and the early Christian Church. This course assumes knowledge of the contents of the New Testament, and is the foundation for advanced studies.', 'BIBL', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6753', 'BIBL-5043', 'Death,Burial&Resurrec Jesus', 'The death, burial and resurrection of Jesus is central to historic Christian belief. This course will consider how the historicity of these events can be established confidently, despite criticisms and objections. Through a close reading of the evidence in the four Gospels and other portions of the New Testament, and examination of other historical and archeological evidence, the historicity of these events will be explored.', 'BIBL', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6754', 'BIBL-5503', 'Hebrew Scripture Foundations', 'A general introduction to the historical, sociological, and theological context in which the Hebrew Scriptures came into existence, this course will provide the student with an understanding of the major emphases of the texts. In addition, the student will be introduced to themes of community life and praxis in the Hebrew Scriptures that find parallels in historical Indigenous worldviews of creation and Creator. The course will use community understandings, models and paradigms as a basis for comparison. This course is normally taught by an Indigenous instructor. This course is normally available only to students enrolled in the MA-INCD program.', 'BIBL', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6755', 'BIBL-5513', 'New Testament Foundations', 'A general introduction to the historical, sociological, and theological context in which the New Testament Scriptures came into existence, this course will familiarize students with the content and structure, distinctive theology, and introductory matters of the New Testament. In addition, the student will be introduced to the nature of the early Christian community, its transitions and changes from a strictly Hebraic construct as found within the Jewish community, and projections made for its future development. This course is normally taught by an Indigenous instructor. This course is normally available only to students enrolled in the MA-INCD program.', 'BIBL', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6757', 'BIBL-6013', 'Genesis', 'In this course students will study the book of Genesis by applying the hermeneutical and exegetical skills learned in BIBL 5023. In addition to the contents, context, and interpretive issues, authorship, date of composition, theology, and narrative technique will also receive attention. This course will provide students with the foundation for preaching, teaching, and further research in Genesis and other Old Testament narrative. Prerequisite: BIBL 5023, and completion of, or simultaneous enrolment in, HEBR 5013.', 'BIBL', 3, 0, 6, '[{"codes":["BIBL-5023"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["HEBR-5013"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6758', 'BIBL-6023', 'Deuteronomistic History', 'In this course students will study selected texts from Joshua, Judges, 1 and 2 Samuel, and 1 and 2 Kings by applying the hermeneutical and exegetical skills learned in BIBL 5023. In addition to the contents, context, and interpretive issues, authorship, date of composition, theology, and narrative technique will also receive attention. This course will provide students with the foundation for preaching, teaching, and further research in these books and other Old Testament narrative. Prerequisite: BIBL 5023, and completion of, or simultaneous enrolment in, HEBR 5013.', 'BIBL', 3, 0, 6, '[{"codes":["BIBL-5023"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["HEBR-5013"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6759', 'BIBL-6033', '1 & 2 Chron & Ezra-Nehemiah', 'In this course students will study the books of 1 and 2 Chronicles and Ezra-Nehemiah by applying the hermeneutical and exegetical skills learned in BIBL 5023. In addition to the contents, context, and interpretive issues, authorship, date of composition, theology, and narrative technique will also receive attention. This course will provide students with the foundation for preaching, teaching, and further research in 1 and 2 Chronicles, Ezra-Nehemiah, and other Old Testament narrative. Prerequisite: BIBL 5023, and completion of, or simultaneous enrolment in, HEBR 5013.', 'BIBL', 3, 0, 6, '[{"codes":["BIBL-5023"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["HEBR-5013"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6760', 'BIBL-6043', 'Daniel', 'In this course students will study the book of Daniel by applying the hermeneutical and exegetical skills learned in BIBL 5023. In addition to the contents, context, and interpretive issues, authorship, date of composition, theology, and apocalyptic world-view will also receive attention. This course will provide students with the foundation for preaching, teaching, and further research in Daniel and other apocalyptic literature. Prerequisite: BIBL 5023, and completion of, or simultaneous enrolment in, HEBR 5013.', 'BIBL', 3, 0, 6, '[{"codes":["BIBL-5023"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["HEBR-5013"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6761', 'BIBL-6053', 'Amos and Isaiah', 'In this course students will study the books of Amos and Isaiah by applying the hermeneutical and exegetical skills learned in BIBL 5023. In addition to the contents, context, and interpretive issues, authorship, date of composition, theology, and social justice issues will also receive attention. This course will provide students with the foundation for preaching, teaching, and further research in Amos, Isaiah, and other prophetic literature. Prerequisite: BIBL 5023, and completion of, or simultaneous enrolment in, HEBR 5013.', 'BIBL', 3, 0, 6, '[{"codes":["BIBL-5023"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["HEBR-5013"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6762', 'BIBL-6063', 'Psalms', 'In this course students will study the book of Psalms by applying the hermeneutical and exegetical skills learned in BIBL 5023. In addition to the contents, context, and interpretive issues, authorship, date of composition, theology, and poetic technique will also be receive attention. This course will provide students with the foundation for preaching, teaching, and further research in Psalms and other poetic literature. Prerequisite: BIBL 5023, and completion of, or simultaneous enrolment in, HEBR 5013.', 'BIBL', 3, 0, 6, '[{"codes":["BIBL-5023"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["HEBR-5013"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6763', 'BIBL-6113', 'The Gospel of Matthew', 'In this course students will study Matthew''s gospel by applying the hermeneutical and exegetical skills learned in BIBL 5033. In addition to the contents, context, and interpretive issues, authorship, date of composition, theology, and Matthew''s portrait of Jesus will receive attention. This course will provide students with the foundation for preaching, teaching, and further research in Matthew and other gospels. Prerequisite: BIBL 5033, and completion of, or simultaneous enrolment in, GREE 5013.', 'BIBL', 3, 0, 6, '[{"codes":["BIBL-5033"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["GREE-5013"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6764', 'BIBL-6123', 'Luke-Acts', 'Luke-Acts is a two-part work that describes the life and ministry of Jesus and moves seamlessly to the life and ministry of the church, with the early church''s ministry modelled upon the ministry of Jesus. This course will examine the narrative and theological unity of Luke-Acts, focusing particularly on the mission of the early church. Prerequisite: BIBL 5033, and completion of, or simultaneous enrolment in, GREE 5013.', 'BIBL', 3, 0, 6, '[{"codes":["BIBL-5033"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["GREE-5013"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6765', 'BIBL-6133', 'The Gospel of John', 'In this course students will study the John''s gospel by applying the hermeneutical and exegetical skills learned in BIBL 5033. In addition to the contents, context, and interpretive issues, authorship, date of composition, theology, and John''s portrait of Jesus will receive attention. This course will provide students with the foundation for preaching, teaching, and further research in John and other gospels. Prerequisite: BIBL 5033, and completion of, or simultaneous enrolment in, GREE 5013.', 'BIBL', 3, 0, 6, '[{"codes":["BIBL-5033"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["GREE-5013"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6766', 'BIBL-6143', 'Romans and Galatians', 'In this course students will study the Epistles of Romans and Galatians by applying the hermeneutical and exegetical skills learned in BIBL 5033. In addition to studying the contents, contexts, and interpretive issues involved in the study of the apostle Paul''s major epistles to the churches in Galatia and in Rome, the epistles'' contribution to the Christian teaching regarding righteousness and justification before God will be emphasized. This course will provide students with the foundation for preaching, teaching, and further research in Romans, Galatians and other New Testament epistles. Prerequisite: BIBL 5033, and completion of, or simultaneous enrolment in, GREE 5013.', 'BIBL', 3, 0, 6, '[{"codes":["BIBL-5033"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["GREE-5013"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6767', 'BIBL-6153', 'Hebrews and James', 'In this course students will study the Epistle to the Hebrews and James by applying the hermeneutical and exegetical skills learned in BIBL 5033. In addition to studying the contents, contexts, and interpretive issues involved in the study of Hebrews and James, these letters'' contribution to the Christian understanding of Jesus Christ''s saving work will be emphasized. This course will provide students with the foundation for preaching, teaching, and further research in Hebrews and other New Testament epistles. Prerequisite: BIBL 5033, and completion of, or simultaneous enrolment in, GREE 5013.', 'BIBL', 3, 0, 6, '[{"codes":["BIBL-5033"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["GREE-5013"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6768', 'BIBL-6163', 'Philippians, Colos, Eph, Phil', 'In this course students will study Paul''s Prison Epistles by applying the hermeneutical and exegetical skills learned in BIBL 5033. In addition to studying the contents, contexts, and interpretive issues involved in the study these epistles, these letter''s contribution to Christology and a life of integrity in the face of adversity will be emphasized. This course will provide students with the foundation for preaching, teaching, and further research in the Prison Epistles and other New Testament epistles. Prerequisite: BIBL 5033, and completion of, or simultaneous enrolment in, GREE 5013.', 'BIBL', 3, 0, 6, '[{"codes":["BIBL-5033"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["GREE-5013"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6771', 'BIBL-6503', 'Community Models in Scripture', 'This course is a theological and exegetical exploration of how the Scriptures speak about community, how they present and promote particular values and praxis of community, and what examples of community appear in both testaments. This understanding is critical to a community development program focused through the lens of a biblically-informed worldview. Finally, the course will seek to enable understanding of the nature of community in the early church and its implications, if any, on our thinking about the holistic development of community within the Kingdom of God.', 'BIBL', 3, 0, 6, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6780', 'BIBL-7113', 'Dead Sea Scrolls', 'This course introduces students to the Dead Sea Scrolls and their contribution to our understanding of the world of Jesus and the early Church. The course surveys the Scrolls and related literature of the intertestamental and New Testament periods, including a survey of the history of these periods and the debate surrounding the origin of the Scrolls. The course engages in the study of a number of texts and themes that shed light on Jesus, the Gospels, and Paul. Prerequisite: BIBL 5023, 5033.', 'BIBL', 3, 0, 7, '[{"codes":["BIBL-5033"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6781', 'BIBL-7123', 'Life and Teaching of Jesus', 'This course offers an introduction to the life of Jesus, with emphasis on religious and historical context. Sources-canonical and noncanonical-will be critically assessed, criteria for determining authenticity will be reviewed, and the history of critical study of the life of Jesus will be surveyed. Prerequisite: BIBL 5033.', 'BIBL', 3, 0, 7, '[{"codes":["BIBL-5033"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6782', 'BIBL-7133', 'Israel Study Tour', 'A study tour in Israel and the Palestinian Territories (and surrounding areas as possible) designed to introduce the geography of the land and to shed light on events of the Old and New Testaments and the intertestamental period. Some consideration will also be given to the role that Christians and the Church have played in the land in ancient and modern times.', 'BIBL', 3, 0, 7, '[]');
