INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6835', 'BIOL-1113', 'Organisms & Their Enviro 1', 'An introduction to ecology, and to the foundations of genetics. (3h lab). Antirequisite(s): Credit can be obtained for only one of BIOL 1113/BIOL 1123 or BIOL 1813/BIOL 1823. Major credit cannot be obtained for BIOL 1113/BIOL 1123 and BIOL 1813/BIOL 1823 or BIOL 1853/BIOL 1863. However, students who have taken BIOL 1813/BIOL 1823 or BIOL 1853/BIOL 1863, and are subsequently transferring to the biology major may use either BIOL 1813/BIOL 1823 or BIOL 1853/BIOL 1863 as science electives.', 'BIOL', 3, 0, 1, '[{"codes":["BIOL-1110L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6836', 'BIOL-1120L', 'BIOL 1123 Laboratory', '', 'BIOL', 0, 1, 1, '[{"codes":["BIOL-1123"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6837', 'BIOL-1123', 'Organisms & Their Enviro 2', 'An introduction to molecular genetics and evolution. (3h lab). Prerequisite(s): BIOL 1113 with a minimum grade of C-. Antirequisite(s): Credit can be obtained for only one of BIOL 1113/BIOL 1123 or BIOL 1813/BIOL 1823. Major credit cannot be obtained for BIOL 1113/BIOL 1123 and BIOL 1813/BIOL 1823 or BIOL 1853/BIOL 1863. However, students who have taken BIOL 1813/BIOL 1823 or BIOL 1853/BIOL 1863, and are subsequently transferring to the biology major may use either BIOL 1813/BIOL 1823 or BIOL 1853/BIOL 1863 as science electives.', 'BIOL', 3, 0, 1, '[{"codes":["BIOL-1113","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["BIOL-1120L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6841', 'BIOL-1813', 'Human Biology 1', 'The fundamental principles of biology with an emphasis on humans. Topics include the foundations of the scientific method, cell cycle and reproduction, mechanisms of inheritance, body organization and systems with an emphasis on organ systems. This course is not recommended for biology majors. Antirequisite(s): Major credit can be obtained for only one of BIOL 1113/BIOL 1123 and BIOL 1813/BIOL 1823 or BIOL 1853/BIOL 1863. However, students who have taken BIOL 1813/BIOL 1823 or BIOL 1853/BIOL 1863 and are subsequently transferring to the biology major may use either BIOL 1813/BIOL 1823 or BIOL 1853/BIOL 1863 as science electives.', 'BIOL', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6843', 'BIOL-1823', 'Human Biology 2', 'The fundamental principles of biology with an emphasis on humans. Topics include reproduction, genetics and sexual orientation, behaviour, and evolution. This course is not recommended for biology majors. Prerequisite(s): BIOL 1813 with a minimum grade of C-. Antirequisite(s): Credit can be obtained for only one of BIOL 1813/1823 or BIOL 1853/1863.', 'BIOL', 3, 0, 1, '[{"codes":["BIOL-1813","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6844', 'BIOL-1850L', 'BIOL 1853 Laboratory', '', 'BIOL', 0, 1, 1, '[{"codes":["BIOL-1853"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6845', 'BIOL-1853', 'Applied Human Biology 1', 'An examination of the human body from an applied perspective. Topics include the foundations of the scientific method, cell cycle and reproduction, mechanisms of inheritance, body organization and systems with an emphasis on organ systems. This course is recommended for Kinesiology majors. (3h lab). Antirequisite(s): Credit can be obtained for only one of BIOL 1813/BIOL 1823 or BIOL 1853/BIOL 1863.', 'BIOL', 3, 0, 1, '[{"codes":["BIOL-1850L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6846', 'BIOL-1860L', 'BIOL 1863 Laboratory', '', 'BIOL', 0, 1, 1, '[{"codes":["BIOL-1863"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6847', 'BIOL-1863', 'Applied Human Biology 2', 'An examination of the human body from an applied perspective. Topics include reproduction, genetics and sexual orientation, behavior, and evolution. This course is recommended for Kinesiology majors. (3h lab). Prerequisite(s): BIOL 1853 or permission of instructor. Antirequisite(s): Credit can be obtained for only one of BIOL 1813/BIOL 1823 or BIOL 1853/BIOL 1863.', 'BIOL', 3, 0, 1, '[{"codes":["BIOL-1853","or","permission","of","instructor"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["BIOL-1860L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6849', 'BIOL-2010L', 'BIOL 2013 Laboratory', '', 'BIOL', 0, 1, 2, '[{"codes":["BIOL-2013"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6850', 'BIOL-2013', 'Cell and Molecular Biology', 'An introduction to the principles of cell biology with an emphasis on the organization of cells and the structure and function of cellular constituents. Topics include an overview of cell metabolism, cell communication/specialization and the cell cycle. (3h lab). Biology majors only.', 'BIOL', 3, 0, 2, '[{"codes":["BIOL-1113","and","BIOL-1123","or","BIOL-1813","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["BIOL-2010L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6855', 'BIOL-2040L', 'BIOL 2043 Laboratory', '', 'BIOL', 0, 1, 2, '[{"codes":["BIOL-2043"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6856', 'BIOL-2043', 'Biodiversity Plants & Algae', 'An introduction to the structure, function, evolution and diversity of plants and algae. (3h lab). Prerequisite(s): BIOL 1113/BIOL 1123 with a minimum grade of C-.', 'BIOL', 3, 0, 2, '[{"codes":["BIOL-1113","and","BIOL-1123","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["BIOL-2040L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6857', 'BIOL-2050L', 'BIOL 2053 Laboratory', '', 'BIOL', 0, 1, 2, '[{"codes":["BIOL-2053"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6858', 'BIOL-2053', 'Microbial Biodiversity', 'This course is an overview of the diversity of microorganisms on the planet, including Bacteria, Archaea, Protista, Fungi, and Viruses, and focuses on the unique and vital roles that these organisms play in their environment. (3h lab) This course is intended for Biology and Environmental Science majors.  Other majors may be able to take BIOL 2053, BIOL 2253, or BIOL 2453.  Antirequisite(s): Credit can be obtained for only one of BIOL 2053, BIOL 2253, or BIOL 2453.', 'BIOL', 3, 0, 2, '[{"codes":["BIOL-1113","and","BIOL-1123","with","minimum","grade","C-"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["BIOL-2050L"],"textExtension":"- Must be taken at the same time as this course."},{"codes":["CHEM-1013/CHEM-1023","or","CHEM-1113/CHEM-1123","with","a","minimum","grade","of","C-"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6859', 'BIOL-2070L', 'BIOL 2073 Laboratory', '', 'BIOL', 0, 1, 2, '[{"codes":["BIOL-2073"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6860', 'BIOL-2073', 'Animal Biodiversity', 'An introduction to the diversity, evolution, structure, and function of vertebrates, invertebrates, and non-photosynthetic protista. The main objective of this course is to introduce students to major groups and demonstrate the variety of relationships within, as well as between, these groups of organisms. (3h lab). Prerequisite(s): BIOL 1113/BIOL 1123 with a minimum grade of C-; BIOL 2073 may be taken concurrently with BIOL 1113/BIOL 1123 with permission of the Department.', 'BIOL', 3, 0, 2, '[{"codes":["BIOL-1113","and","BIOL-1123","with","minimum","Grade","C-","required","or","permission","of","the","Department"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["BIOL-2070L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6874', 'BIOL-2253', 'Health Science Microbiology', 'This course introduces the interactions of bacteria, archaea, protists, fungi, and viruses with the human environment, including the important roles of these microbes in production and spoilage of food and beverages, in benefitting human health, in causing human disease, and in shaping the human immune system. This course is recommended for NURS majors. It cannot be used for program credit by BIOL, ENVS, or NUTR majors.??  Antirequisite(s): Credit can be obtained for only one of BIOL 2253, BIOL 2053, or BIOL 2453.', 'BIOL', 3, 0, 2, '[{"codes":["BIOL-1113,","or","BIOL-1813,","or","BIOL-1853,","or","BIOL-2853,","with","minimum","grade","C-;","CHEM-1013","is","highly","recommended"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6891', 'BIOL-2553', 'Plants in the Modern World', 'The role played by plants in everyday life is investigated. Both historical and social developments caused by plants are explored. Current topics may include genetic manipulation of plant material, monoculture and deforestation.', 'BIOL', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6892', 'BIOL-2563', 'Marine Biology', 'An introduction to the oceans of the world and marine organisms, their importance to humans and how they are impacted by society. The diversity and ecology of phytoplankton, zooplankton, invertebrates, fish, mammals, birds, and seaweeds are explored as they relate to ocean processes such as tides, currents, pollution, fisheries, aquaculture, and climate change. Local focus on the Bay of Fundy. BIOL-2563-FA01 is for 1st/2nd year Biology majors only. BIOL-2563-FA02 is intended for other years and for other majors.', 'BIOL', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6896', 'BIOL-2663', 'Marine Biology', 'This course will teach you about the oceans of the world, what lives in them, how they function, how they are important to humans and our impact on them.', 'BIOL', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6900', 'BIOL-2813', 'Human Physiology & Anatomy 1', 'The basic anatomical and physiological principles of the human body. Major topics covered include: levels of organization, muscle-skeletal systems, neuroanatomy and physiology, and the integument. Prerequisite(s): BIOL 1113/BIOL 1123 or BIOL 1813 or BIOL 1853. The BIOL course(s) used as a prerequisite must be completed with a minimum grade of C-. Antirequisite(s): Credit can be obtained for only one of BIOL 2813 or KINE 2413.', 'BIOL', 3, 0, 2, '[{"codes":["BIOL-1113","and","BIOL-1123","or","BIOL-1813","or","BIOL-1853","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6902', 'BIOL-2823', 'Human Physiology & Anatomy 2', 'Major topics covered include the endocrine, cardiovascular, respiratory, urinary, digestive, and reproductive systems. Prerequisite(s): BIOL 2813 with a minimum grade of C-. Antirequisite(s): Major credit cannot be obtained for both BIOL 3173/BIOL 3183 and BIOL 2823, although BIOL 2823 can be used as a science elective. Credit can be obtained for only one of BIOL 2823 or KINE 2423.', 'BIOL', 3, 0, 2, '[{"codes":["BIOL-2813","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6905', 'BIOL-3013', 'Natural History & Field Bio', 'Hands on experience in any or all of terrestrial, fresh water, brackish water, intertidal, and marine-pelagic ecosystems. Relationships among the biota and the physical environment. Sampling design and techniques, data analysis. Field work, labs, lectures, discussions, projects. Presented at the Richardson Field Station in Biology, Bon Portage Island.', 'BIOL', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6907', 'BIOL-2030L', 'Biol 2033 Laboratory', '', 'BIOL', 0, 1, 2, '[{"codes":["BIOL-2033"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6908', 'BIOL-2033', 'Principles of Ecology', 'Principles of ecology provides an overview of the fundamental concepts of ecology at the individual, population, community, ecosystem and landscape levels of organization. Emphasis is placed on both developing the theory behind the concepts, and on the application of this theory to environmental issues. (3h lab).', 'BIOL', 3, 0, 2, '[{"codes":["BIOL-1113","and","BIOL-1123","with","minimum","grade","C-","or","permission","of","","Department"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["BIOL-2030L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6909', 'BIOL-3060L', 'BIOL 3063 Laboratory', '', 'BIOL', 0, 1, 3, '[{"codes":["BIOL-3063"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6910', 'BIOL-3063', 'Introductory Neuroscience', 'A lecture and laboratory course that covers cell biology of neurons, electrical and biochemical signalling, motor control, sensation and perception, learning and memory, and anatomy of the brain and spinal cord. Additional topics include special senses and diseases of the nervous system. Complementary to PSYC 3383. (3h lab). Prerequisite(s): BIOL 2013 with a minimum grade of C- or PSYC 2133 or CHEM 2713.', 'BIOL', 3, 0, 3, '[{"codes":["BIOl-2013","with","minimum","grade","C-","required","or","PSYC","2133","or","CHEM-2713"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["BIOL-3060L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6914', 'BIOL-3110L', 'BIOL 3113 Laboratory', '', 'BIOL', 0, 1, 3, '[{"codes":["BIOL-3113"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6915', 'BIOL-3113', 'Vertebrate Diversity', 'Evolution and diversity of the subphylum vertebrata, including a study of representative species and their morphological and phylogenetic relationships. Emphasis placed on the pivotal role of the dinosaurs in the evolution of tetrapods. (3h lab). Prerequisite(s): BIOL 2073 with a minimum grade of C-.', 'BIOL', 3, 0, 3, '[{"codes":["BIOL-2073","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["BIOL-3110L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6916', 'BIOL-3120L', 'BIOL 3123 Laboratory', '', 'BIOL', 0, 1, 3, '[{"codes":["BIOL-3123"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6917', 'BIOL-3123', 'Parasitology', 'Parasites are everywhere, and some cause devastating diseases of humans and other animals. Through exploration of parasite diversity, with focus on protozoa, worms, and arthropods, this course analyses benefits and drawbacks of parasitic existence, strategies to enhance transmission, evasion of host immunity, manipulation of host behaviour, and parasite epidemiology. Laboratories feature experimentation with live parasites and examination of preserved material. (3h lab). Prerequisite(s): BIOL 2013, BIOL 2053 and BIOL 2073, each with a minimum grade of C.', 'BIOL', 3, 0, 3, '[{"codes":["BIOL-2013,","BIOL-2053","and","BIOL-2073","with","a","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["BIOL-3120L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6919', 'BIOL-3140L', 'BIOL 3143 Laboratory', '', 'BIOL', 0, 1, 3, '[{"codes":["BIOL-3143"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6920', 'BIOL-3143', 'Animal Behaviour', 'Why animals do what they do from an evolutionary perspective, and the mechanics of how they do it. Optimality, evolutionarily stable strategies, foraging, escaping predators, communication, sexual reproduction and sexual selection, mating systems, parental care, group-living, territoriality, altruism, genetics of behaviour, sensory processing, hormones and control of behaviours, development, bird song, biological clocks. (3h lab). Prerequisite(s): BIOL 1113/BIOL 1123 with a minimum grade of C- or PSYC 3133.', 'BIOL', 3, 0, 3, '[{"codes":["BIOL-2073","or","PSYC","3133","with","minimum","grade","C-"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["BIOL-3140L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6921', 'BIOL-3150L', 'BIOL 3153 Laboratory', '', 'BIOL', 0, 1, 3, '[{"codes":["BIOL-3153"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6922', 'BIOL-3153', 'Principles of Development', 'An introduction to the early development of animals. Topics include comparative development of model species, pattern formation, induction, cell migration and differentiation, formation of the vertebrate body plan, metamorphosis, developmental genetics, and evolution. (3h lab). Prerequisite(s): BIOL 2013 with a minimum grade of C-.', 'BIOL', 3, 0, 3, '[{"codes":["BIOL-2013","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["BIOL-3150L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6923', 'BIOL-3160L', 'BIOL 3163 Laboratory', '', 'BIOL', 0, 1, 3, '[{"codes":["BIOL-3163"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6924', 'BIOL-3163', 'Comparative Embryology', 'A continuation of BIOL 3153 with a focus on advanced topics such as: Evo-Devo, Eco-Devo, sex determination, tool kit genes, stem cells, regeneration, cloning, and the developmental basis of disease. (3h lab). Prerequisite(s): BIOL 3153 with a minimum grade of C-.', 'BIOL', 3, 0, 3, '[{"codes":["BIOL-3153","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["BIOL-3160L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6926', 'BIOL-3170L', 'BIOL 3173 Laboratory', '', 'BIOL', 0, 1, 3, '[{"codes":["BIOL-3173"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6927', 'BIOL-3173', 'Animal Physiology 1', 'Key physiological systems of animals. Major topics covered include thermoregulation, osmoregulation, acid base balance, respiration and circulation. (3h lab).', 'BIOL', 3, 0, 3, '[{"codes":["BIOL-2013,","and","BIOL-2073","or","BIOT-2013,","all","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["BIOL-3170L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6928', 'BIOL-3180L', 'BIOL 3183 Laboratory', '', 'BIOL', 0, 1, 3, '[{"codes":["BIOL-3183"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6929', 'BIOL-3183', 'Animal Physiology 2', 'Topics covered include endocrinology, muscle physiology, basic neurophysiology, receptor physiology,movement and navigation. (3h lab). Prerequisite(s): BIOL 3173 with a minimum grade of C-; Corequisite(s): BIOL 3180L. Antirequisite(s): Major credit cannot be obtained for both BIOL 3173/BIOL 3183 and BIOL 2823, although BIOL 2823 can be used as a science elective.', 'BIOL', 3, 0, 3, '[{"codes":["BIOL-3173","with","minumum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["BIOL-3180L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6930', 'BIOL-3190L', 'BIOL 3193 Laboratory', '', 'BIOL', 0, 1, 3, '[{"codes":["BIOL-3193"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6931', 'BIOL-3193', 'Entomology', 'An introduction to the structure, function, evolution and taxonomy of the insects, the most diverse and abundant group of animals. Topics also include the ecology, behaviour, and impact, both in medical and economic terms, of these animals. A collection of insects gathered on field trips during regularly scheduled laboratories is required. (3h lab). Prerequisite(s): BIOL 2073 with a minimum grade of C-.', 'BIOL', 3, 0, 3, '[{"codes":["BIOL-2073","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["BIOL-3190L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6937', 'BIOL-3240L', 'BIOL 3243 Laboratory', '', 'BIOL', 0, 1, 3, '[{"codes":["BIOL-3243"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6938', 'BIOL-3243', 'Plant Growth and Development', 'The factors and mechanisms involved in the regulation of plant growth and development. Topics include phytohormones, differential growth responses, dormancy, photomorphogenesis and photoperiodism. (3h lab). Prerequisite(s): BIOL 2013 and BIOL 2043, each with minimum grades of C-, or permission of the Department.', 'BIOL', 3, 0, 3, '[{"codes":["BIOL-2013","and","BIOL-2043","with","minimum","grade","C-","required","or","permission","of","the","Department"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["BIOL-3240L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6947', 'BIOL-3290L', 'BIOL 3293 Laboratory', '', 'BIOL', 0, 1, 3, '[{"codes":["BIOL-3293"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6948', 'BIOL-3293', 'Flora of Nova Scotia', 'A survey of the flowering plants and ferns of the province. Identification by technical keys; important plant families; field recognition of common species; habitat preferences; and collecting methods will be covered. A properly annotated plant collection must be prepared. Lecture and Field work. (3h lab). Prerequisite(s): BIOL 1113/BIOL 1123 with a minimum grade of C-, or permission of the Department.', 'BIOL', 3, 0, 3, '[{"codes":["BIOL-1113","and","BIOL-1123","with","minimum","grade","C-","required","or","permission","of","the","Department"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["BIOL-3290L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6956', 'BIOL-3360L', 'BIOL 3363 Laboratory', '', 'BIOL', 0, 1, 3, '[{"codes":["BIOL-3363"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6957', 'BIOL-3363', 'Biodiversity', 'Global patterns of biodiversity and the underlying processes generating them. (3h lab). Prerequisite(s): BIOL 1113/BIOL 1123 with a minimum grade of C-.', 'BIOL', 3, 0, 3, '[{"codes":["BIOL-1113","and","BIOL-1123","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["BIOL-3360L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6958', 'BIOL-3370L', 'BIOL 3373 Laboratory', '', 'BIOL', 0, 1, 3, '[{"codes":["BIOL-3373"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6959', 'BIOL-3373', 'Aquatic Ecology', 'An exploration of freshwater and marine ecosystems emphasizing the relationships between ecosystem structure and function, aquatic community interactions, human activities that influence natural aquatic processes, and new technology and procedures for assessing the health of aquatic ecosystems, and to provide information critical for ecosystem-based management. Laboratory work is mainly field based.', 'BIOL', 3, 0, 3, '[{"codes":["BIOL","1113/BIOL","1123","with","a","minimum","grade","of","C-,","BIOL","2563","Marine","Biology","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["BIOL-3370L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6961', 'BIOL-3413', 'Research Topics 1', 'Laboratory or field investigations, or review of research topics in biology. Students participate in a research study which may include planning, developing suitable procedures and techniques, and/or undertaking a review or critical evaluation. Each student will write a research report and present findings. The research must be supervised by a member of the department. Prerequisite(s): Permission of supervisor and Department.', 'BIOL', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6962', 'BIOL-3420L', 'BIOL 3423 Laboratory', '', 'BIOL', 0, 1, 3, '[{"codes":["BIOL-3423"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6963', 'BIOL-3423', 'Histology 1', '??Histology is the study of the functional structure of cells, tissues and organs. We focus on vertebrate tissues and their dynamic nature throughout life, including development, renewal, pathology and aging. Histology 1 includes the primary tissue types and the circulatory and nervous systems. Labs examine healthy tissues and those impacted by disease, and include a histotechnique project. (3h lab).?', 'BIOL', 3, 0, 3, '[{"codes":["BIOL-2013","with","minimum","grade","C-"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["BIOL-3420L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6964', 'BIOL-3430L', 'BIOL 3433 Laboratory', '', 'BIOL', 0, 1, 3, '[{"codes":["BIOL-3433"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6965', 'BIOL-3433', 'Histology 2', 'Emphasizes the structure and functions of organ systems in vertebrates, including digestive, endocrine, reproductive and sensory systems. This course is offered in a learner centred format and is based on collaborative learning. (3h lab). Prerequisite(s): BIOL 3423 with a minimum grade of C-.', 'BIOL', 3, 0, 3, '[{"codes":["BIOL-3423","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["BIOL-3430L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6967', 'BIOL-3463', 'Evolution', 'A critical analysis of concepts and analytical methods in evolutionary biology. Topics include basic population genetics, the analysis of adaptations, natural and sexual selection, species and speciation, systematics and phylogenetic methods. Recent developments in evolutionary biology (e.g. Darwinian medicine, evolution of infectious diseases) are discussed. Prerequisite(s): BIOL 1113/BIOL 1123 with a minimum grade of C- and 60 credit hours, or permission of the instructor.', 'BIOL', 3, 0, 3, '[{"codes":["BIOL-1113","and","BIOL-1123","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6977', 'BIOL-3550L', 'BIOL 3553 Laboratory', '', 'BIOL', 0, 1, 3, '[{"codes":["BIOL-3553"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6978', 'BIOL-3553', 'Immunology', 'An introduction to the fundamental concepts of the defences of mammals and other organisms at the molecular, cellular and system levels. Topics include the organization and regulation of the immune system, cellular interactions among immune system components, immune dysfunction, and specific immune responses against pathogens. (2h tutorial). Note: For 2022-2023, BIOL-3550L is not required to be taken with the course.', 'BIOL', 3, 0, 3, '[{"codes":["BIOL-2013","and","BIOL-2053","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["BIOL-3550L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6981', 'BIOL-3570L', 'BIOL 3573 Laboratory', '', 'BIOL', 0, 1, 3, '[{"codes":["BIOL-3573"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6982', 'BIOL-3573', 'Appld & Enviro Microbiology', 'Earth could not support life without the activities of microorganisms. This course will examine the essential roles that microbes play in the biosphere, the unusual and surprising ways that they have adapted to harsh niches, and how humans are increasingly exploiting their biochemical abilities in food production, water purification, medicines, soil improvement and energy recovery. (3h lab). Prerequisite(s): BIOL 2053 with a minimum grade of C-; BIOL 2013 with a minimum grade of C- or permission of the instructor.', 'BIOL', 3, 0, 3, '[{"codes":["BIOL-2053","and","BIOL-2013","with","minimum","grade","C-","required","or","permission","or","instructor"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["BIOL-3570L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6983', 'BIOL-3580L', 'BIOL 3583 Laboratory', '', 'BIOL', 0, 1, 3, '[{"codes":["BIOL-3583"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6984', 'BIOL-3583', 'Eukaryotic Microbiology', 'An introduction to the structure, function, evolution and biodiversity of unicellular eukaryotic organisms, including protozoa, microbial fungi and unicellular algae. The ecology of free-living eukaryotic microbes and the immune responses of humans and other animals against pathogenic species will be discussed in detail. Laboratories include experiments with live protozoa and microscopical observations of prepared microbes. (3h lab). Prerequisite(s): BIOL 2013, BIOL 2053, and BIOL 2073, each with a minimum grade of C-.', 'BIOL', 3, 0, 3, '[{"codes":["BIOL-2013,","BIOL-2053,","and","BIOL-2073","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["BIOL-3580L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6986', 'BIOL-3610L', 'BIOL 3613 Laboratory', '', 'BIOL', 0, 1, 3, '[{"codes":["BIOL-3613"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6987', 'BIOL-3613', 'Principles of Genetics', 'Provides an overview of the fundamental principles of genetics with a focus on modern theories and techniques including gene editing, regulation of gene expression and the use of genetic information in forensics. The laboratory will train students in the skills used in DNA fingerprinting and analyses. (3h lab).', 'BIOL', 3, 0, 3, '[{"codes":["BIOL-2013","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["BIOL-3610L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6988', 'BIOL-3620L', 'BIOL 3623 Laboratory', '', 'BIOL', 0, 1, 3, '[{"codes":["BIOL-3623"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6989', 'BIOL-3623', 'Molecular Genetics & Genomics', 'An advanced genetics course that builds upon topics covered in Cell and Molecular Biology (BIOL 2013), with a focus on the genomics and genetics of disease. Modern molecular therapies and the role of pharmacogenomics and pharmacodynamics in exploring genetic diseases will be discussed. (3h lab).', 'BIOL', 3, 0, 3, '[{"codes":["BIOL","3613","with","a","minimum","grade","of","C-"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["BIOL-3620L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6992', 'BIOL-3660L', 'BIOL 3663 Laboratory', '', 'BIOL', 0, 1, 3, '[{"codes":["BIOL-3663"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6993', 'BIOL-3663', 'Introductory Mycology', 'An introduction to Kingdom Fungi, including biology, taxonomy, ecology and identification of fungi, with an emphasis on field collections and documenting Nova Scotia''s fungal diversity. Topics include plant-fungal, fungal-animal and fungal-bacterial interactions, fungal secondary metabolites, marine fungi, as well as industrial, medical, veterinary, forestry and agricultural applications of the study of fungi. (3h lab). Prerequisite(s): BIOL 2013, and BIOL 2043 or BIOL 2053, each with minimum grade of C-, or permission of the instructor.', 'BIOL', 3, 0, 3, '[{"codes":["BIOL-2013,","and","BIOL-2043","or","BIOL-2053","with","minimum","grade","C-","required","or","permission","of","instructor"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["BIOL-3660L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('6996', 'BIOL-3753', 'The Arctic Environment', 'An introduction to the extreme world of Arctic terrestrial, aquatic and marine environments and biota. Topics will include the physical and ecological setting, food webs, wildlife diseases, key and iconic wildlife species and threats to their health, as well as an environmental and ecological perspective on history, peoples, and current issues. Focus on Canadian Arctic regions. Prerequisite(s): BIOL 1113 with a minimum grade of C, or permission of the instructor. Recommend completion of at least one second-year biology course.', 'BIOL', 3, 0, 3, '[{"codes":["BIOL-1113","with","minimum","grade","C-","required","or","permission","of","instructor"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["3hrs","from","2000","level","BIOL","course"],"textExtension":"- Recommended prior to taking this course, but is not required."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7000', 'BIOL-3840L', 'BIOL 3843 Laboratory', '', 'BIOL', 0, 1, 3, '[{"codes":["BIOL-3843"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7001', 'BIOL-3843', 'Marine Invertebrate Zoology', 'A survey of the major invertebrate phyla, their morphology, taxonomy and evolutionary relationships. Local marine species are emphasized and studied from both living and preserved materials. Field trips required. (3h lab). Prerequisite(s): BIOL 2073 with a minimum grade of C-.', 'BIOL', 3, 0, 3, '[{"codes":["BIOL-2073","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["BIOL-3840L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7002', 'BIOL-3880L', 'BIOL 3883 Laboratory', '', 'BIOL', 0, 1, 3, '[{"codes":["BIOL-3883"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7003', 'BIOL-3883', 'Chemical Ecology', 'Chemical Ecology examines the roles of chemical cues in the lives of animals, plants and microbes, including informative roles, such as mate location, navigation, sociality, resource procurement and defence. Topics will include relationships between chemical cues and environmental issues, including applied aspects and physiological processing of chemicals by organisms. (3h lab). Prerequisite(s): BIOL Core, each course completed with a minimum grade of C-, CHEM 2513.', 'BIOL', 3, 0, 3, '[{"codes":["BIOL-1113,","BIOL-1123,","BIOL-2013,","BIOL-2043,","BIOL-2053","and","BIOL-2073","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["CHEM-2513"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["BIOL-3880L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7007', 'BIOL-3993', 'Special Topics in Biology', 'Special topics or projects that are not covered in the regular curriculum. For research-based courses, please see BIOL 3413/ BIOL 4413 and BIOL 4996. Prerequisite(s): Permission of Department.', 'BIOL', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7009', 'BIOL-4023', 'Intellectual Origins Mod. Bio', 'A brief survey of major developments in biological thought. The philosophical basis of modern biology will be examined with emphasis on the development of the scientific method. The development of evolutionary thinking and the other major concepts in biology will be traced. May not be used by arts students as a science credit. Prerequisite(s): 12h in BIOL above the 1000-level, each completed with a minimum grade of C-.', 'BIOL', 3, 0, 4, '[{"codes":["12h","BIOL","above","1000","level","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7010', 'BIOL-4110L', 'BIOL 4113 Laboratory', '', 'BIOL', 0, 1, 4, '[{"codes":["BIOL-4113"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7011', 'BIOL-4113', 'Fish Biology', 'An exploration of the evolution, zoogeography, functional morphology, taxonomy, reproduction, physiology and behaviour of marine and freshwater fishes on a global scale. Consideration will be given to social, stewardship and conservation aspects of commercial and recreational fisheries. Labs will emphasize morpholgy and identification of fishes. (3h lab).Prerequisite(s): BIOL-2073 and BIOL-2563, or one Biology course at the 3000 or 4000 level. Corequisite(s): BIOL-4110L.', 'BIOL', 3, 0, 4, '[{"codes":["Prerequisite(s):","BIOL-2073,","and","BIOL-2563","or","one","Biology","course","at","the","3000","or","4000","level.","Corequisite(s):","BIOL-4110L"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["BIOL-4110L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7012', 'BIOL-4120L', 'BIOL 4123 Laboratory', '', 'BIOL', 0, 1, 4, '[{"codes":["BIOL-4123"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7013', 'BIOL-4123', 'Mammalogy', 'Evolution, functional morphology, reproduction, physiology, evolutionary and behavioural ecology of mammals. Labs stress classification, anatomy and functional morphology. Field trips. (3h lab). Prerequisites: BIOL 2073 with a minimum grade of C-.', 'BIOL', 3, 0, 4, '[{"codes":["BIOL-2073","with","miniumum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["BIOL-4120L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7018', 'BIOL-4160L', 'BIOL 4163 Laboratory', '', 'BIOL', 0, 1, 4, '[{"codes":["BIOL-4163"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7019', 'BIOL-4163', 'Ornithology', 'Birds from an ecological and evolutionary perspective. The fossil record, hybrid zones, biogeography, classification. Flight and associated morphological and physiological changes. Brains and hormones, migration and navigation, song, territoriality, sexual selection, sperm competition, nests, eggs, incubation, parental care, sex ratio manipulation, cooperative breeding, brood parasitism, longevity, population monitoring. (3h lab). Prerequisite(s): BIOL 2073 with a minimum grade of C-.', 'BIOL', 3, 0, 4, '[{"codes":["BIOL-2073;","MIN","GRADE","C-"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["BIOL-4160L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7020', 'BIOL-4170L', 'BIOL 4173 Laboratory', '', 'BIOL', 0, 1, 4, '[{"codes":["BIOL-4173"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7024', 'BIOL-3383', 'Data Science Living Planet', 'The application of data science in biology, ecology, environmental, health sciences and other disciplines. Curating data, creating plots, tables, and maps (GIS), and production of reproducible research using R/RStudio software are emphasized. Analyses include understanding and interpreting life sciences experimental and observational data for scientific communications. An introduction to general linear models (e.g. regression, ANOVA, mixed models) is provided. Biology Majors may use BIOL 3383 to either fulfill the Biology Core or as credit toward the 3000-4000 level requirement, but not both.', 'BIOL', 3, 0, 3, '[{"codes":["MATH-2223,","MATH-2243,","or","MATH-2253"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7027', 'BIOL-4350L', 'BIOL 4353 Laboratory', '', 'BIOL', 0, 1, 4, '[{"codes":["BIOL-4353"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7028', 'BIOL-4353', 'Pathogenic Microbiology', 'This course examines the ceaseless struggle between the antimicrobial defences of humans and the virulence factors of bacterial and protozoan pathogens. Important human infectious diseases will be studied as examples of the contest between hosts and parasites, and as examples of how modern medicine is driving evolution of human pathogens. (3h lab). Prerequisite(s): BIOL 3553 with a minimum grade of C+.', 'BIOL', 3, 0, 4, '[{"codes":["BIOL-3553","with","minimum","grade","C+","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["BIOL-4350L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7030', 'BIOL-4413', 'Research Topics 2', 'This course consists of advanced laboratory and/or field investigations of a research topic in biology. Each student will conduct research, write a research paper and may be expected to present their findings. The research must be supervised or co-supervised by a faculty member in the Department of Biology.', 'BIOL', 3, 0, 4, '[{"codes":["BIOL-3413","with","a","minimum","grade","of","C-"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7031', 'BIOL-4420L', 'BIOL 4423 Laboratory', '', 'BIOL', 0, 1, 4, '[{"codes":["BIOL-4423"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7032', 'BIOL-4423', 'Conservation Biology', 'The theory and practice of conservation biology including human impacts on the biosphere, historical and present worldviews of human and nature, Indigenous perspectives and the honourable harvest, protected area design, management and restoration, ecosystem services, extinction risk, invasive species and species at risk. (3h lab).', 'BIOL', 3, 0, 4, '[{"codes":["BIOL-1113","and","BIOL-1123","with","minimum","grade","C-"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["BIOL-4420L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7034', 'BIOL-4443', 'Comparative Animal Physiology', 'Lectures, research and student seminars emphasizing physiological similarities and differences of vertebrates and invertebrates. Prerequisite(s): BIOL 3183 with a minimum grade of C-.', 'BIOL', 3, 0, 4, '[{"codes":["BIOL-3183","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7042', 'BIOL-4520L', 'BIOL 4523 Laboratory', '', 'BIOL', 0, 1, 4, '[{"codes":["BIOL-4523"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7045', 'BIOL-4540L', 'BIOL 4543 Laboratory', '', 'BIOL', 0, 1, 4, '[{"codes":["BIOL-4543"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7046', 'BIOL-4543', 'Coastal and Estuarine Ecology', 'The physical, chemical and biological features and processes of coastal and estuarine waters. Ecosystem health indicators and impacts of pollutants, invasive species, tidal energy extraction, rehabilitation of coastal wetlands and estuaries, and other anthropogenic activities will be discussed. Field work on nearby shores and estuaries is required. (3h lab). Prerequisite(s): BIOL 2073 with a minimum grade of C-.', 'BIOL', 3, 0, 4, '[{"codes":["BIOL-2073","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["BIOL-4540L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7058', 'BIOL-4653', 'Seminar in Ecology', 'This course explores current topics in ecology through presentations, analysis, and critiques of recent papers in ecology journals. Students will gain an in-depth expertise in reading, discussing and critiquing the ecological literature.', 'BIOL', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7059', 'BIOL-4670L', 'BIOL 4673 Laboratory', '', 'BIOL', 0, 1, 4, '[{"codes":["BIOL-4673"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7060', 'BIOL-4673', 'Molecular Techniques', 'A hands-on introduction to the use of a variety of molecular techniques applicable to questions in ecology, evolution and medicine. Students will be required to complete a project using one or more molecular tools. Projects are determined in consultation with the course instructor. (3h lab) Prerequisite(s): BIOL-1113 and 1123, or BIOL-1813; BIOL-2013, each with minimum grades of C-, or Permission of the instructor. Corequisite(s): BIOL-4670L', 'BIOL', 3, 0, 4, '[{"codes":["Take","BIOL-1113","and","BIOL-1123,","or","BIOL-1813;","BIOL-2013,","each","with","minimum","grades","of","C-,","or","permission","of","the","instructor."],"textExtension":"- Must be completed prior to taking this course."},{"codes":["Take","BIOL-4670L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7063', 'BIOL-4773', 'Natural Product Chemistry', 'Overview of natural products, biosynthesis of secondary metabolites, modern techniques for studying secondary metabolism and biosynthesis, biological reactions, chemical interactions between living organisms, and classes of bioactive compounds grouped according to building blocks and biogenesis. This course will complement the basic knowledge necessary to students in diverse fields (e.g., organic chemistry, agricultural chemistry, biochemistry, nutrition, and pharmacy). Prerequisite(s): CHEM 2713 or permission of instructor. Antirequisite(s): Credit can be obtained for only one of BIOL 4773 or CHEM 4773.', 'BIOL', 3, 0, 4, '[{"codes":["CHEM-2713","or","permission","of","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7064', 'BIOL-4830L', 'BIOL 4833 Laboratory', '', 'BIOL', 0, 1, 4, '[{"codes":["BIOL-4833"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7071', 'BIOL-5013', 'Research Methods in Biology 1', 'An exploration of the history and philosophy of science, expectations of students and supervisors, and practical approaches to biological research, publishing, and critical review. Students complete a research proposal, research grant application, and/or manuscript from current or past research. Students meet weekly to explore topics, and review and critique the work of others. Proposals and applications are presented and defended. Prerequisite(s): none.', 'BIOL', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7072', 'BIOL-5023', 'Research Methods in Biology 2', 'An exploration of current and historical topics in biology through seminar discussions, original research projects, critical reviews, data exploration (visual, mathematical, and statistical), software implementation, presentations, workshops, and/or field trips.', 'BIOL', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7073', 'BIOL-5033', 'Adv Topic in Graduate Biol 3', 'Students will choose a course from one of the following subheadings in consultation with their supervisor/supervisory committee: Terrestrial Ecology; Molecular Biology and Genetics; Plant Biology; Animal Biology; Conservation and Population Biology; Aquatic Ecology; Microbiology and Parasitology.', 'BIOL', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7074', 'BIOL-5043', 'Adv Topic in Graduate Biol 4', 'Students will choose a course from one of the following subheadings in consultation with their supervisor/supervisory committee: Terrestrial Ecology; Molecular Biology and Genetics; Plant Biology; Animal Biology; Conservation and Population Biology; Aquatic Ecology; Microbiology and Parasitology.', 'BIOL', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7075', 'BIOL-5053', 'Adv Topic in Graduate Biol 5', 'Students will choose a course from one of the following subheadings in consultation with their supervisor/supervisory committee: Terrestrial Ecology; Molecular Biology and Genetics; Plant Biology; Animal Biology; Conservation and Population Biology; Aquatic Ecology; Microbiology and Parasitology.', 'BIOL', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7109', 'BIOL-5960', 'Graduate Thesis', '', 'BIOL', 0, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7114', 'BUSI-1013', 'Financial Accounting 1', 'An introduction to financial statements from both the preparer''s and user''s perspectives. Students learn how to prepare, read and analyze the income statement, balance sheet and cash flow statement. Students will also learn how financial accounting supports organizational decision making.', 'BUSI', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7121', 'BUSI-1703', 'Introduction to Business', 'Students develop a general knowledge of various models of business, industry and organizations, functional areas of business, the role of management, and interrelationships between business, society and external forces. Through lectures and required 1-hour applied workshops, students gain basic business research skills, learn how organizations and market systems have developed over time, and the challenges of operating in contemporary society.
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7127', 'BUSI-2013', 'Management Accounting', 'The development of various accounting concepts as an aid in managerial decisions. An examination of the information provided by financial statements, reports, budgets and other sources of data available to management. The role of accounting in the business environment and its relationship to general decision theory. Prerequisite(s): BUSI 1013 with a minimum grade of C-.', 'BUSI', 3, 0, 2, '[{"codes":["BUSI-1013","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7129', 'BUSI-2033', 'Financial Accounting 2', 'A continuation of the study of introductory financial accounting from both the preparer''s and user''s perspectives. Students study financial accounting concepts, methods, standards and techniques. Topical coverage includes cash and internal control, receivables, inventories, capital assets, current and long-term liabilities, shareholders'' equity, and financial statement analysis. Prerequisite(s): BUSI 1013 with a minimum grade of C-.', 'BUSI', 3, 0, 2, '[{"codes":["BUSI-1013","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7134', 'BUSI-2223', 'Fundamentals of Finance 1', 'A combination of lectures, problem-solving, case studies, group discussions, current events and field research are used to introduce students to the theory and practice of corporate finance. The course will focus on the basic concepts of securities markets, financial analysis, cost-benefit analysis and decision making under conditions of uncertainty. Prerequisite(s): ECON 1013, ECON 1023, ECON 2613, and MATH 1613 or MATH 1013. Corequisite: ECON 2613 or MATH 1253.', 'BUSI', 3, 0, 2, '[{"codes":["ECON-1013,","ECON-1023,","and","either","","MATH-1613","or","MATH-1013"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["Corequisite:","ECON-2613","or","MATH-1253."],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7136', 'BUSI-2233', 'Fundamentals of Finance 2', 'A combination of lectures, problem-solving, case studies, group discussions, current events and field research are used to introduce students to the theory and practice of corporate finance. The course continues on from the Fundamentals of Finance 1 course to further explore financial decision-making under conditions of uncertainty and the risk-return trade-off in corporate finance. Prerequisite(s): BUSI 2223 with a minimum grade of C-.', 'BUSI', 3, 0, 2, '[{"codes":["BUSI-2223","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7141', 'BUSI-2423', 'Marketing Principles', 'The basic concepts and principles of marketing as practiced by organizations. The intent is to provide students with an understanding of how the marketing function fits within the overall structure of the organization and how it contributes to achieving the organization''s mission. Areas include the marketing environment, marketing research, consumer behaviour, the marketing mix (4P''s), segmentation, targeting, positions, and marketing strategy. Prerequisite(s): COMM 1213 with a minimum grade of C-, ECON 1013 and ECON 1023.', 'BUSI', 3, 0, 2, '[{"codes":["COMM-1213","(or","CODE-1043)","with","minimum","grade","C-","required","and","ECON-1013","and","ECON-1023"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7142', 'BUSI-2433', 'Marketing Strategy', 'A continuation of BUSI 2423 with an emphasis on the application of basic concepts and theories to a variety of marketing issues. The intent of this course is to provide students with a deeper understanding of the process of formulation, implementation, and management of marketing strategy. Using the case study method, students will gain experience in analysis and decision-making skills. Prerequisite(s): BUSI 2423 with a minimum grade of C-.', 'BUSI', 3, 0, 2, '[{"codes":["BUSI-2423","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7143', 'BUSI-2513', 'Operations Management', 'A general management approach to the fundamental aspects of manufacturing and service operations. Decision making in the areas of process selection, capacity analysis, layout, planning and scheduling, job design, quality and inventory control. Prerequisite(s): ECON 1013, ECON 1023, ECON 2613, and MATH 1613 or MATH 1013. Corequisite: ECON-2613 or MATH-1253.', 'BUSI', 3, 0, 2, '[{"codes":["ECON-1013,","ECON-1023","and","either","MATH-1613","or","MATH-1013."],"textExtension":"- Must be completed prior to taking this course."},{"codes":["Corequisite:","ECON-2613","or","MATH-1253."],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7149', 'BUSI-2733', 'Organizational Behaviour', 'The behaviour of individuals and groups in organizational settings. The effects of personality, perception, learning and motivation on individual performance. The interaction between individual determinants of behaviour and group dynamics.', 'BUSI', 3, 0, 2, '[{"codes":["COMM-1213","(or","CODE-1043)","and","BUSI-1703,","both","with","minimum","grade","C-","required."],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7150', 'BUSI-2743', 'Organizational Theory', 'This course examines current theory and research on the design and behaviour of effective organizations. It focuses on developing in students an understanding of mainstream and alternatives theories of organizational and economics theories of the firm. Prerequisite(s): BUSI 2733, with a minimum grade of C-.', 'BUSI', 3, 0, 2, '[{"codes":["BUSI","2733","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7151', 'BUSI-2763', 'Organizations & Sustainability', 'Students will study frameworks, models, and tools for planning for and implementing sustainability focused strategies and activities within organizations. Perspectives on how organization impact social and environmental sustainability will be considered along with how aspects of sustainability impact the various dimensions of organization management (marketing, finance, operations, etc.). Various organizational types (for profit, non-profit, etc.) will be considered. Prerequisite(s): BUSI 1703 or both of ESST 1003 and ESST 1023.', 'BUSI', 3, 0, 2, '[{"codes":["BUSI-1703","OR","ESST-1003","AND","ESST-1023"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7152', 'BUSI-2773', 'Entrepreneurship', 'An introduction to entrepreneurship theory and practice that considers different ways of defining entrepreneurship, processes entrepreneurs use to create/discover and exploit opportunities, the social context of entrepreneurship, entrepreneurial ways of thinking and learning, and various kinds of entrepreneurial ventures such as those found within existing organizations and those that aim for social/environmental impact. Includes an experiential learning project.', 'BUSI', 3, 0, 2, '[{"codes":["Second-year","standing,","or","permission","of","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7153', 'BUSI-2803', 'Business Technology Management', 'An examination of the general principles of information technology and current technologies. Emphasis is on managing technology, and the government''s effort to develop standards and current industry policies. The management of technology is explored as a means of improving management and practice and creating strategic competitive advantage. The restructuring of organizations to accommodate these new technologies is also explored. Prerequisite(s): BUSI 1703, COMM 1213, each with a minimum grade of C-, and MATH 1613 or MATH 1013.', 'BUSI', 3, 0, 2, '[{"codes":["Both","COMM-1213","(or","CODE-1043)","and","BUSI-1703","with","minimum","grade","C-","required,","and","either","MATH-1613","or","MATH-1013."],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7166', 'BUSI-3063', 'Business Analytics Modeling 1', 'An introduction to the use of mathematical modeling to support managerial decision making. Modeling techniques covered include linear programming, regression analysis, time series forecasting and simulation. Spreadsheet software is used as the analytic platform for developing models. Prerequisite(s): BUSI 2513 with a minimum grade of C-.', 'BUSI', 3, 0, 3, '[{"codes":["BUSI-2513","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7167', 'BUSI-3073', 'Intermediate Accounting 1', 'Financial accounting functions and basic theory including the conceptual framework underlying financial accounting. The CPA Canada Handbook will be used. Recognition, measurement and disclosure of revenue and assets including inventories, investments, capital assets and intangible assets. Suitable for students considering a professional accounting designation or finance career. Prerequisite(s): BUSI 2013 and BUSI 2033, each with a minimum grade of C-.', 'BUSI', 3, 0, 3, '[{"codes":["BUSI-2013","and","BUSI-2033","with","","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7168', 'BUSI-3083', 'Intermediate Accounting 2', 'This course builds on the concepts in BUSI 3073 and deals with liabilities, recognition, measurement and disclosure, shareholders'' equity and special topics including corporate income tax and leases. The CPA Canada Handbook will be used. Prerequisite(s): BUSI 3073 with a minimum grade of C-.', 'BUSI', 3, 0, 3, '[{"codes":["BUSI-3073","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7169', 'BUSI-3113', 'Cost Systems', 'Purposes of cost accounting; cost accumulation and responsibility centres; costing methods for product; process, job-orders, joint-products, by-products, and distribution (marketing); cost analysis and systems for planning, controlling, and decision making. Prerequisite(s): BUSI 2013 and BUSI 2033, each with a minimum grade of C-.', 'BUSI', 3, 0, 3, '[{"codes":["BUSI-2013","and","BUSI-2033","with","a","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7174', 'BUSI-3233', 'International Finance', 'This course develops ability to understand and analyze issues in financial management in an international context. Emphasis is on decision-making skills in international capital markets and the financial function in the multinational corporation. Prerequisite(s): BUSI 2233 with a minimum grade of C-, BUSI 3273 or BUSI 3243.', 'BUSI', 3, 0, 3, '[{"codes":["BUSI-2233","with","minimum","grade","C-","required","and","BUSI-3273","or","BUSI-3243"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7175', 'BUSI-3243', 'Intermediate Finance', 'This course delves further into the concepts and theories introduced in BUSI 2223, 2233, and introduces valuation, value-based management and strategic financing decisions. The course prepares the student for upper level finance electives. Prerequisite(s): BUSI 2233 with a minimum grade of C-.', 'BUSI', 3, 0, 3, '[{"codes":["BUSI-2233","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7176', 'BUSI-3253', 'Personal Financial Management', 'This course develops the principles upon which the sound management of personal financial resources are based. Emphasis is placed on the understanding, mathematical analysis and evaluation of financial products and strategies within the context of the Canadian banking and taxation systems. Issues related to providing advice in the context of the financial services industry are emphasized. Prerequisite(s): BUSI 2223 with a minimum grade of C-.', 'BUSI', 3, 0, 3, '[{"codes":["BUSI-2223","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7178', 'BUSI-3273', 'Invt Analysis', 'Financial assets and the markets in which they are traded. The analysis of common and preferred stock, bonds, warrants, and working knowledge of investing. Prerequisite(s): BUSI 2233 with minimum grade of C-, or permission of the instructor.', 'BUSI', 3, 0, 3, '[{"codes":["BUSI-2223","with","minimum","grade","C-","required","or","permission","of","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7180', 'BUSI-3293', 'Managing E-Business', 'This course focuses on the foundations of e-business, business-to-consumer and business-to-business strategies. Topics include buying and selling on the world wide web, back-office integration, impact of the business-to-consumer e-business on logistics and supply chain management, hardware and software of the internet, intranets and extranets, technological innovations and their impact, and competitive dynamics of firms operating in internet enabled operating environments. Prerequisite(s): BUSI-2803 and third-year standing.', 'BUSI', 3, 0, 3, '[{"codes":["BUSI-2803","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["3rd","year","standing","(55h","or","more","completed","credits)"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7182', 'BUSI-3313', 'Human Resource Management', 'The human problems of the management of all work situations, supervision by authority and motivation, communication and introduction of change, organization of work efforts, employee development, performance incentives, personnel policy, and management responsibilities. Prerequisite(s): BUSI 2733 with a minimum grade of C-.', 'BUSI', 3, 0, 3, '[{"codes":["BUSI-2733","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7183', 'BUSI-3323', 'Employment Relations', 'Employment relations refers to the nature, practice, and outcomes of relations between management and non-union employees under an individual employment contract. The course will consider: the nature of the non-union employment relationship; employee rights in the legislated and common law of Canada; ensuring fairness through employee voice, involvement, and communication; related issues such as discipline, dismissal, job security, and downsizing. Prerequisite(s): BUSI 3313 with a minimum grade of C-.', 'BUSI', 3, 0, 3, '[{"codes":["BUSI-3313","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7184', 'BUSI-3373', 'Taxation', 'This course introduces the Canadian income tax system with coverage of both personal and corporate taxation. Students learn the fundamental principles of taxation, compliance requirements, and how to apply specific tax provisions in the Income Tax Act to determine taxable income, provincial and federal taxes.', 'BUSI', 3, 0, 3, '[{"codes":["BUSI-2013","and","BUSI-2033","with","minimum","grade","of","C-"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7187', 'BUSI-3433', 'Consumer Behaviour', 'The practices of business firms, the behaviour of consumers and consumer decision making. A behavioural science approach will be used to analyze and evaluate the consumer and business environments and the forces affecting them. Prerequisite(s): BUSI 2433, with a minimum grade of C-.', 'BUSI', 3, 0, 3, '[{"codes":["BUSI-2433","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7189', 'BUSI-3463', 'Global Marketing Strategy', 'This course focuses on firms'' global strategic marketing processes. Major topics covered include challenges of pursuing markets globally, opportunity selection, globalization versus localization, modern global marketing strategies and practices, and different modes of foreign market entry. Prerequisite(s): BUSI 2433 with a minimum grade of C-.', 'BUSI', 3, 0, 3, '[{"codes":["BUSI-2433","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7190', 'BUSI-3473', 'Marketing Research', 'This course provides students with a solid understanding of the use of marketing research. Exploring methods and procedures used in designing and executing a marketing research project (including analytic processes), students will understand how to evaluate research data and write research reports to support management decision making. Prerequisite(s): BUSI 2433.', 'BUSI', 3, 0, 3, '[{"codes":["BUSI-2433"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7192', 'BUSI-3483', 'Business Research', 'The conduct of research. Topics will include research design from a variety of methodological perspectives, sampling, data collection, analysis and presentation of results. Practical projects done in conjunction with BUSI 3993 will be theoretically informed. Prerequisite: Third year standing or higher in the BBA program.', 'BUSI', 3, 0, 3, '[{"codes":["At","least","3rd","year","standing","(55h","or","more","completed","credits)"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7196', 'BUSI-3613', 'Business Law', 'The course raises awareness of the relevance and importance of the law in business and enables students to use knowledge of the law to improve business decisions and avoid unnecessary legal difficulties. The key elements are the Canadian legal system; the basics of contracts and torts; and a framework for identifying and managing legal risks faced by organizations.', 'BUSI', 3, 0, 3, '[{"codes":["(BUSI","1703","and","COMM","1213)","or","(LAWS","1003","and","ENGL","1413)","each","with","a","minimum","grade","of","C-","and","2nd","year","standing"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["2nd","Year","Standing","(25h","or","more","completed","credits)"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7197', 'BUSI-3623', 'Business Law 2', 'The course extends the topics of BUSI 3613 into the other areas of law that are important for business and presents the law in a way that relates to the functional areas of business. The course topics are organized under major headings - business organizations; types of types of property; employment; marketing; and finance. Prerequisite(s): BUSI 3613 with a minimum grade of C-.', 'BUSI', 3, 0, 3, '[{"codes":["BUSI-3613","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7199', 'BUSI-3643', 'Consumer Law', 'A study of law as it relates to consumers in today''s marketplace, with special emphasis on the protection of consumers in their purchase and use of goods and services. Federal and provincial legislation which affects the consumer are explored in detail.', 'BUSI', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7200', 'BUSI-3723', 'Organizational Change', 'A systems approach to change in organizations, illustrating the interrelationships of structure, technology, individual and group behaviour, and organizational climate. A seminar format is used, with discussion centering on a variety of analyses of organizational change, and a selection of case studies. Prerequisite(s): BUSI 2733 and BUSI 2743.', 'BUSI', 3, 0, 3, '[{"codes":["BUSI-2733","and","BUSI-2743"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7203', 'BUSI-3753', 'Gend & Diver in Organizations', 'Students will be introduced to the diverse world of work by examining demographic trends, patterns of work, and subsequent legislative and non-legislative attempts to ''manage diversity''. Topics will include: the gendering of work; masculinity and femininity at work; sexuality and sexual orientation at work; race, class, and ethnicity at work; and ability/disability at work. Prerequisite(s): BUSI 2733 or WGST 2906, or permission of the instructor.', 'BUSI', 3, 0, 3, '[{"codes":["BUSI-2733","or","WGST-2906","or","permission","of","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7204', 'BUSI-3763', 'Cross-Cultural Management', 'This course introduces students to important frames of reference, theories and concepts to understand the behavioural and social implications of managing culturally diverse organizations. Prerequisite(s): BUSI 2733.', 'BUSI', 3, 0, 3, '[{"codes":["BUSI-2733"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7206', 'BUSI-3786', 'Doing Business Abroad', 'This course provides students with insight into the economic conditions, business practices, work environments, cultural context and societal norms of a foreign country. Learning will occur through travel to the country, site visits, class lectures, and course assignments. Note: Travel fees apply. For the Winter 2027 semester, the class lectures will be delivered virtually by St. Francis Xavier University but closely supported by Acadia University. Course Credits will be transferred to Acadia University at the conclusion of the course.  Prerequisite(s): 3rd-year standing and permission of the Instructor.', 'BUSI', 6, 0, 3, '[{"codes":["At","least","3rd","year","standing","(55h","or","more","completed","by","January","2027)","and","permission","of","the","instructor.","\r\n\r\nPlease","email","Conor","Vibert","(conor.vibert@acadiau.ca)","for","costs","and","draft","course","syllabus.","Airfare,","train,","and","accommodation","need","to","be","paid","before","the","end","of","November","2026","and","prior","to","taking","this","course."],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7207', 'BUSI-3813', 'Business Analytics Modeling 2', 'This course focuses on developing quantitative models to support decision making in situations involving large amounts of quantitative data. The modeling techniques covered in this course include: classification, clustering, forecasting, and tree methods. Prerequisite(s): BUSI 3063.', 'BUSI', 3, 0, 3, '[{"codes":["BUSI-3063"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7208', 'BUSI-3853', 'Design & Busi Model Innovation', 'This hands-on course explores the relationship between innovation and business strategy, and the role of design thinking in the innovation process. Student teams apply design thinking methods and client engagement skills to develop product and business model designs for an entrepreneurial venture. Prerequisite(s): BUSI 2803, BUSI 2773, each with a minimum grade of C-.', 'BUSI', 3, 0, 3, '[{"codes":["BUSI-2803","and","BUSI-2743","with","a","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7212', 'BUSI-3913', 'Independent Study in Business', 'Independent study of a topic not covered in the regular curriculum. A major paper or project is produced under the supervision of a faculty advisor. Prerequisite(s): Third-year standing or higher or permission of the Department.', 'BUSI', 3, 0, 3, '[{"codes":["3rd-year","standing","(55h","or","more","completed)"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7213', 'BUSI-3923', 'Special Topics 2', 'Special projects or topics not covered in the regular curriculum. Visiting instructors or Acadia faculty members may present specific subjects. Prerequisite(s): Third-year standing or higher, or permission of the instructor.', 'BUSI', 3, 0, 3, '[{"codes":["3rd-year","standing","(55h","or","more","completed)"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7215', 'BUSI-3993', 'Business Research Literacy', 'Seminar, reading and discussion of scientific inquiry, problem formulation, literature research, theoretical formulation, and procedures and organization of honours research project. Development of research proposal. Prerequisite(s): Third year standing or higher and registration in the BBA honours program.', 'BUSI', 3, 0, 3, '[{"codes":["3rd","year","standing","(55h","or","more","completed","credits)"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7218', 'BUSI-4073', 'Advanced Accounting', 'An advanced financial accounting course that includes reporting for investments, companies subject to significant influence, business combinations and joint ventures. Techniques and theory are covered for other specialized areas including segmented information, interim reporting, foreign currency transactions and operations, hedge accounting, not-for-profit organizations, and government accounting.', 'BUSI', 3, 0, 4, '[{"codes":["BUSI-3083","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7219', 'BUSI-4083', 'Integrated Cases in Accounting', 'This course is a capstone course designed to support students pursuing a Canadian Chartered Professional Accounting (CPA) designation. Students will be introduced to more complex corporate income tax issues, and integrated case analysis across financial reporting, income tax, and auditing competencies.', 'BUSI', 3, 0, 4, '[{"codes":["BUSI-4073","with","minimum","grade","of","C-"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7220', 'BUSI-4113', 'Audit and Assurance', 'Auditing procedures for balance sheet and profit and loss items, staff organization and reports for internal control; auditing concepts, professional ethics, legal responsibility, and fraud. Prerequisite(s): BUSI 2033 with a minimum grade of C-.', 'BUSI', 3, 0, 4, '[{"codes":["BUSI-2033","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7223', 'BUSI-4223', 'Portfolio Management', 'This course focuses on modern portfolio theory and the issues and mathematics involved in managing portfolios of securities. Theory is applied to the understanding of pension fund management in a simulation exercise. Prerequisite(s): BUSI 3273.', 'BUSI', 3, 0, 4, '[{"codes":["BUSI-3273"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7224', 'BUSI-4233', 'Financial Analysis & Modelling', 'The course focusses on developing investment models using financial statements and public market information related to stocks, bonds, and other financial assets. Students will develop applied technical and fundamental models focused on asset selection techniques as well as investment performance measurement and reporting. Prerequisite(s): BUSI 3243 and BUSI 3273.', 'BUSI', 3, 0, 4, '[{"codes":["","BUSI-3243","and","BUSI-3273"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7225', 'BUSI-4243', 'Derivative Secs. & Risk Mgmt', 'This course provides a comprehensive introduction to derivative securities such as futures, options, and swaps. Various trading strategies are discussed and applications to financial risk management are emphasized. Prerequisite(s): BUSI 3273.', 'BUSI', 3, 0, 4, '[{"codes":["BUSI-3273"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7226', 'BUSI-4253', 'Project & Enterprise Valuation', 'This course is a study of valuation methods for investments ranging from capital budgeting projects to the mergers and acquisitions of businesses. The theory and application of financial models for decision-making under uncertainty and the evaluation of strategic benefits are explored. Prerequisite(s): BUSI 3243.', 'BUSI', 3, 0, 4, '[{"codes":["BUSI-3243"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7227', 'BUSI-4313', 'Labour Relations', 'The structure, functions, attitudes, and philosophy of labour organizations in collective bargaining; consideration of the behaviour of the actors in the labour relations scene; and consideration of the basic stages of the labour relations process (organization, certification, negotiation, grievance, arbitration) from the viewpoint of labour, management, and the law. Prerequisite(s): BUSI 3313.', 'BUSI', 3, 0, 4, '[{"codes":["BUSI-3313"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7231', 'BUSI-4413', 'Personal Selling & Sales Mgmt', 'This course examines the use of personal selling within the context of the overall promotional effort of an organization, and how the sales function is managed to effectively achieve organizational objectives. Students will gain an understanding of how sales people create value for their customers and organizations, and how sales managers organize, recruit, select, motivate, and control the sales function. Prerequisite(s): BUSI 2433 with a minimum grade of C-.', 'BUSI', 3, 0, 4, '[{"codes":["BUSI-2433","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7232', 'BUSI-4423', 'Advertising & Promotion Mgmt', 'This course encompasses the set of strategic decisions on the kinds of information needed for effective communication targeting, the development and use of creative strategies, on appropriate media scheduling, and on ways to measure the effects of the integrated marketing communications programs. Practitioner-oriented, it also examines other components of the communications mix including consumer sales and trade promotions, public relations, publicity and corporate sponsorship. Prerequisite(s): BUSI 2433 with a minimum grade of C-.', 'BUSI', 3, 0, 4, '[{"codes":["BUSI-2433","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7233', 'BUSI-4433', 'Digital Marketing', 'This course builds on BUSI 2423 and BUSI 2433 as it applies and adapts traditional marketing strategy and actions to a digital context, examining the integration of digital marketing as a vital component of overall marketing strategy. Students will learn to evaluate website effectiveness, use search engines efficiently, create effectual social media strategies, and the basics of viral marketing. Prerequisite(s): BUSI 2433 with a minimum grade of C-.', 'BUSI', 3, 0, 4, '[{"codes":["BUSI-2433","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7235', 'BUSI-4483', 'Strategic Brand Management', 'This course is designed to introduce advanced concepts in branding and brand management to students concentrating in or with a keen interest in marketing. The course will cover the concepts, tools and techniques that are applied to successfully develop new brands and manage established brands. The course will involve lectures, case assignments and a comprehensive project. Prerequisite(s): BUSI 2433 with a minimum grade of C-.', 'BUSI', 3, 0, 4, '[{"codes":["BUSI-2433","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7236', 'BUSI-4543', 'Customer Management', 'This course builds on BUSI 2423 and 2433 in that it furthers the student''s understanding of the importance of dynamic customer management. The course discusses current theory and practice in customer management such as customer relationship management (CRM), direct marketing, database management and marketing, and campaign management. Prerequisite(s): BUSI 2433 with a minimum grade of C-.', 'BUSI', 3, 0, 4, '[{"codes":["BUSI-2433","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7237', 'BUSI-4553', 'Venture Creation 1', 'Beginning with a hypothesized customer need and a proposed solution, students design experiments to discover whether the concept represents a potentially sound business idea. Lean Startup and customer development methodologies are applied as low-risk means of determining whether they have found a problem worth solving, and whether to proceed with the design and development of the proposed solution.', 'BUSI', 3, 0, 4, '[{"codes":["BUSI-2773","or","permission","of","instructor."],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7238', 'BUSI-4563', 'Venture Creation 2', 'Students begin with a known customer need and a proposed solution, representing a potentially sound business idea. Students iterate through the Lean Startup build-measure-learn cycle by combining design thinking and rapid prototyping with qualitative and quantitative research methods to develop and test their minimum viable product with potential customers and establish product-market fit.', 'BUSI', 3, 0, 4, '[{"codes":["BUSI-4553","or","permission","of","the","instructor",""],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7239', 'BUSI-4613', 'Small Business Management', 'This course is a topical seminar that introduces the context, theory, and practice of small business management. Prerequisite(s): Third or fourth year students.', 'BUSI', 3, 0, 4, '[{"codes":["3rd-year","standing","(55h","or","more","completed)"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7240', 'BUSI-4623', 'Advanced Business Law', 'An expansion of BUSI 3613 and 3623 into such topics as E-business government regulation of business, trade secrets, computer law, intellectual property, corporate law. Prerequisite(s): BUSI 3623.', 'BUSI', 3, 0, 4, '[{"codes":["BUSI-3623"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7241', 'BUSI-4633', 'Ethics, Morality & Soci. Res.', 'The course examines the challenges of ethical decision making, moral cultivation, and social responsibility in a variety of organizational and industry contexts. Decisions made and actions taken by people in everyday organizational life can have significant ethical implications for broader society. Course materials will explore the complex relationships among corporate social responsibility, individual pursuit of moral cultivation, and broader societal wellbeing. Prerequisite(s): Third-year standing or higher.', 'BUSI', 3, 0, 4, '[{"codes":["3rd-year","standing","(55h","or","more","completed)"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7243', 'BUSI-4653', 'Strategic Business Development', 'This course provides students with the opportunity to practice the design, implementation, and control of business development strategies. It is an operationally oriented course in which the application of business concepts, principles, and methods is important. Students will work in teams and use a computer simulation. Prerequisite(s): BUSI 2433 with a minimum grade of C-.', 'BUSI', 3, 0, 4, '[{"codes":["BUSI-2433","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7244', 'BUSI-4663', 'Project Management', 'This course provides students with an introduction to the concepts, principles and techniques for the practice of project management. The material discusses the key processes, including initiating, executing, monitoring and controlling of the personnel and resources, to accomplish specific project goals, from both technical and behavioural perspectives. Other topics include project scope and time management, cost, quality and risk management. Prerequisite(s): BUSI 2513, BUSI 2233 with a minimum grade of C-.', 'BUSI', 3, 0, 4, '[{"codes":["BUSI-2513","and","BUSI-2233","with","a","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7246', 'BUSI-4773', 'Social Entrepreneurship', 'This course explores the practices of social entrepreneurship and social innovation. A primary focus is the development of new products, services, and organizations that can address complex social and/or environmental problems. Students are introduced to key theories, concepts and issues related to the startup and sustainability of social ventures. Prerequisite(s): BUSI 2773, or permission of the instructor.', 'BUSI', 3, 0, 4, '[{"codes":["BUSI-2773","or","permission","of","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7247', 'BUSI-4883', 'Decision Support Systems', 'The decision-making process and the information needed to support decision making. Discussions and cases centre on the organization environment, communications, quantitative techniques required for successful decision support systems. Prerequisite(s): BUSI 2803. Open only to fourth year students.', 'BUSI', 3, 0, 4, '[{"codes":["BUSI-2803"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["4th-year","standing","(85h","or","more","completed)"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7249', 'BUSI-4893', 'Digital Transformation', 'In today''s economy, information technology has become a driving force that enables gradual changes as well as paradigm shifts. This course offers an in-depth look at digital transformation and disruption. It helps develop the understanding of how digital transformation unfolds and delves into critical issues such as the innovation life cycle, work redesign, and IT governance, compliance, and ethics. Prerequisite(s): BUSI 2803 and third-year standing or higher.', 'BUSI', 3, 0, 4, '[{"codes":["BUSI-2803"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["3rd-year","standing","(55h","or","more","completed)"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7251', 'BUSI-4913', 'Independent Study in Business', 'Independent study of a topic not covered in the regular curriculum. A major paper or project is produced under the supervision of a faculty advisor. Prerequisite(s): Fourth-year standing or higher or permission of the Department.', 'BUSI', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7252', 'BUSI-4923', 'Special Topics 2', 'Special projects or topics not covered in the regular curriculum. Visiting instructors or Acadia faculty members may present specific subjects. Prerequisite(s): Fourth-year standing or higher, or permission of the instructor.', 'BUSI', 3, 0, 4, '[{"codes":["4th-year","standing","(85h","or","more","completed)"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7253', 'BUSI-4933', 'Projects in Business 1', 'A project performed under the direction of a faculty member. Note: Students should apply to the school several months before the start of the course. Prerequisite(s): Permission of the Director of the School.', 'BUSI', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7254', 'BUSI-4943', 'Projects in Business 2', 'A project performed under the direction of a faculty member. Note: Students should apply to the school several months before the start of the course. Prerequisite(s): Permission of the Director of the School.', 'BUSI', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7256', 'BUSI-4953', 'Busi & Corporate Strategy', 'This course establishes a foundation in the area of strategy formulation, implementation and analysis. Students learn from visiting business executives, undertake industry analyses, construct industry value chains, examine mergers and acquisitions, conduct SWOT and scenario analyses, search out new disruptive technologies and use other analytical approaches while profiling the formal strategies of major public companies. (2h Studio) Prerequisite(s): BUSI 2743, BUSI 2233, BUSI 2433, and BUSI 2513 each with a minimum grade of C-.', 'BUSI', 3, 0, 4, '[{"codes":["BUSI-2743,","BUSI-2233,","BUSI-2433,","and","BUSI-2513","each","with","a","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7257', 'BUSI-4963', 'Strategic Issues in Business', 'Increasingly, business managers must address concerns of constituents beyond traditional business borders. Through the examination of some of the most important and complex issues facing today''s management, students will gain an understanding of strategic fit between business strategies and the external environment. Prerequisite(s): BUSI 2743, BUSI 2233, BUSI 2433, and BUSI 2513 each with a minimum grade of C-, and BUSI 4953 as either a prerequisite or corequisite.', 'BUSI', 3, 0, 4, '[{"codes":["BUSI-2743,","BUSI-2233,","BUSI-2433,","and","BUSI-2513","each","with","a","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["BUSI-4953"],"textExtension":"- Must be taken either prior to or at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7259', 'CHAP-5023', 'Introduction to Chaplaincy', 'An overview of the profession of chaplaincy, exploring the diversity that exists in this ministry. A variety of specialists will be involved in the course instruction through discipline-specific didactics, including prison chaplains, airport chaplains, military chaplains, university chaplains, and chaplains who are involved in the business, sport, and healthcare sectors. Students will be introduced to organizational and vocational aspects of these specialized ministerial settings. In addition, students will begin developing theological understandings of the chaplain''s unique call and will begin to develop a personal theology of care. Pastoral interventions will also be taught and competence developed in the areas of crisis response, stress management, dealing with loss, death, and dying. There will also be the opportunity for self-examination, where one might consider interpersonal and intrapersonal dynamics that influence one''s own relationships and faith development. Cross-listed as PACC 5023.', 'CHAP', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7260', 'CHAP-5033', 'Intro to Prison Ministry', 'This course considers the specialized form of ministry with persons who are incarcerated. Areas considered will include the following: an historical view of corrections, the social structure of prisons, prison violence, understanding the effect of guilt, grief, and shame in the prisoner''s life, worship, approaches to pastoral counselling, the development of chaplaincy programs, and restorative justice. Cross-listed as PACC 5033.', 'CHAP', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7261', 'CHAP-6013', 'Professional & Personal Ethics', 'This course explores the ethical foundations essential for counselors and caring leaders, focusing on critical issues like consent, confidentiality, boundaries, self-care, and cultural sensitivity. Students will engage in a structured ethical decision-making process to navigate complex scenarios thoughtfully and critically. Through reflective practice, participants will develop strategies for maintaining healthy personal and professional boundaries. Additionally, the course examines professional standards and legal responsibilities, equipping students to integrate ethical principles into their leadership or counseling contexts. By the end, students will have the tools to approach ethical challenges with confidence, integrity, and respect for diverse cultural and professional expectations. Cross-listed as PACC 6013.', 'CHAP', 3, 0, 6, '[{"codes":["PACC-5013","and","PACC-5043"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7262', 'CHAP-7016', 'Clinical Pastoral Education 1', 'Students complete Basic Unit 1 of Clinical Pastoral Education (comprising 400 hours of supervised chaplaincy experience and instruction) within an approved setting. To register for this course students must apply, and be accepted by, an approved clinical training site. Recommended prior study: CHAP 5023, 6013. Prerequisite: Successful application to Canadian Association of Spiritual Care process required.', 'CHAP', 6, 0, 7, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7264', 'CHAP-7026', 'Clinical Pastoral Education 2', 'Students complete Basic Unit 2 of Clinical Pastoral Education (comprising 400 hours of supervised chaplaincy experience and instruction) within an approved setting. To register for this course students must apply, and be accepted by, an approved clinical training site. Prerequisite: CHAP 7016 and successful application to Canadian Association of Spiritual Care process required.', 'CHAP', 6, 0, 7, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7266', 'CHAP-7103', 'Prison Ministry Practicum 1', 'Students complete 120 hours comprising mentored prison chaplaincy experience in an approved setting, and required reading and reflection. Open only to students admitted to the Master of Divinity in Prison Chaplaincy or the Master of Arts (Theology) in Prison Chaplaincy. Recommended prior study: CHAP 5023, 5033, 6013.', 'CHAP', 3, 0, 7, '[{"codes":["CHAP-5023,","CHAP-5033","and","CHAP-6013"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7267', 'CHAP-7113', 'Prison Ministry Practicum 2', 'Students complete 120 hours comprising mentored prison chaplaincy experience in an approved setting, and required reading and reflection. Open only to students admitted to the Master of Divinity in Prison Chaplaincy or the Master of Arts (Theology) in Prison Chaplaincy. Prerequisite: CHAP 7103.', 'CHAP', 3, 0, 7, '[{"codes":["CHAP-7103"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7268', 'CHAP-7213', 'Special Topics in Chaplaincy 1', 'Specialized courses in Chaplaincy offered from time to time.', 'CHAP', 3, 0, 7, '[]');
