INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7280', 'CHAP-7343', 'Directed Study 4', '', 'CHAP', 3, 0, 7, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7281', 'CHAP-7916', 'Thesis 1', '', 'CHAP', 6, 0, 7, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7282', 'CHAP-7926', 'Thesis 2', '', 'CHAP', 6, 0, 7, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7283', 'CHEM-0110', 'Pre-University Chemistry', 'Topics from the NS high school chemistry curriculum (Chemistry 11 and Chemistry 12). This course is designed for students who have never taken high school chemistry or who would like to refresh their high school chemistry knowledge. This non-credit course serves as a prerequisite for courses that require NS Chemistry 11 and 12 or their equivalent.', 'CHEM', 0, 0, 0, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7285', 'CHEM-1010L', 'CHEM 1013 Laboratory', '', 'CHEM', 0, 1, 1, '[{"codes":["CHEM-1013"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7286', 'CHEM-1013', 'General Chemistry 1', 'An introduction to the fundamental principles of chemistry, including atomic and molecular structure, periodic properties, chemical bonding, stoichiometry, energy changes in reactions, and the foundations of acids, bases, and organic chemistry. Designed to build core concepts for further study in chemistry and related sciences. (3h lab). Prerequisite(s): NS 12 chemistry or equivalent with minimum grade of 60% or permission of the Department. Credit for laboratory component cannot be transferred to other Acadia courses with the exception of CHEM 1113. Antirequisite(s): Credit can be obtained for only one of CHEM 1033, CHEM 1013, or CHEM 1113.', 'CHEM', 3, 0, 1, '[{"codes":["CHEM-1010L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7287', 'CHEM-1020L', 'CHEM 1023 Laboratory', '', 'CHEM', 0, 1, 1, '[{"codes":["CHEM-1023"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7288', 'CHEM-1023', 'General Chemistry 2', 'A continuation of introductory chemistry, exploring the behaviour of matter in different states, reaction kinetics and equilibria, thermodynamics, electrochemistry, and additional topics in acids, bases, and organic chemistry. Emphasizes the application of chemical principles to physical, life, and environmental systems. (3h lab). Credit for laboratory component cannot be transferred to other Acadia courses with the exception of CHEM 1123. Antirequisite(s): Credit can be obtained for only one of CHEM 1043, CHEM 1023, or CHEM 1123.', 'CHEM', 3, 0, 1, '[{"codes":["CHEM-1013"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["CHEM-1020L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7290', 'CHEM-1033', 'Introductory Chemistry 1', 'Basic concepts in chemistry including stoichiometry, periodic trends and bonding. This course is offered through Open Acadia. The laboratory work consists of video- and computer-based assignments. This course may only be used as a prerequisite for admission to other chemistry courses with the permission of the Department. Prerequisite(s): NS 12 chemistry or equivalent with a minimum grade of 60% or permission of the Department. Antirequisite(s): Credit can be obtained for only one of CHEM 1033, CHEM 1013, or CHEM 1113.', 'CHEM', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7291', 'CHEM-1043', 'Introductory Chemistry 2', 'Basic concepts in chemistry, including properties of gases, liquids, solids and solutions as well as acids and bases. This course is offered through Open Acadia. The laboratory work consists of video- and computer-based assignments. This course may only be used as a prerequisite for admission to other chemistry courses with the permission of the Department. Prerequisite(s): CHEM 1033, CHEM 1013, or CHEM 1113. Antirequisite(s): Credit can be obtained for only one of CHEM 1043, CHEM 1023, or CHEM 1123.', 'CHEM', 3, 0, 1, '[{"codes":["CHEM-1033,","CHEM-1013,","or","CHEM-1113"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7292', 'CHEM-1053', 'Chemistry and Our World', 'This course provides an insight into the roles chemicals play in our everyday world. We will look at the chemistry that underlies issues with toxins, food and nutrition, air and water pollution, climate change, drugs, plastics and agrichemicals. No prior experience in chemistry is necessary for this course. No prerequisites or corequisites.', 'CHEM', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7293', 'CHEM-1110L', 'CHEM 1113 Laboratory', '', 'CHEM', 0, 1, 1, '[{"codes":["CHEM-1113"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7294', 'CHEM-1113', 'Fundamental Chemistry 1', 'The course is designed for chemistry majors to build a strong foundation in chemistry. Topics may include the electronic structure and periodic properties of atoms, chemical bonds and molecular geometry, stoichiometry, enthalpy, acid/base equilibria, buffers, and organic chemistry. (3h lab). Prerequisite(s): NS 12 chemistry or equivalent with minimum grade of 60%, or permission of the Department. Antirequisite(s): Credit can be obtained for only one of CHEM 1033, CHEM 1013, or CHEM 1113.', 'CHEM', 3, 0, 1, '[{"codes":["CHEM-1110L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7295', 'CHEM-1120L', 'CHEM 1123 Laboratory', '', 'CHEM', 0, 1, 1, '[{"codes":["CHEM-1123"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7296', 'CHEM-1123', 'Fundamental Chemistry 2', 'The course is designed for chemistry majors to build a strong foundation in chemistry. Topics may include reaction kinetics, energy and thermochemistry, entropy and Gibbs energy, chemical equilibrium, electrochemistry, phase equilibrium, and properties of gases, liquids, solids and solutions. (3h lab). Antirequisite(s): Credit can beobtained for only one of CHEM 1043, CHEM 1023, or CHEM 1123.', 'CHEM', 3, 0, 1, '[{"codes":["CHEM-1113"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["CHEM-1120L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7299', 'CHEM-2100L', 'CHEM 2103 Laboratory', '', 'CHEM', 0, 1, 2, '[{"codes":["CHEM-2103"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7300', 'CHEM-2103', 'Chemical Thermodynamics', 'Principles and applications of chemical thermodynamics. Topics normally include the laws of thermodynamics, phase equilibrium, chemical equilibrium, properties of mixtures and Boltzmann distribution. (3h lab). Prerequisite(s): CHEM 1123 or CHEM 1023 with a minimum grade of C-, MATH 1023, and PHYS 1023 or PHYS 1063; MATH 2013 or MATH 2753 is highly recommended.', 'CHEM', 3, 0, 2, '[{"codes":["CHEM-1023","or","CHEM-1123","with","minimum","grade","C-","required,","MATH-1023,","PHYS-1023","or","PHYS-1063"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["CHEM-2100L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7304', 'CHEM-2300L', 'CHEM 2303 Laboratory', '', 'CHEM', 0, 1, 2, '[{"codes":["CHEM-2303"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7305', 'CHEM-2303', 'Inorganic Chemistry', 'An introduction to atomic structure and bonding in inorganic compounds, with the use of group theory and molecular symmetry, a brief introduction to the coordination chemistry of the transition metals and related topics. (3h lab). Prerequisite(s): CHEM 1123 or CHEM 1023, with a minimum grade of C-.', 'CHEM', 3, 0, 2, '[{"codes":["CHEM-1023","or","CHEM-1123","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["CHEM-2300L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7308', 'CHEM-2510L', 'CHEM 2513 Laboratory', '', 'CHEM', 0, 1, 2, '[{"codes":["CHEM-2513"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7309', 'CHEM-2513', 'Organic Chemistry 1', 'An introduction to organic chemistry covering structure, nomenclature and reactions of the main classes of organic compounds. (3h lab). Prerequisite(s): CHEM 1023 or 1123 with a minimum grade of C-.', 'CHEM', 3, 0, 2, '[{"codes":["CHEM-1023","or","CHEM-1123","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["CHEM-2510L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7311', 'CHEM-2530L', 'CHEM 2533 Laboratory', '', 'CHEM', 0, 1, 2, '[{"codes":["CHEM-2533"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7312', 'CHEM-2533', 'Organic Chemistry 2', 'A more detailed treatment of the chemistry of functional groups with special attention given to carbonyl compounds. The student will be presented with a rigorous discussion of stereochemistry. The student will be introduced to 1-3 step organic reactions in the lab. (3h lab). Prerequisite(s): CHEM 2513 with a minimum grade of C-.', 'CHEM', 3, 0, 2, '[{"codes":["CHEM-2513","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["CHEM-2530L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7314', 'CHEM-2710L', 'CHEM 2713 Laboratory', '', 'CHEM', 0, 1, 2, '[{"codes":["CHEM-2713"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7315', 'CHEM-2713', 'Biochemistry', 'An introduction to the major organic substances of living organisms, proteins, carbohydrates, lipids, and nucleic acids: structure, analysis and biochemical function. Activity and analysis of enzymes. (3h lab). Prerequisite(s): CHEM 2513 with a minimum grade of C-. Antirequisite(s): Credit can be obtained for only one of CHEM 2773 or CHEM 2713.', 'CHEM', 3, 0, 2, '[{"codes":["CHEM-2513","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["CHEM-2710L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7316', 'CHEM-2773', 'Biochemistry for Life Sciences', 'An introduction to the structure and function of major micromolecules (sugars, amino acids, lipids, nucleosides, nucleotides, vitamins, etc.) and macromolecules (carbohydrates, proteins, enzymes, nucleic acids, etc.) of living systems, food digestion and major pathways for harnessing energy from nutrients. Prerequisite(s): CHEM 2513 with a minimum grade of C-. Antirequisite(s): Credit can be obtained for only one of CHEM 2773 or CHEM 2713.', 'CHEM', 3, 0, 2, '[{"codes":["CHEM-2513","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7318', 'CHEM-2810L', 'CHEM 2813 Laboratory', '', 'CHEM', 0, 1, 2, '[{"codes":["CHEM-2813"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7319', 'CHEM-2813', 'Analyt. Chem 1: Clascl Methds', 'An introduction to chemical analysis: statistical data evaluation, gravimetry and titrimetry, basic UV-VIS spectrometry and introduction to chromatography. (3h lab). Prerequisite(s): CHEM 1023 or 1123 with a grade of C-. Antirequisite(s): Credit can be obtained for only one of CHEM 2813 or CHEM 2853.', 'CHEM', 3, 0, 2, '[{"codes":["CHEM-1023","or","CHEM-1123","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["CHEM-2810L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7322', 'CHEM-2850L', 'CHEM 2853 Laboratory', '', 'CHEM', 0, 1, 2, '[{"codes":["CHEM-2853"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7323', 'CHEM-2853', 'Environmental Analytical Chem', 'Introduction to chemical analysis with an emphasis on the chemistry of the environment. Examples studied will be taken from air, aquatic, and terrestrial sources. (3h lab). Prerequisite(s): CHEM 1023 or 1123 with a minimum grade of C-. Antirequisite(s): Credit can be obtained for only one of CHEM 2813 or CHEM 2853.', 'CHEM', 3, 0, 2, '[{"codes":["CHEM-1023","or","CHEM-1123","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["CHEM-2850L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7324', 'CHEM-3100L', 'CHEM 3103 Laboratory', '', 'CHEM', 0, 1, 3, '[{"codes":["CHEM-3103"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7325', 'CHEM-3103', 'Chemical Kinetics', 'Principles and applications of chemical kinetics. Topics normally include Maxwell distribution diffusion, viscosity, ionic conduction, reaction rates, reaction mechanisms, photochemistry, collision theory and catalysis. (3h lab). Prerequisite(s): CHEM 2103 with a minimum grade of C-.', 'CHEM', 3, 0, 3, '[{"codes":["CHEM-2103","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["CHEM-3100L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7327', 'CHEM-3113', 'Quantum Chemistry', 'Principles of theoretical chemistry. The fundamental concepts of quantum mechanics are developed and applied to chemical bonding and molecular spectroscopy. Basics of modern computational chemistry are introduced to study the geometry, energy and spectroscopy of molecules. This course is normally offered every other year. Prerequisite(s): MATH 1023.', 'CHEM', 3, 0, 3, '[{"codes":["MATH-1023"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7328', 'CHEM-3140L', 'CHEM 3143 Laboratory', '', 'CHEM', 0, 1, 3, '[{"codes":["CHEM-3143"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7329', 'CHEM-3143', 'Surface Chem for Life Sciences', 'Special topics on the practical aspects of physical chemistry relevant to biological and industrial applications. Emphasis is on colloid, interfacial and surface chemistry. (3h lab). Prerequisite(s): CHEM 2713 or CHEM 2773 with minimum grade of C-.', 'CHEM', 3, 0, 3, '[{"codes":["CHEM-2713","or","CHEM-2773","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["CHEM-3140L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7330', 'CHEM-3300L', 'CHEM 3303 Laboratory', '', 'CHEM', 0, 1, 3, '[{"codes":["CHEM-3303"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7331', 'CHEM-3303', 'Main Group Chemistry', 'A survey of the chemistry and bonding of the main group elements, including compounds with unusual bonding environments. Computational chemistry is introduced as a tool for understanding chemical bonding. (3h lab). Prerequisite(s): CHEM 2303, with minimum grade of C-.', 'CHEM', 3, 0, 3, '[{"codes":["CHEM-2303","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["CHEM-3300L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7332', 'CHEM-3310L', 'CHEM 3313 Laboratory', '', 'CHEM', 0, 1, 3, '[{"codes":["CHEM-3313"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7333', 'CHEM-3313', 'Transition Metal Chemistry', 'A survey of the chemistry and bonding of the transition metals, including organometallic chemistry and inorganic compounds of biological interest. (3h lab). Prerequisite(s): CHEM 2303 with minimum grade of C-.', 'CHEM', 3, 0, 3, '[{"codes":["CHEM-2303","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["CHEM-3310L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7335', 'CHEM-3510L', 'CHEM 3513 Laboratory', '', 'CHEM', 0, 1, 3, '[{"codes":["CHEM-3513"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7336', 'CHEM-3513', 'Intermediate Organic Chemistry', 'An intermediate course which will study the chemistry of organic functional groups not covered at the 2000 level. Special attention will be given to the use of sophisticated organic reactions for the synthesis of more complex molecules. Students will be introduced to organic reactions under inert and anhydrous atmosphere. (3h lab). Prerequisite(s): CHEM 2533, with a minimum grade of C-.', 'CHEM', 3, 0, 3, '[{"codes":["CHEM-2533","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["CHEM-3510L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7337', 'CHEM-3520L', 'CHEM 3523 Laboratory', '', 'CHEM', 0, 1, 3, '[{"codes":["CHEM-3523"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7338', 'CHEM-3523', 'Structure Determination', 'Investigation of molecular structure determination by modern methods. Special emphasis will be placed on nuclear magnetic resonance (NMR) spectroscopy, supplemented by mass spectrometry and IR spectroscopy for structure elucidation. X- ray crystallography is introduced. (3h lab) Prerequisite(s): CHEM 2303 or CHEM 2513, with minimum grade of C-.', 'CHEM', 3, 0, 3, '[{"codes":["CHEM-2303","or","CHEM-2513","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["CHEM-3520L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7342', 'CHEM-3720L', 'CHEM 3723 Laboratory', '', 'CHEM', 0, 1, 3, '[{"codes":["CHEM-3723"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7343', 'CHEM-3723', 'Metabolism', 'An introduction to intermediary metabolism and biochemical genetics. The major degradative and biosynthetic pathways of metabolism; energy changes and metabolic regulation; the molecular basis of genetic processes. (3h lab). Prerequisite(s): CHEM 2713 with a minimum grade of C-.', 'CHEM', 3, 0, 3, '[{"codes":["CHEM-2713","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["CHEM-3720L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7345', 'CHEM-3820L', 'CHEM 3823 Laboratory', '', 'CHEM', 0, 1, 3, '[{"codes":["CHEM-3823"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7346', 'CHEM-3823', 'Analytical Chem 2: Instr Met', 'Modern molecular and atomic spectrometry, gas and liquid chromatography. (3h lab). Prerequisite(s): CHEM 2813 or CHEM 2853, with a minimum grade of C-.', 'CHEM', 3, 0, 3, '[{"codes":["CHEM-2813","or","CHEM","2853","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["CHEM-3820L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7348', 'CHEM-3913', 'Research Project 1', 'A research project sponsored and approved by one or more faculty members of the department. The student must take an active role in planning and implementation, and submit a written report upon completion of the project. Seventy-two (72) hours of research activity, normally involving laboratory or field work, are required. This course is graded as pass or fail. Prerequisite(s): 18h lab-based chemistry courses with minimum grades of C-; requires permission of the Department, and the availability of a suitable research supervisor.', 'CHEM', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7349', 'CHEM-3923', 'Research Project 2', 'A research project sponsored and approved by one or more faculty members of the department. The student must take an active role in planning and implementation, and submit a written report upon completion of the project. Seventy-two (72) hours of research activity, normally involving laboratory or field work, are required. This course is graded as pass or fail. Prerequisite(s): CHEM 3913; requires permission of the Department, and the availability of a suitable research supervisor.', 'CHEM', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7355', 'CHEM-4123', 'Physical Chemistry 4', 'Introduction to spectroscopy and statistical thermodynamics. The factors determining the intensities and wavelengths of electronic, vibrational and rotational spectra are examined. This leads to the application of spectroscopy as a source of molecular and atomic parameters for use in calculations with statistical thermodynamics. Applications of statistical thermodynamics to selected chemical systems will conclude the course. Prerequisite(s): CHEM 3103 and CHEM 3113 each with a minimum grade of C-.', 'CHEM', 3, 0, 4, '[{"codes":["CHEM-3103","and","CHEM-3113","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7358', 'CHEM-4313', 'Advanced Transition Metal Chem', 'Topics of current interest in transition metal and organometallic chemistry are discussed. Emphasis will be on developing research areas in the scientific literature. Prerequisite(s): CHEM 3303 or CHEM 3313, with a minimum grade of C-.', 'CHEM', 3, 0, 4, '[{"codes":["CHEM-3303","or","CHEM-3313","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7360', 'CHEM-4323', 'Adv Characterization Techs.', 'A survey of characterization techniques commonly used in inorganic chemistry, including: multinuclear NMR spectroscopy, EPR spectroscopy, computational chemistry and X-ray crystallography. Prerequisite(s): CHEM 3523 with a minimum grade of C-.', 'CHEM', 3, 0, 4, '[{"codes":["CHEM-3523","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7362', 'CHEM-4513', 'Synthetic Organic Chemistry', 'The principles involved in the planning and execution of the synthesis of organic molecules. A consolidation of the procedures learned in CHEM 2513, CHEM 2533 and CHEM 3513 with other modern synthetic methods. Prerequisite(s): CHEM 3513 with a minimum grade of C-.', 'CHEM', 3, 0, 4, '[{"codes":["CHEM-3513","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7364', 'CHEM-4523', 'Struct./Dynamics: Organic Chem', 'Includes the description of bonding in organic molecules and the methods for determining, analyzing, and predicting molecular structure, as well as the study of the physical properties and chemical transformations of molecules. Included are the more important reaction mechanisms and the methods by which these are elucidated. Prerequisite(s): CHEM 3523 with a minimum grade of C-.', 'CHEM', 3, 0, 4, '[{"codes":["CHEM-3523","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7368', 'CHEM-4723', 'Topics in Biochemistry', 'Specific topics of current interest are discussed in some detail. Possible topics include DNA structure and function with an emphasis on topological implications, enzymology, protein structure/function analysis, and molecular genetics. Emphasis will be on current experimental techniques used in biochemistry. Prerequisite(s): CHEM 3723 with a minimum grade of C-.', 'CHEM', 3, 0, 4, '[{"codes":["CHEM-3723","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7369', 'CHEM-4733', 'Food Chemistry/Biochemistry', 'Chemistry of the major and minor constituents of food. Flavour and colour molecules, additives, contaminants, natural toxicants, and vitamins. Prerequisite(s): CHEM 2713 with a minimum grade of C-.', 'CHEM', 3, 0, 4, '[{"codes":["CHEM-2713","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7370', 'CHEM-4773', 'Natural Product Chemistry', 'Overview of natural products, biosynthesis of secondary metabolites, modern techniques for studying secondary metabolism and biosynthesis, biological reactions, chemical interactions between living organisms, and classes of bioactive compounds grouped according to building blocks and biogenesis. This course will complement the basic knowledge necessary to students in diverse fields (e.g., organic chemistry, agricultural chemistry, biochemistry, nutrition, and pharmacy). Prerequisite(s): CHEM 2713 or permission of instructor. Antirequisite(s): Credit can be obtained for only one of CHEM 4773 or BIOL 4773.', 'CHEM', 3, 0, 4, '[{"codes":["CHEM-2713","or","permission","of","instructor"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7372', 'CHEM-4803', 'Adv Chemical Instrumentation', 'Advanced analytical techniques are discussed. Topics may include advanced mass spectrometry, advanced chromatography, capillary electrophoresis, sample preparation, sampling methods, data acquisition, electroanalytical chemistry, spectrometry and surface analytical chemistry. Prerequisite(s): CHEM 3823 with a minimum grade of C-, or CHEM 2853 with a minimum grade of B-.', 'CHEM', 3, 0, 4, '[{"codes":["CHEM-3823","with","a","minimum","grade","C-,","or","CHEM-2853","with","a","minimum","grade","of","B-."],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7375', 'CHEM-4820L', 'CHEM 4823 Laboratory', '', 'CHEM', 0, 1, 4, '[{"codes":["CHEM-4823"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7376', 'CHEM-4823', 'Applied Environmental Chem', 'Applications of analytical chemistry in elucidating the chemistry of the natural environment with an emphasis on current environmental issues. The course will focus on the role of analytical chemistry in studying the chemical composition of the natural environment and the cycling of natural and anthropogenic chemicals. Prerequisite(s): CHEM 3823 with a minimum grade of C-.', 'CHEM', 3, 0, 4, '[{"codes":["CHEM-3823","with","minimum","grade","C-","required"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["CHEM-4820L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7377', 'CHEM-4830L', 'CHEM 4833 Laboratory', '', 'CHEM', 0, 1, 4, '[{"codes":["CHEM-4833"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7378', 'CHEM-4833', 'Instrument Design', 'The techniques required to use computers to read, store and analyze experimental data, as well as control experiments in real time, are introduced. Topics include a programming language, signal conditioning and processing, and several interfacing techniques. A major component of the course is a project involving interfacing a computer to an experiment. A rudimentary knowledge of computer programming is recommended. (6h lecture/lab) Prerequisite(s): PHYS 2203. Antirequisite(s): Credit can be obtained for only one of CHEM 4833 or PHYS 2213.', 'CHEM', 3, 0, 4, '[{"codes":["PHYS-2203"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["CHEM-4830L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7379', 'CHEM-4903', 'Advanced Chemistry Laboratory', 'A capstone laboratory course designed to integrate and augment the content of previous chemistry courses. This may include labs in organic, inorganic, physical, analytical chemistry, and biochemistry. Students will select and carry out a number of short projects which are developed by faculty members in the various areas of chemistry. Students will be evaluated on their development of experimental procedures based on the chemical literature, scientific record-keeping, and preparation of reports. (no lectures, 6h lab) Prerequisite(s): CHEM 3823, and fourth-year standing in Chemistry.', 'CHEM', 3, 0, 4, '[{"codes":["CHEM-3823"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["4th-year","standing","(85h","or","more","completed)"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7383', 'CHEM-5010', 'Research Seminars', 'Graduate students are required to attend all departmental seminars. This is a non-credit course required for all full-time graduate students in Chemistry.', 'CHEM', 0, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7384', 'CHEM-5013', 'Qualifying Exam', 'Oral presentation on a research topic that relates to the thesis sub-discipline. The oral presentation will be followed by an oral examination on the student''s general chemistry knowledge. Required course for the MSc degree in Chemistry that should be attempted during the first term of the program.', 'CHEM', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7385', 'CHEM-5023', 'Research Proposal', 'Oral defence of a written research proposal (using the format of an NSERC Discovery Grant) that should be attempted during the second term of the MSc program. Required course for the MSc degree in Chemistry.', 'CHEM', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7386', 'CHEM-5106', 'Advanced Physical Chemistry 1', 'Advanced topics in chemical kinetics and reaction dynamics.', 'CHEM', 6, 0, 5, '[]');
