INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7867', 'DISP-5013', 'Transformational Discipleship', 'This course explores discipleship as participation in the mission of God rather than mere program delivery or information transfer. Grounded in a biblical theology of discipleship and with critical engagement with contemporary cultural realities, the course examines how people learn and change across generations, cultures, and digital contexts. Students will critically evaluate congregational discipleship strategies and design lessons that foster spiritual maturity, vocational integration, and reproducible disciple-making. The course culminates in a theological and practical vision for lifelong discipleship that forms resilient, mission-shaped leaders.', 'DISP', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7868', 'DISP-6013', 'Faith Development Small Groups', 'Explores the place of small groups within the wider ministry of the church in nurturing Christian spiritual growth - both in the individual and in the community of faith. Provides a practical knowledge of small-group ministry with its benefits and challenges and of various models, approaches, and leadership training. Recommended prior study: DISP 5013.', 'DISP', 3, 0, 6, '[{"codes":["DISP-5013"],"textExtension":"- Recommended prior to taking this course, but is not required."}]');
