INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('7934', 'DMIN-8513', 'Directed Study 1', 'DMin students are given the opportunity to focus their degree program by designing and implementing specialty study courses. Such courses are offered at the student''s request, subject to the Director''s and the professor''s agreement. See the Doctor of Ministry Handbook for the regulations governing directed studies.', 'DMIN', 3, 0, 8, '[]');
