INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9423', 'HIST-4903', 'Historiography', '', 'HIST', 3, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9495', 'IDST-1103', 'Hypermedia Theory and Practice', 'In this course, students will be introduced to the history behind and the theories that underlie networked communication and hypertextual practice. Students can expect to study the history of the internet and its corollary technologies, theories of typography, colour, and image, and to employ what they learn in practical applications.', 'IDST', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9496', 'IDST-1106', 'Hypermedia in the Humanities', 'Students draw upon a variety of digital resources to create HTML projects incorporating many different media. In addition to classes taught by members of the Departments of English, History & Classics, and Philosophy, students will receive instruction in Information Literacy from Faculty Librarians, and instruction in the use of applicable software.', 'IDST', 6, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9497', 'IDST-1113', 'Peoples and Cultures of Asia 1', 'An introduction to Asia in the modern era from geopolitical, religious, historical, social and cultural perspectives. It seeks to understand the ways of thinking found in South, Southeast and East Asia, the basic role of tradition in society, and the current challenges that confront this half of the world. May be offered for major credit in History.', 'IDST', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9499', 'IDST-1123', 'Peoples and Cultures of Asia 2', 'An introduction to Asia in the modern era from geopolitical, religious, historical, social and cultural perspectives. It seeks to understand the ways of thinking found in South, Southeast and East Asia, the basic role of tradition in society, and the current challenges that confront this half of the world. May be offered for major credit in History.', 'IDST', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9500', 'IDST-1213', 'Africian Cdn. Exp:Past/Pres.', 'Spanning 400 years of the African presence in Canada, this course explores how African-descended peoples have resisted slavery and racial oppression, and the political, social, economic, gender, class and other factors that have influenced their experience. Through lectures, field trips and hands-on workshops, students learn how African Canadians have contributed to the building of this nation, and the global diaspora. Cross-coded with HIST 1913. Antirequisite(s): Credit can be obtained for only one of IDST 1213 or HIST 1913.', 'IDST', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9501', 'IDST-1223', 'Indigenous Exper:Past/Present', 'With the advisory participation of the Black-Indigenous Community Education Initiative (BICE), this course surveys the aboriginal experience across Canada from pre-contact to contemporary times. Special emphasis is placed on particular aspects of the experience of the Mi''kmaq and Maliseet First Nations.', 'IDST', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9507', 'IDST-1503', 'Popular Culture and You', 'A transdisciplinary team-taught course designed to encourage critical thinking about popular culture, society and the role of the individual, focusing on the representation of race, gender, and sexuality in the popular media of music, film, literature (including graphic novels) and video games. This course may be counted as a 3h elective credit in Music.', 'IDST', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9508', 'IDST-1513', 'Narrative/Play/Performance', 'A transdisciplinary team-taught course designed to recognize reading, gaming and acting as activities that can be used to construct, reflect, and interrogate our individual, communal and cultural selves. Students will read and reflect on written narratives, design and play through digital narratives and gamespaces, and explore the possibilities and consequences of role-playing and live performance. This course may be counted as a 3h elective credit in English or Recreation Management or Kinesiology.', 'IDST', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9509', 'IDST-1603', 'Human/Environmental Diversity', 'A transdisciplinary team-taught course designed to introduce students to the global, national and regional importance of interrelations between human and environmental diversity. Students will consider issues such as social and environmental justice, challenges to biodiversity and cultural diversity, practical options to preserve, deepen and expand human and environmental diversity, as involving a wide range of factors, from geography to genetics. This course may be counted as a 3h elective credit in Sociology or Biology.', 'IDST', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9510', 'IDST-1613', 'Perspectives on Climate Change', 'A transdisciplinary team-taught course designed to examine from the perspectives of science, economy, culture, and community, the dimensions of climate change as a global issue: its causes, potential impacts, ways to mitigate, and ways to adapt. Students will learn the science behind climate change, the economics of tackling it, and the potential for positive outcomes by managing it properly. This course may be counted as a 3h elective credit in Business or Geology.', 'IDST', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9511', 'IDST-1703', 'A Guided Tour of Our Universe', 'A transdisciplinary team-taught course designed to help students develop a scientific view of the universe as the place we live in. Students will study the night sky, evolution of scientific methods, influence of astronomy on popular culture, the precondition for life, the structure and fate of the universe, and examine its historical and fictive depiction in literature and popular media. This course may be counted as a 3h elective credit in Physics or Recreation Management or Kinesiology. Antirequisite(s): Credit can be obtained for only one of IDST 1703 or PHYS 1513.', 'IDST', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9512', 'IDST-1713', 'Motives & Ethics of War', 'A transdisciplinary team-taught course designed to engage students in an investigation of the motives and ethics of war from historical, biological, and psychological perspectives, using case studies to develop a template of the motives that lead to war and to formulate a set of ethical principles that should govern and prevent war. Sources range from ancient Greek epic to modern film documentaries. This course may be counted as a 3h elective or major credit in Classics or 3h elective credit in Biology.', 'IDST', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9516', 'IDST-2063', 'World Music', 'A survey of folk music from around the world involving basic analysis of musical sounds in their social context. Musical analysis will be conducted primarily on an aural basis. Previous knowledge of musical theory or practice is not required. May be offered for credit in Music.', 'IDST', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9520', 'IDST-2213', 'Peace Studies 1', 'These courses aim to give students a better general understanding of the dynamics of conflict and peace. They attempt to sensitize students to the different dimensions of conflict and peace, of their causes and effects, and of the obstacles and opportunities for meaningful change in the contemporary world. These courses may be taken for Political Science credit.', 'IDST', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9522', 'IDST-2223', 'Peace Studies 2', 'These courses aim to give students a better general understanding of the dynamics of conflict and peace. They attempt to sensitize students to the different dimensions of conflict and peace, of their causes and effects, and of the obstacles and opportunities for meaningful change in the contemporary world. These courses may be taken for Political Science credit.', 'IDST', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9523', 'IDST-2253', 'Organized Labour in Canada', 'A social history approach to the origins and development of the Canadian labour movement emphasizing the involvement of labour in social and political transformation. A primary focus is on the social history of organized labour in Nova Scotia. This course may be offered for major credit in sociology. Prerequisite(s): Second-year standing.', 'IDST', 3, 0, 2, '[{"codes":["2nd-year","standing","(25h","or","more","completed)"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9528', 'IDST-2423', '19th & 20th C World Lit', 'Realism, naturalism, and symbolism in prose fiction from 1850 to 1950.', 'IDST', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9530', 'IDST-2453', 'Epic Tradition 2', 'A study of how the epic tradition is deployed in support of and in the context of Reformation Christianity, the rise of national identities, and the rise of individualism. May be offered for major credit in English.', 'IDST', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9532', 'IDST-2503', 'Canadian Persp: Myths&Symbols', 'Focusing on the mythologization of Canada, we will critically examine symbols often used to represent and define the nation, such as hockey, the RCMP, and the maple leaf. Each week will be centred on a specific theme that will be explored in readings, class discussions, as well as visual and new media. May be offered for major credit in History.', 'IDST', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9534', 'IDST-2513', 'Perspectives on Canada 2', 'A multi-disciplinary course designed to introduce students to themes in Canadian culture and familiarize them with the methodologies of the humanities. The focus is on the Canadian identity and the many forms in which it has been expressed. May be offered for major credit in History.', 'IDST', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9538', 'IDST-2706', 'Interdisc Enterprise Project', 'This course provides students the opportunity to examine entrepreneurial behaviour from a theoretical and practical perspective through situated learning. Teams of students from a variety of disciplines will undertake a project requiring risk taking, creativity, decision-making/problem solving, team work, experiential learning and project evaluation. These experiences will be considered and reflected upon in relation to the theoretical underpinnings appropriate to the nature of the project. This course is administered by a committee comprised of faculty members from differing disciplines. Prerequisite(s): Permission of the committee.', 'IDST', 6, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9540', 'IDST-2813', 'Civilization in South Asia 1', 'The unique spiritual and cultural resources of India and their impact on South Asian history, philosophy, art and social structures from the Vedic period to the beginning of the Common Era. Specific attention is paid to the development of a traditional Indian world-view based on Hindu, Buddhist and Jain teachings. May be offered for major credit in History.', 'IDST', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9541', 'IDST-2823', 'Civilization in South Asia 2', 'The great flowering of Hindu Indian civilization associated with the first seven centuries of the Common Era was radically challenged with the introduction of Islam and the colonial era. Focus is on the Islamic contribution to Indian civilization, the impact of the British period and the formation of Pakistan, Sri Lanka and Bangladesh in post- colonial South Asia. May be offered for major credit in History.', 'IDST', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9550', 'IDST-3103', 'Environmental Law', 'An historical review of property law concepts and an examination of the legal principles associated with environmental law, including a review of the rights, obligations, claims, defences and remedies of conflicting environmental interests. May be offered for major credit in political science. Prerequisite(s): Third-year standing.', 'IDST', 3, 0, 3, '[{"codes":["3rd-year","standing","(55h","or","more","completed)"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9553', 'IDST-3123', 'Family Law', 'A study of the family in Canadian society from the legal perspective. Topics covered include children and the law, custodial issues, divorce and separation, family property, family violence, protection for the elderly, reproduction and the law, and an examination of the family court system and current trends in family law. May be offered for major credit in political science and sociology. Prerequisite(s): Third-year standing.', 'IDST', 3, 0, 3, '[{"codes":["3rd-year","standing","(55h","or","more","completed)"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9558', 'IDST-3213', 'Sustainable Nova Scotia', 'Through experiential learning, this course explores the global issues of sustainability through a local focus on Nova Scotia. Students and professors from across the university work together on local projects that address complex environmental, economic, social, and political issues. Students enroll in the discipline of their choice (within class size limit), and will be assigned to work on one project. Prerequisite(s): Third or fourth-year standing.', 'IDST', 3, 0, 3, '[{"codes":["3rd-year","standing","(55h","or","more","completed)"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9559', 'IDST-3463', 'Perspect on Fren/Germ/Span', '2024/25 - A multi-disciplinary course to offer students a basic knowledge of the post-1492 overseas expansion of major European languages. The course will be offered in English. Students wishing to have this course count towards a major degree in the Department of Languages and Literatures will be required to write summaries of readings in the language in which they major.', 'IDST', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9560', 'IDST-3473', 'Intro Contemp Frn/Grm/Spn Film', 'A multi-disciplinary course covering developments in French, German and Spanish film as well as the theories shaping them, with a focus on literary adaptations. The course will be offered in English. Students wishing to count this course towards a major in a language will be required to write their assignments and essays in the language of that major.', 'IDST', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9562', 'IDST-3613', 'Health/Wellness:Nova Scotia', 'Professors from across the campus lead students through analyses of the complex global issues of health and wellness, while drawing substantially on a local, multidisciplinary focus on the state of health and wellness of Nova Scotians. Lectures featuring professors and other regional experts are combined with small group projects focused on current health and wellness issues, to present the complex physical, social-psychological, spiritual, economic, educational, environmental and political issues associated with holistic health and wellness.', 'IDST', 3, 0, 3, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9567', 'IDST-4186', 'Peacekeeping: Critcl Perspect', 'This course examines all the elements of modern peacekeeping from consolidating security to ensuring good governance and promoting economic rehabilitation. It also looks at the major players involved on both the military and civilian sides including NGOs and presents a series of case studies of peacekeeping missions. May be offered for credit in Political Science.', 'IDST', 6, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9569', 'IDST-4996', 'Honours Thesis', 'Kinesiology', 'IDST', 6, 0, 4, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9572', 'IDST-5186', 'Peacekeeping: Critcl Perspect', 'This course examines all the elements of modern peacekeeping from consolidating security to ensuring good governance and promoting economic rehabilitation. It also looks at the major players involved on both the military and civilian sides including NGOs and presents a series of peacekeeping missions.', 'IDST', 6, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9588', 'IDTH-2010', 'Orientation', 'This non-credit, Pass/Fail course is part of the annual orientation to Acadia Divinity College (ADC) and is normally required for all entering students at ADC (not including students in program partnerships). It will orient students to ADC and to seminary-level research and writing. Through lectures, demonstrations, practice exercises, readings, testing, and an all-day retreat, students will be introduced to various expectations, skills, and resources necessary for advancing successfully through their degrees, and they will also begin their preliminary personal testing. A part of this course will be an all-day session which provides an overview of the Bible''s narration of events from Abraham to the early church.', 'IDTH', 0, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9589', 'IDTH-5010', 'Orientation', 'This non-credit, Pass/Fail course is part of the annual orientation to Acadia Divinity College (ADC) and is normally required for all entering students at ADC (not including students in program partnerships). It will orient students to ADC and to seminary-level research and writing. Through lectures, demonstrations, practice exercises, readings, testing, and an all-day retreat, students will be introduced to various expectations, skills, and resources necessary for advancing successfully through their degrees, and they will also begin their preliminary personal testing. A part of this course will be an all-day session which provides an overview of the Bible''s narration of events from Abraham to the early church.', 'IDTH', 0, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9591', 'IDTH-7813', 'MA (Theo) Graduate Seminar', 'A seminar course focused on research methodologies, advanced critical-thinking skills, and seminar presentation skills appropriate to graduate-level MA thesis work. Students will read in areas of general research skills, and in methodologies relevant to their individual specializations. During seminar sessions, students will present for engagement by student and faculty colleagues, their research findings from thesis research or research associated with upper-level courses. Prerequisites: Open only to Master of Arts (Theology) students who are in the last 30 hr of the degree.', 'IDTH', 3, 0, 7, '[{"codes":["30h","University","Credits"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9593', 'INCD-5513', 'Cultures and Systems Change', 'The experience of Christianity has been culturally devastating for Indigenous peoples. Through exploring the process of decolonization and indigenization, this course will examine how Indigenous people live a biblically-informed Christian faith in the context of Indigenous cultures. Jesus, as a change master in a complex cultural system, is the model for guiding effective and lasting change. This course utilizes perspectives and tools for interpreting and guiding a cultural system towards deep change. Insights from various disciplines, such as anthropology, social psychology, and organizational science, will stimulate the exegesis of culture in fresh ways.', 'INCD', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9594', 'INCD-5523', 'Theory & Praxis in Development', 'This course begins with a brief examination of historic relief and development theories, focusing in on a more careful examination of post WWII models and their evolution through the 1960s, 70s, and 80s toward the Transformational Development models of the 1990s and beyond. The continued emphasis on Modernization and Westernization in contemporary practice will create a frame around a discussion of alternate ideas for community health and well-being. The cost-benefit between asset- and deficit-based methodologies will emerge through the examination of the biblical and theological issues raised when applied to human systems and communities.', 'INCD', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9595', 'INCD-5533', 'Indigenous Leadership Dev', 'This seminar course will introduce students to concepts of leadership, organizational change theory, and skills required to lead organizations and communities in the context of the changing demographics. The emerging practice of diversity as central to leadership theory and practice, the holistic nature of diversity, social justice within a diverse society, and the role these have in contributing to effective and appropriate leadership will be explored to gain an informed understanding. Reflection on multicultural, and intercultural perspectives and partnerships, specifically, those between Indigenous Peoples and Western culture is a focal aspect of this course. Leaders require knowledge, skill and attributes that support inclusion and promote unity.', 'INCD', 3, 0, 5, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9596', 'INCD-6503', 'Asset-based Development', 'The course is an introduction to asset-based planning and design as a human and organizational capacity-building approach. ABCD seeks to locate, underscore, and emphasize, in a selective way, the life-giving forces and successes within an organization, group, or community. The course will focus on different ways of engaging life within communities and organizations, while exploring the skills of community development facilitation for practitioners. Several tools used in asset-based planning and development will be carefully examined with a view to creating proficiency in both their theory and practice.', 'INCD', 3, 0, 6, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9597', 'INCD-6513', 'Community Field Placement', 'The student will work in a community agency or non-profit organization as a field placement, selected jointly with their supervisor. This should be a setting focused on community transformative development where possible, from a primarily asset-framed perspective. The placement will be chosen so as to provide the optimum contributory learning experience. This 3-credit-hour course will take place over two semesters.', 'INCD', 3, 0, 6, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9598', 'INCD-6523', 'Family and Social Systems', 'Indigenous family contexts have changed dramatically over the course of the centuries, since contact. Family systems, including parenting, intergenerational roles and relationships, as well as governance and provision for need, have come under significant stress, as a result. Proposed remedies over the 20th and into the 21st centuries have attempted to accommodate what constituted traditional ways within often invasive new ways. This course examines the impact of cultural and social forces upon the family system including major systems theories, strategies, and techniques of engaging family and family relationship in the midst of shifting dynamics and demographics. Issues of family and inter-generational conflict as well as the ethical considerations of intervention are also examined.', 'INCD', 3, 0, 6, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9599', 'INCD-7213', 'ST:Indigenous Community Dev 1', 'Specialized courses in Indigenous Community Development offered from time to time.', 'INCD', 3, 0, 7, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9600', 'INCD-7223', 'ST:Indigenous Community Dev 2', 'Specialized courses in Indigenous Community Development offered from time to time.', 'INCD', 3, 0, 7, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9601', 'INCD-7233', 'ST:Indigenous Community Dev 3', 'Specialized courses in Indigenous Community Development offered from time to time.', 'INCD', 3, 0, 7, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9603', 'INCD-7603', 'Directed Study', 'This course provides students with an opportunity to pursue an interest in a particular topic related to Indigenous peoples. The goal is to expand the student''s depth and breadth of knowledge in a specific area, including Indigenous History, Indigenous Philosophy, or Indigenous Religious Contexts.', 'INCD', 3, 0, 7, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9604', 'INCD-7613', 'Cultural Anthropology', 'In this course, participants explore together a variety of historical anthropological theories. Trajectories in the study of anthropology have been helpful and hurtful, particularly to Indigenous people globally. The course will explore anthropology as a discipline, and invite other worldviews to contribute to the shaping of anthropological theory and practice for Indigenous and non-Indigenous people.', 'INCD', 3, 0, 7, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9605', 'INCD-7623', 'Colonization & Decolonization', 'This course will consider the critiques made by Indigenous and postcolonial scholars of the methodological approaches used in the humanities and social sciences for their complicity in colonialism. It will examine various attempts to "decolonize" methodology and to construct Indigenous and postcolonial methodological approaches to society and community. Students will work to develop their own philosophical and methodological approaches to decolonization.', 'INCD', 3, 0, 7, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9606', 'INCD-7633', 'Studies in a Holistic Gospel', 'The course will explore how the body and soul dualism, out of which much Christian mission operated in the past (i.e. saving souls only), has proved inadequate and damaging to many First Nations, Inuit, and Metis peoples in Canada. In this course, participants will explore and participate in developments in Christian missiology, in order to provide a more robust understanding of the nature of the gospel.', 'INCD', 3, 0, 7, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9607', 'INCD-7663', 'Social Construction Identity', 'This course examines critically the social construction of ethnicity and identity within First Nations, Inuit, and Metis communities, as well as the implications for broader community social responses to those identities. Students will study the myths and realities surrounding the development of racial, ethnic, and cultural categories in North America and learn how social, political, and economic forces have shaped the experiences of different ethnic groups. Students will also be introduced to the concepts of socialization, social interaction, identity formation and self-fashioning; the social construction of class, gender and race, age, and deviance; and other social phenomena.', 'INCD', 3, 0, 7, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9608', 'INCD-7723', 'Indigenous Spirituality & Form', 'Indigenous understandings of the nature of the spiritual and of spirituality differ in many respects from those commonly held within Western traditions of Christian faith. The focus of the course, therefore, is to introduce the student to the ways in which Indigenous people participate as followers of Jesus in a manner that is authentic to their own cultural understandings, seeking to encourage spiritual growth and development from within such an Indigenous framework. This course will also discuss the appropriation of what has been perceived to be Indigenous spirituality by non-Indigenous people as well as a brief focus on what can be effectively learned from Indigenous understandings of the spiritual.', 'INCD', 3, 0, 7, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9609', 'INCD-7733', 'Indigenous Prac Andragogy', 'Andragogy is the study of methods, epistemologies, philosophies and contextual understandings of education that pertain to and enhance an adult-focused learning environment. This course will introduce the student to andragogical method as a theological framework and a contextual teaching practice, exploring the theological, philosophical, and pragmatic underpinnings of teaching. The course will also introduce the student to a variety of strategies to advance their development as a teacher.', 'INCD', 3, 0, 7, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9610', 'INCD-7813', 'Indigenous Research/Writing', 'This course covers all aspects of research and writing at an academic level. The student develops their voice as an academic writer by learning how to identify and use rhetorical strategies in writing. The course will also explore the specific needs or concerns of Indigenous writing and research methods including protocol. Other topics covered are: proper citation and bibliography formatting, grammar, crafting solid thesis statements, building a line of reasoning and other organizational strategies of formal research papers, finding and interacting with quality secondary sources and how to synthesize and interact with secondary sources in an academic essay.', 'INCD', 3, 0, 7, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9611', 'INCD-7823', 'Indigenous Symposium Seminars', 'In order to foster deeper relationship, more effective academic engagement, and an overall greater involvement within the NAIITS community, students are required to attend two symposia as they progress through their studies. They will be required to participate in the concurrent seminar, and complete required assignments. Students will only register for the course at the time of their second Symposium following which, grades assigned to first and second Symposium work will be recorded.', 'INCD', 3, 0, 7, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9612', 'INCD-7913', 'Project Indigenous Comm Devel', '', 'INCD', 3, 0, 7, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9613', 'INCD-7916', 'Thesis 1', '', 'INCD', 6, 0, 7, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9614', 'INCD-7923', 'Project Indigenous Comm Devel', '', 'INCD', 3, 0, 7, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9615', 'INCD-7926', 'Thesis 2', '', 'INCD', 6, 0, 7, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9687', 'KINE-1013', 'Foundations', 'This course is designed to provide students with an understanding of the depth and breadth of the field of Kinesiology and its sub-disciplines, and provides foundational knowledge of kinesiology, sport and physical activity. Prerequisite(s): BKIN students only.', 'KINE', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9690', 'KINE-1100', 'First Aid and CPR', 'Intermediate CSA First Aid CPR AED Level C or an approved equivalent must be completed prior to the second year of study. Students must provide a copy of the valid certification to the school by April of their first year in the program. Prerequisite(s): BKIN Students Only.', 'KINE', 0, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9691', 'KINE-1113', 'Rsrch Meth. in Kinesiology', 'An overview of the role of research, various research themes and methodologies in kinesiology. Various applications of research findings will be examined. Prerequisite(s): BKIN Students Only, KINE 1013.', 'KINE', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9693', 'KINE-1210L', 'KINE 1213 Laboratory', '', 'KINE', 0, 1, 1, '[{"codes":["KINE-1213"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9694', 'KINE-1213', 'Growth and Motor Development', 'A study of the sequential changes and characteristics of physical growth and motor development related to physical activity. Attention will focus on sequential motor patterns, individual differences across the lifespan; factors affecting and measurement of physical growth and motor development. (1.5h lab).  Prerequisite(s): BKIN Students Only.', 'KINE', 3, 0, 1, '[{"codes":["KINE-1210L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9695', 'KINE-1243', 'Histor. Asp. Phys Act & Sport', 'An examination of the place of physical activity and sport in Canadian history. Prerequisite(s): BKIN Students Only, and KINE 1013.', 'KINE', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9698', 'KINE-1330L', 'KINE 1333 Laboratory', '', 'KINE', 0, 1, 1, '[{"codes":["KINE-1333"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9699', 'KINE-1333', 'Care/Prev of Athletic Injuries', 'An introduction to the prevention and recognition of injuries from accidents in athletic activities. Analysis of the incidence of these athletic injuries, assessment techniques, support methods and medicolegal implications are discussed. Laboratory work includes the injury evaluation procedures, basic taping and therapy methods. (1.5h lab biweekly) Prerequisite(s): BKIN students only, KINE 1413; Antirequisite(s): Credit can be obtained for only one of KINE 1333 or KINE 2023.', 'KINE', 3, 0, 1, '[{"codes":["BKIN","students","only,","and","KINE","1413"],"textExtension":"- Must be completed prior to taking this course."},{"codes":["KINE-1330L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9700', 'KINE-1410L', 'KINE 1413 Laboratory', '', 'KINE', 0, 1, 1, '[{"codes":["KINE-1413"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9701', 'KINE-1413', 'Human Anatomy 1', 'This course examines the structures of the human body from cell to systems, with a particular emphasis on those responsible for movement. The musculoskeletal structures, including bones, joints and muscles are emphasized. The nervous, cardiovascular and respiratory systems are also introduced.  Prerequisite(s): BKIN students only.', 'KINE', 3, 0, 1, '[{"codes":["KINE-1410L"],"textExtension":"- Must be taken at the same time as this course."}]');
