INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9742', 'KINE-190C', 'Ag, Quick, & Speed Ad Act Crse', 'To develop advanced technical and practical skill levels and the theoretical knowledge for coaching the sport or activity. Students require the appropriate introductory activity course as a prerequisite to the advanced activity course. Prerequisite(s): BKIN/BKIH Students Only, second-year standing.', 'KINE', 1.5, 0, 1, '[{"codes":["2nd-year","standing","(25h","or","more","completed)"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9743', 'KINE-1993', 'Physically Active Living', 'An introductory level course covering basic concepts related to exercise, fitness, and health. Will include exercise myths, risks, benefits and choices as related to physically active lifestyles and the development of personal wellness. This course cannot be counted as credit toward the BKIN degree. Antirequisite(s): Credit can be obtained for only one of KINE 1993 or KINE 2293.', 'KINE', 3, 0, 1, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9744', 'KINE-2003', 'Adapted Physical Activity', 'Students will gain an understanding of theory and practice in the field of adapted physical activity. Students will develop skills to design, implement, and evaluate physical activity participation for individuals of varying ages and abilities across physical activity environments. Practicum in the S.M.I.L.E program is required. Prerequisite(s): BKIN students only, second-year standing.', 'KINE', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9750', 'KINE-2030L', 'KINE 2033 Laboratory', '', 'KINE', 0, 1, 2, '[{"codes":["KINE-2033"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9751', 'KINE-2033', 'Biomechanics 1', 'An introduction to the biomechanics of human movement, including kinematics and kinetics of the musculoskeletal system and mechanics of muscle contraction. Practical examples from sport, rehabilitation and the workplace will be discussed. The lab component will demonstrate these concepts and introduce methods used to quantify the mechanical aspect of human motion. (3h lab). Prerequisite(s): BKIN Students Only, KINE 1213 and KINE 1413.', 'KINE', 3, 0, 2, '[{"codes":["BKIN","Students","Only,","KINE","1213","and","KINE","1413."],"textExtension":"- Must be completed prior to taking this course."},{"codes":["KINE-2030L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9754', 'KINE-2133', 'Coaching', 'An examination of the principles of coaching as they relate to the overall development of the athlete. Course content is taken directly from the NCCP Introduction to Competition manuals, although the breadth of material covered will surpass the expectations set by the NCCP. Prerequisite(s): BKIN/BKIH Students Only, min. second-year standing', 'KINE', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9757', 'KINE-2253', 'Soc. Asp. Health & Moving Body', 'This course is designed to provide a sound introduction to the sociological study of health, the moving body and physical activity.  Students are encouraged to identify and think critically about how health is shaped by broader socio-cultural and political forces and conceptualize the physically active body as a biological, social, and cultural entity.', 'KINE', 3, 0, 2, '[{"codes":["BKIN","students","only,","2nd-year","standing"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9763', 'KINE-2410L', 'KINE 2413 Laboratory', '', 'KINE', 0, 1, 2, '[{"codes":["KINE-2413"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9764', 'KINE-2413', 'Applied Human Physiology 1', 'An introduction to human physiology for kinesiology students. This course covers basic physiological concepts including cell physiology and focuses primarily on neuromuscular physiology, with an introduction to metabolism, gastrointestinal, integument, and endocrine physiology. Homeostasis and sensory control of movement are explored. Anatomical and physiological changes over the lifespan will be introduced. The focus of the physiology courses is on physical activity and the implications to health and wellbeing. (1.5h lab)  Prerequisite(s): BKIN/BKIH Students only, KINE 1100, KINE 1413 and BIOL 1863. Antirequisite(s): Credit can be obtained for only one of KINE 2413 or BIOL 2813.', 'KINE', 3, 0, 2, '[{"codes":["BKIN/BKIH","Students","only,","KINE","1100,","KINE","1413","and","BIOL","1863."],"textExtension":"- Must be completed prior to taking this course."},{"codes":["KINE-2410L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9765', 'KINE-2420L', 'KINE 2423 Laboratory', '', 'KINE', 0, 1, 2, '[{"codes":["KINE-2423"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9766', 'KINE-2423', 'Applied Human Physiology 2', 'An introduction to human physiology for kinesiology students. This course covers primarily cardiovascular and respiratory physiology with introduction to support systems (acid-base regulation, renal, gastrointestinal, immune and reproductive systems). Anatomical and physiological changes over the lifespan will also be covered. (1.5h lab).  Prerequisite(s): BKIN Students Only, KINE 2413. Antirequisite(s): Credit can be obtained for only one of KINE 2423 or BIOL 2823.', 'KINE', 3, 0, 2, '[{"codes":["BKIN","Students","Only,","KINE","2413."],"textExtension":"- Must be completed prior to taking this course."},{"codes":["KINE-2420L"],"textExtension":"- Must be taken at the same time as this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9767', 'KINE-2433', 'Psych. Asp. Phys Act/Sprt', 'An examination of the primary psychological aspects important in understanding physical activity participation and sport performance. This course will focus on the role of theory in effectively promoting physical activity and exercise. The course will examine psychological factors that affect and are affected by participation in physical activity and sport, social influences on participation, as well as psychological techniques to enhance participation. Prerequisite(s): BKIN Students Only, KINE 1013, and second-year standing.', 'KINE', 3, 0, 2, '[{"codes":["2nd-year","standing","(25h","or","more","completed)"],"textExtension":"- Must be completed prior to taking this course."}]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9769', 'KINE-2493', 'Health Promotion and Wellness', 'Students will be exposed to a wide range of health and wellness issues. Students will examine their attitudes toward these issues with an emphasis on self-responsibility, and will be prepared to design and implement health promotion programs. Prerequisites: BKIN majors and BSN (NUTR) majors only; second-year standing.', 'KINE', 3, 0, 2, '[]');
INSERT INTO "courses" ("id", "code", "title", "description", "departmentPrefix", "credits", "isLab", "academicLevel", "requisites") VALUES ('9772', 'KINE-276D', 'Outdoor Leader 2', 'Prerequisite(s): BKIN/BKIH and BCD/BCDH Students Only, second year standing.', 'KINE', 1.5, 0, 2, '[{"codes":["KINE-176D"],"textExtension":"- Must be taken at the same time as this course."},{"codes":["2nd-year","standing","(25h","or","more","completed)"],"textExtension":"- Must be completed prior to taking this course."}]');
